window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-endocrinologia-end-2"]={"block":"medcurso:medcurso-endocrinologia-end-2","label":"Medcurso · END 2","count":428,"questions":[{"id":"medcurso-endocrinologia-end-2-345456","number":"345456","sourceNumber":"345456","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Nos indivíduos com diabetes melitus tipo 2 (DM2), a necessidade de insulina aumenta à\nmedida que a doença avança no tempo, devido ao declínio progressivo da função da célula ?.\n\nAnalise as afirmativas abaixo sobre a terapia baseada em insulina: 1. Está indicada em momentos\ndo tratamento farmacológico em que haja\nintercorrências que causem descompensação da\nhiperglicemia. 2. Está indicada quando outras opções de tratamento tiverem falhado ou estiverem\ncontraindicadas e persistir a hiperglicemia. 3. Poderá ser considerada quando a HbA1c estiver\nacima de 9,0%, seja em combinação com outros agentes ou em monoterapia. 4. É recomendada\nna presença de sintomas de hiperglicemia, incluindo polidipsia, poliúria e perda de peso, devendo\nesta ser substituída posteriormente, respeitando as limitações da função renal e os efeitos adversos\ndos demais anti-hiperglicemiantes. Assinale a alternativa que indica todas as afirmativas\nCORRETAS:","options":{"A":"São corretas apenas as afirmativas 1 e 2.","B":"São corretas apenas as afirmativas 1, 2 e 3.","C":"São corretas apenas as afirmativas 1, 2 e 4.","D":"São corretas as afirmativas 1, 2, 3 e 4."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-345473","number":"345473","sourceNumber":"345473","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre alterações de perfil lipídico e relação com hábitos alimentares marque a\nalternativa INCORRETA:","options":{"A":"O alvo de tratamento das dislipidemias visa um LDL-colesterol abaixo de 70, independentemente\nda idade e de outros fatores de risco\ncardiovasculares.","B":"O hipotireoidismo pode ser uma causa secundária de dislipidemia.","C":"Muitas medicações incluindo diuréticos tiazídicos e hormônios podem influenciar os níveis\nsanguíneos de colesterol e triglicerídeos.","D":"Adoção de medidas saudáveis de estilo de vida como atividade física regular e diminuição do\netilismo auxiliam no tratamento das dislipidemias."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-343806","number":"343806","sourceNumber":"343806","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"José das Neves, de 60 anos, chega à Unidade Básica de Saúde e fala ao enfermeiro\nque deseja marcar uma nova consulta, pois já\npassaram 3 meses da anterior. O enfermeiro, que já\nsabe que José é portador de diabetes e já se trata na Unidade há 4 anos, desde que se mudou\npara o bairro, marca a consulta para o dia seguinte na parte da tarde. No dia seguinte na hora\nmarcada, seu José comparece e o médico o recebe com simpatia, perguntando como ele tinha\npassado os meses anteriores. Fala que manteria o tratamento, mas que estava na hora de realizar\nnovos exames de sangue para acompanhar seu quadro, que vinha sendo controlado já há 3 anos,\nquando iniciou nova medicação. Considerando ainda o caso clínico da questão anterior, assinale\ndos testes abaixo, aquele que proporciona ao médico uma visão mais a longo prazo de controle\nglicêmico do paciente, sendo atualmente uma valiosa medida para manejo dos pacientes com\nDiabetes Mellitus.","options":{"A":"Medida da glicemia capilar por glicosímetro em jejum.","B":"Dosagem da Glicose em laboratório em jejum.","C":"Dosagem sérica de Hemoglobina glicada.","D":"Teste de tolerância à glicose."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-343844","number":"343844","sourceNumber":"343844","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Não é característica Fisiopatológica do Diabetes Mellitus tipo II:","options":{"A":"Deficiência relativa de insulina para manter os níveis de glicose normais, caracterizada pela\nresistência insulínica.","B":"Anti GAD negativo.","C":"Presença de Acantose Nigrans.","D":"Deficiência absoluta de insulina para manter os níveis normais de glicose no sangue."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-291757","number":"291757","sourceNumber":"291757","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Considerando as Diretrizes da Sociedade Brasileira de\nDiabetes, em relação ao tratamento desse paciente, é correto afirmar:","options":{"A":"A dose total diária de insulina, inicialmente, deve ser em torno de 20 a 40 unidades.","B":"A dose de insulina basal deve ser entre 60% a 80% da dose total para evitar hipoglicemia.","C":"Devido à aderência, deve-se optar por administrar a insulina 1 a 2 vezes ao dia.","D":"O paciente não é candidato ao uso de bomba de insulina, por maior risco de hipoglicemia que\napresente."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-291758","number":"291758","sourceNumber":"291758","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Identifique a alternativa que contém uma combinação\nadequada de insulinas para esse paciente.","options":{"A":"Glargina, degludeca.","B":"NPH, glargina.","C":"Lispro, regular.","D":"Glulisina, detemir."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283274","number":"283274","sourceNumber":"283274","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente de 70 anos, deu entrada em unidade de pronto atendimento apresentando\nquadro de confusão mental, sonolência e\nvertigem. Ao exame o paciente se apresenta hipocorado,\ncom turgor cutâneo reduzido e mucosas desidratadas. Acompanhante refere que o paciente é\ndiabético e acerca de duas semanas não tem utilizado medicação de forma adequada. No\nmomento, a glicemia capilar é de 420 mg/dL. Em relação ao quadro clínico assinale a alternativa\ncorreta quanto à conduta.","options":{"A":"Deve-se iniciar insulina regular em bomba de infusão.","B":"Deve-se iniciar 15 unidades de insulina regular.","C":"Deve-se iniciar 0,15U/kg de insulina NPH.","D":"Deve-se iniciar hidratação venosa com soro fisiológico."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-291759","number":"291759","sourceNumber":"291759","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Indique a orientação que deve ser fornecida ao paciente em\nrelação à insulinoterapia:","options":{"A":"A insulina que ainda não foi aberta deve ser mantida no congelador, em torno de -10o C a -20o\nC.","B":"Após aberta, a insulina pode ser mantida em temperatura ambiente por 30 dias.","C":"A aplicação da insulina deve ser realizada sempre no abdome, na região próxima ao umbigo.","D":"A insulina de ação rápida nunca deve ser combinada com uma de ação intermediária na mesma\nseringa."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283275","number":"283275","sourceNumber":"283275","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente do sexo feminino, 59 anos, com diabetes mellitus tipo 2 em seguimento há 10\nanos com boa adesão à terapia não\nfarmacológica e uso regular de metformina e sulfonilureia há 5\nanos. Comparece para consulta de controle com hemoglobina glicada de 12%. Em relação à\nproposta terapêutica, assinale a alternativa correta.","options":{"A":"Iniciar insulina NPH 0,3UI/kg em dose única à noite.","B":"Iniciar insulina regular 0,3UI/kg em dose única no almoço.","C":"Iniciar insulina regular 0,3UI/kg em dose única à noite.","D":"Iniciar insulina NPH 0,3UI/kg em dose única no almoço."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-281118","number":"281118","sourceNumber":"281118","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem, 45 anos, refere poliúria, polidipsia e emagrecimento de seis quilos, há 4\nmeses. O mesmo faz uso constante de álcool,\ndiariamente, desde os 18 anos de idade. Glicemia\nem jejum de 250 mg/dl, realizada há cinco dias quando foi iniciado 1g de metformina no café da\nmanhã e no jantar. Desde então, apresenta intensa flatulência e diarreia aquosa. Assinale a\nalternativa que apresenta a melhor conduta em relação ao uso da metformina.","options":{"A":"A dose deve ser reduzida pela metade, uma vez que os sintomas tendem desaparecer com o\ntempo.","B":"Deve ser prontamente suspensa.","C":"Manter a dose e suspender caso haja ocorrência de neuropatia periférica.","D":"A dose deve ser mantida, uma vez que o benefício supera o risco do uso.","E":"Realizar avaliação da função renal e, caso a creatinina seja superior a 1,7mEq/L, deve ser\nsuspensa."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-281121","number":"281121","sourceNumber":"281121","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Pelas recomendações atuais o teste de perfil lipídicos de adultos deve se iniciar após\nos:","options":{"A":"20 anos e se repetir a cada 5 anos.","B":"18 anos e se repetir a cada 2 anos.","C":"25 anos e se repetir a cada 2 anos.","D":"30 anos e se repetir a cada ano.","E":"40 anos e se repetir a cada ano."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-281127","number":"281127","sourceNumber":"281127","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação às dislipidemias, é correto afirmar que:","options":{"A":"A farmacoterapia para otimização de HDL colesterol e triglicerídios tem menos impacto do que a\ndirecionada para LDL colesterol.","B":"Hipotireoidismo, síndrome nefrótica e doença hepática grave são causas identificáveis de\naumento do LDL colesterol.","C":"O paciente com hipercolesterolemia isolada beneficia-se de dieta com restrição de carboidratos\nsimples.","D":"O principal objetivo do tratamento das dislipidemias é a redução do LDL colesterol.","E":"O rastreamento de dislipidemia deve ser feito em pacientes adultos aos 35 anos."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283319","number":"283319","sourceNumber":"283319","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Estando de plantão na UPA, você atende um paciente portador de diabetes devido a\numa lesão no pé esquerdo, com mais de 1 mês\nde evolução, piora referida há 4 dias e nota ferida\nna região plantar e drenagem de secreção purulenta além de halo de eritema com mais de 3 cm.\nPaciente nega dor. Exames laboratoriais informam glicemia de 456 mg/dl, creatinina 1,9 mg/dl e\nleucometria 13.000 cel/mm3. Qual das afirmações abaixo informa a melhor alternativa na condução\ndo caso?","options":{"A":"Tratamento ambulatorial, com antibioticoterapia de largo espectro, ajuste dos hipoglicemiantes\norais e curativos em serviço especializado.","B":"Iniciar antibióticos orais e encaminhar ao serviço de cirurgia vascular de referência.","C":"Suporte clínico com internação hospitalar, antibioticoterapia parenteral e avaliação da\nnefrologia.","D":"Internação hospitalar, antibioticoterapia parental e avaliação cirúrgica."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283366","number":"283366","sourceNumber":"283366","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A metformina é um hipoglicemiante oral amplamente utilizado no tratamento\nfarmacológico do diabetes mellitus tipo 2.\nAnalise as afirmativas abaixo e assinale a alternativa\ncorreta. I. O uso prolongado de metformina pode estar associado à deficiência bioquímica de\nvitamina B1. II. A metformina é o agente farmacológico inicial preferencial para o tratamento do\ndiabetes tipo 2. III. Uma vez iniciada, a metformina deve ser continuada desde que seja tolerada e\nnão contraindicada; outros agentes, exceto a insulina, podem ser adicionados à metformina. IV. A\nterapêutica com metformina para prevenção da diabetes tipo 2 deve ser considerada em indivíduos\ncom pré-diabetes, especialmente para aqueles com IMC? 35 kg/m2, aqueles com idade < 60 anos,\ne mulheres com diabetes mellitus gestacional prévio.","options":{"A":"Apenas as afirmativas II e IV estão corretas.","B":"Apenas as afirmativas I, II e IV estão corretas.","C":"As afirmativas I, II, III e IV estão corretas.","D":"Apenas as afirmativas II e III estão corretas."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-251866","number":"251866","sourceNumber":"251866","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A manifestação mais precoce de doença renal crônica em pacientes portadores de\ndiabetes é a presença de:","options":{"A":"Aumento da creatinina.","B":"Proteinúria nefrótica.","C":"Microalbuminúria.","D":"Fibrose tubulointersticial."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-247154","number":"247154","sourceNumber":"247154","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher de 42 anos de idade com diabete melito insulinodependente por 20 anos,\napresenta retinopatia diabética, protenúria e\ndepuração de creatinina normal. A pessoa arterial é de\n164x108mmhg e um discreto edema tibial é observado. A maneira mais eficiente de se preservar a\nfunção renal dessa paciente é:","options":{"A":"Controle da pressão arterial com inibidores da ECA.","B":"Dieta pobre em proteínas e diurético.","C":"Controle da pressão arterial e dieta pobre em proteínas.","D":"Controle rigoroso da glicemia e diuréticos.","E":"Controle da pressão arterial com bloqueadores dos canais de cálcio."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-247156","number":"247156","sourceNumber":"247156","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação ao controle glicêmico intensivo em pacientes internados, é correto dizer\nque:","options":{"A":"Em geral o uso de antidiabéticos orais pode e deve ser mantido durante o período de internação.","B":"A hipoglicemia associada ao tratamento intensivo não parece ser fator de risco independente\npara mortalidade.","C":"Metas glicêmicas entre 140 e 180 mg/dl, estão associadas a menor mortalidade e ocorrência de\nhipoglicemia.","D":"O uso de terapia intravenosa com insulina não está indicado em pacientes hemodinamicamente\ninstáveis.","E":"O uso de insulina rápida subcutânea em doses fixas é superior e mais seguro que o esquema\nbasal/bolus."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-251910","number":"251910","sourceNumber":"251910","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O risco cardiovascular global deve ser avaliado em cada indivíduo hipertenso, pois\nauxilia na decisão terapêutica e permite uma análise prognóstica. São fatores de risco\ncardiovascular na avaliação do risco adicional no hipertenso:","options":{"A":"Homens com idade ? 55 anos ou mulheres com idade ? 65 anos; tabagismo; triglicerídeos >\n300mg/dl.","B":"Circunferência abdominal ? 100 cm nos homens ou ? 88 cm nas mulheres; IMC ? 30 kg/m2;\nHemoglobina glicada entre 5,7 - 6,4%.","C":"História de doença cardiovascular prematura em parentes de 1° grau Homens < 55 anos ou\nmulheres < 65 anos; Circunferência abdominal ? 102 cm nos homens ou ? 88 cm nas mulheres;\netilismo.","D":"Sexo masculino; História de doença cardiovascular prematura em parentes de 1° grau Homens\n\n< 55 anos ou mulheres < 65 anos; Circunferência abdominal ? 102 cm nos homens ou ? 88 cm nas\nmulheres."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-251911","number":"251911","sourceNumber":"251911","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre o tratamento das dislipidemias, assinale a alternativa INCORRETA:","options":{"A":"A decisão para o início da terapia medicamentosa das dislipidemias depende do risco\ncardiovascular do paciente e do tipo de dislipidemia presente.","B":"Os medicamentos hipolipemiantes costumam ser divididos nos que agem predominantemente\nnas taxas séricas de colesterol e naqueles que\nagem predominantemente nas taxas de TG.","C":"Os fibratos são indicados no tratamento da hipertrigliceridemia endógena quando houver falha\ndas medidas não farmacológicas. Quando os\ntriglicerídeos forem muito elevados (> 300 mg/dL) são\nrecomendados, inicialmente, junto das medidas não farmacológicas.","D":"Na hipercolesterolemia isolada, os medicamentos recomendados são as estatinas, que podem\nser administradas em associação à ezetimiba, à\ncolestiramina e, eventualmente, aos fibratos ou ao\nácido nicotínico."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-247236","number":"247236","sourceNumber":"247236","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre dislipidemias, assinale a alternativa correta.","options":{"A":"Devem fazer parte da dieta as frutas, incluindo o abacate, hortaliças, óleos vegetais, sementes e\ncastanhas e os cereais refinados.","B":"O farelo de aveia é uma importante fonte de fibra insolúvel e, portanto auxilia o tratamento\ndietético da hipercolesterolemia.","C":"A dieta deve ser hipossódica e conter ate 20% de lipídios.","D":"O paciente deve ingerir diariamente 80g de fibras entre solúveis e insolúveis, para efeito\nterapêutico.","E":"O tratamento dietético na hipercolesterolemia prevê em torno de 60% de carboidratos, 15% de\nproteínas e 25% de lipídios, dos quais a gordura saturada não deverá ultrapassar 7%."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-217651","number":"217651","sourceNumber":"217651","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Acerca dos medicamentos usados no tratamento do diabetes tipo 2, assinale a\nalternativa CORRETA.","options":{"A":"Sulfonilureias ocasionam perda de peso.","B":"Tiazolidinedionas associadas à metformina causam hipoglicemia grave.","C":"A metformina tende a melhorar a hipertrigliceridemia e a hiperglicemia de jejum em diabéticos\ntipo 2 obesos, sem promover ganho de peso.","D":"A acarbose pode causar hipoglicemia grave."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-217720","number":"217720","sourceNumber":"217720","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A diabetes melito tipo I (DM1) costuma ser diagnosticada em crianças e adolescentes\nsem preferência por gênero e, mais raramente, em\nadultos. Quanto à DM está CORRETO afirmar\nque:","options":{"A":"Os pacientes com DM1 geralmente são obesos e apresentam predisposição para outras\ndoenças autoimunes, como tireoidite de Hashimoto,\ndoença celíaca, miastenia grave e doença de\nAddison.","B":"A maioria dos casos se inicia abruptamente, com sinais e sintomas típicos: poliúria, polidipsia,\npolifagia e perda de peso, que progredirão\npara desidratação, chegando a cetoacidose diabética,\nse o diagnóstico não for realizado.","C":"O diagnóstico de diabetes melito é realizado com uma dosagem de glicemia de jejum ? 126\nmg/dl (jejum definido por 12 horas sem ingesta calórica).","D":"A forma idiopática é responsável pela maioria dos casos na pediatria."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-217732","number":"217732","sourceNumber":"217732","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente de 52 anos, sexo masculino, IMC = 23 apresentando emagrecimento rápido e\ninexplicável, poliúria, polidipsia e polifagia, vem à consulta para avaliação. Nega qualquer\nproblema\nde saúde até o momento. Você solicita exames de laboratório e chama a atenção uma glicemia de\n282 mg/dl. Com o diagnóstico de diabetes tipo II em mente, além de orientar mudanças no estilo de\nvida e dieta (primeiro passo terapêutico para mais de 80% dos pacientes recém-diagnosticados),\ndeve-se inciar imediatamente o tratamento com:","options":{"A":"Metformina.","B":"Insulina NPH.","C":"Glibenclamida.","D":"Pioglitazona."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183178","number":"183178","sourceNumber":"183178","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 55 anos de idade com história de infarto do miocárdio há 3 meses, com\ndieta de estágio II, exercitando-se\nregularmente em programa de reabilitação cardíaca. Não fuma e\na pressão arterial é de 120/80 mmHg sob terapia com betabloqueador e AAS. Apresenta colesterol\ntotal=240 mg/dl, HDL col.= 55 mg/dl, LDL col,=165 mg/dl e triglicérides= 100 mg/dl. Sua conduta no\ntratamento desse paciente é:","options":{"A":"Iniciar sinvastatina, 20 mg/dia.","B":"Iniciar niacina, 2.000 mg/dia.","C":"Recomendar dieta de estágio III.","D":"Encaminhar a um especialista em lipídeos.","E":"Avaliar membros da família para descartar hipercolesterolemia familiar."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-182686","number":"182686","sourceNumber":"182686","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Qual o diagnóstico de um paciente com glicemia de jejum de 108 mg/dl e após Teste de\nsobrecarga oral de dextrose 75g em 2 horas, resultou 180 mg/dl?","options":{"A":"Sem anormalidades.","B":"Pré-diabetes.","C":"Diabetes mellitus.","D":"Síndrome metabólica."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183167","number":"183167","sourceNumber":"183167","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre a retinopatia diabética, analise. I. Uma das complicações mais comuns, presente\ntanto no diabetes tipo 1 quanto no tipo 2,\nespecialmente em pacientes com longo tempo de doença\ne mau controle glicêmico. II. Os efeitos colaterais decorrentes da fotocoagulação consistem em\nescotomas centrais, dificuldade para leitura, aceleração da catarata e, principalmente, na perda da\nvisão periférica ou na diminuição do campo visual. III. A fisiopatologia das alterações\nmicrovasculares do tecido retiniano está relacionada à hiperglicemia crônica, que leva a alterações\ncirculatórias, como perda do tônus vascular, alteração do fluxo sanguíneo, diminuição da\npermeabilidade vascular e, consequentemente, extravasamentos, edemas e obstrução vascular, a\nqual leva à neovascularização, com vasos frágeis que se rompem, causando hemorragia e\ndescolamento da retina. IV. O exame oftalmológico completo, incluindo oftalmoscopia (direta e\nindireta) e a biomicroscopia da retina sob midríase medicamentosa, é fundamental para a detecção\n(86%) e estadiamento da retinopatia. Estão CORRETAS as afirmativas:","options":{"A":"I, II, III e IV.","B":"I e II, apenas.","C":"Il e III, apenas.","D":"III e IV, apenas.","E":"I, II e IV, apenas."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-159056","number":"159056","sourceNumber":"159056","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"JBS, 12 anos de idade, apresenta diabetes há 5 anos. Faz uso de: insulina glargina 16\nUI pela manhã e insulina lispro 4 UI antes do café, 4 UI antes do almoço e 6 ui antes do jantar.\n\nNega episódios de hipoglicemia. Traz o seguinte esquema de dextro, aferido nos últimos 3 dias: -\nGlicemia de jejum: 108,116,112 mg/dL.; - 2 horas pós-café: 170, 130, 133 mg/dL.; - Antes do\n\nalmoço: 110, 120, 122 mg/dL.; -2 horas após o almoço: 208, 220, 201 mg/dL.; -Antes do jantar: 140,\n\n120, 122 mg/dL.; - 2 horas após o jantar: 242, 238, 231 mg/dL.; Sobre o caso, assinale a alternativa\ncorreta:","options":{"A":"A paciente faz uso de análogos de insulina. A insulina glargina é uma insulina de ação\nprolongada e a lispro é uma insulina de ação\nultrarrápida. A paciente apresenta descontrole das\nglicemias pós-prandiais, e deve aumentar a dose da insulina glargina.","B":"A paciente provavelmente apresenta a dosagem dos Anticorpos anti-GAD ou anti-ilhota\nnegativo.","C":"A paciente apresenta níveis de glicemia basais (jejum) adequados, com descontrole das\nglicemias pós-prandiais.Deve aumentar a dose da lispro pré café e lispro pré almoço.","D":"A vantagem da insulina glargina sobre a insulina NPH está principalmente na meia-vida da\ninsulina glargina, que, por ser maior em\nrelação a NPH, faz com que possa ser aplicada uma vez ao\ndia. A conduta mais adequada seria manter a dose da Insulina glargina e aumentar as doses de\ninsulina lispro antes do almoço e antes do jantar."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-108749","number":"108749","sourceNumber":"108749","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"No 1º dia de pós-operatório de uma paciente submetida à tireoidectomia total ela\napresenta sensação de formigamento peri-oral e sinais de Trosseau e Chvostek positivos. Qual o\ndiagnóstico?","options":{"A":"Lesão do nervo laringeo recorrente;","B":"Hiponatremia;","C":"Hipocalcemia;","D":"Hipocalemia."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-66989","number":"66989","sourceNumber":"66989","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente do sexo feminino com hiperglicemia, obesidade, gibosidade, hipertensão\narterial, estrias violáceas, acne, libido\ndiminuída, hipocalemia e fácies de lua \"cheia\". Tem como\nprincipal e mais prevalente etiologia:","options":{"A":"Adenoma de hipófise.","B":"Uso crônico de glicocorticoides.","C":"Adenoma de suprarrenal.","D":"Tumor ectópico produtor de cortisol."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-50104","number":"50104","sourceNumber":"50104","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Durante um exame médico anual de rotina, foi constatado, em um empresário de 48\nanos, concentração sérica de cálcio 11,5 mg/dl. A\nanamnese colhida não revela quaisquer doenças\nrecentes, sintomas evidentes ou uso de medicações. Ele nega qualquer hábito alimentar pouco\ncomum. Revela também que nos últimos 10 anos eliminou três cálculos renais. Dois dos episódios\nassociaram-se à dor no flanco esquerdo e um com dor à direita. Esses cálculos não foram\nguardados para exame, embora o paciente ache que a cor deles fosse castanho-amarelada ou\nmarrom. Além disso, o paciente admitiu, com relutância, letargia e cansaço fácil nos últimos dois\nanos. Ao exame físico parece saudável. Os únicos achados físicos anormais foram uma discreta\nhipertensão arterial e, no exame oftalmológico, a presença de ceratopatia em faixa. Os exames\nlaboratoriais revelaram os seguintes dados pertinentes: Resultados normais: hemoglobina,\nhematócrito, leucometria, diferencial de leucócitos; VHS; EAS; creatinina e ureia séricos;\neletroforese de proteínas; sódio, potássio e bicarbonato séricos e provas de função hepática.\n\nResultados Anormais: fósforo sérico de 2,3 mg/dl; cloreto sérico de 109 mEq/L; ácido úrico sérico\nde 9 mg/dl; fosfatase alcalina sérica de\n100 UI/L; excreção urinária de cálcio de 320 mg/24 horas.\nSe teve a impressão de que o crânio evidenciava um padrão pontilhado fino, sugestivo de\nnumerosas minúsculas regiões de reabsorção óssea no subperiósteo. Os níveis séricos do PTH\n(Hormônio da Paratireoide) estavam acentuadamente elevados 620 pg/ml, quando o normal é 10 a\n\n65. Com base no CASO CLÍNICO, sua próxima conduta baseada na prevalência da etiologia da\ndoença será:","options":{"A":"Tomografia computadorizada de paratireoides.","B":"Realizar Mielograma.","C":"Urografia excretora.","D":"Dosagem sérica da Vitamina D."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-50112","number":"50112","sourceNumber":"50112","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente se apresenta com amenorreia e galactorreia. Seus níveis de prolactina\nestão elevados. Ela não está e nem nunca esteve\ngrávida. Além de pesquisar a presença de um\nprolactinoma, também é necessário estudar outras causas que levariam ao aumento da prolactina,\ntal como:","options":{"A":"A elevação de Dopamina.","B":"A elevação de Ácido Gama-Aminobutírico (GABA).","C":"A ativação do receptor do tipo II da histamina.","D":"A elevação do Hormônio Liberador da Tireotrofina (TRH)."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-50114","number":"50114","sourceNumber":"50114","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Qual das seguintes substâncias estimula a secreção de GnRH (Hormônio Liberador de\nGonadotrofina)?","options":{"A":"Dopamina.","B":"Betaendorfina.","C":"Norepinefrina.","D":"Serotonina."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-372047","number":"372047","sourceNumber":"372047","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quando o paciente apresenta quadro de Cetoacidose Diabética, a insulina análoga de\nação prolongada (glargina, detemir) ou a insulina\nhumana de ação intermediária (NPH):","options":{"A":"Não podem ser administradas após a recuperação da cetoacidose, antes da descontinuação da\ninsulina IV, para evitar que a insulina adequada esteja disponível quando a insulina IV for\ndescontinuada.","B":"São suspensas após a recuperação da cetoacidose, pois a descontinuação da insulina IV, para\ngarantir que a insulina adequada esteja indisponível quando a insulina IV for descontinuada.","C":"São administradas após a recuperação da cetoacidose, antes da descontinuação da insulina IV,\npara garantir que a insulina adequada esteja disponível quando a insulina IV for descontinuada.","D":"São administradas somente antes da recuperação da cetoacidose, depois da descontinuação da\ninsulina IV, para garantir que a insulina adequada esteja disponível quando a insulina IV for\ndescontinuada."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-372074","number":"372074","sourceNumber":"372074","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A hipofosfatemia leve é um achado comum e geralmente assintomático durante a\nterapia da Cetoacidose Diabética - CAD. Podemos indicar como correto o item:","options":{"A":"Não se indica reposição de sais de fosfato de rotina, em parte devido ao risco de hipocalcemia,\nnão havendo evidências suficientes que demonstrem\na melhora do prognóstico quando em\ncomparação com o não uso.","B":"Sempre está indicado reposição de sais de fosfato de rotina, em parte devido ao risco de\nhipocalcemia, não havendo evidências suficientes que demonstrem a melhora do prognóstico\nquando em comparação com o não uso.","C":"Se indica reposição de sais de fosfato de rotina, em parte devido ao risco de hipercalcemia,\nhavendo evidências suficientes que demonstrem a\nmelhora do prognóstico quando em comparação\ncom o não uso.","D":"Dentro dos protocolos se indica reposição de sais de fosfato de rotina, em parte devido ao risco\nde hipercalcemia, havendo evidências suficientes que demonstrem a melhora do prognóstico\nquando em comparação com o não uso."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-372081","number":"372081","sourceNumber":"372081","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Na Síndrome da Quilomicronemia Familiar - SQF, os quilomícrons, os quilomícrons\nremanescentes e as lipoproteínas ricas em triglicérides não podem ser metabolizados e se\nacumulam no plasma.","options":{"A":"Dessa forma, o acúmulo de triglicérides pode prejudicar o fluxo sanguíneo pancreático e inativar\nprocessos inflamatórios, resultando em pancreatite aguda.","B":"Dessa forma, o acúmulo de triglicérides pode ajudar o fluxo sanguíneo pancreático e ativar\nprocessos inflamatórios, resultando em pancreatite aguda.","C":"Dessa forma, o acúmulo de triglicérides pode prejudicar o fluxo sanguíneo pancreático e ativar\nprocessos inflamatórios, resultando em pancreatite aguda.","D":"Dessa forma, o acúmulo de glicose pode prejudicar o fluxo sanguíneo pancreático e ativar\nprocessos inflamatórios, resultando em pancreatite aguda."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-369509","number":"369509","sourceNumber":"369509","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem, 77 anos de idade, portador de hipertensão arterial sistêmica, diabetes mellitus\ntipo 2, ansiedade e depressão, está sob\ntratamento farmacológico com múltiplas medicações,\nincluindo anti-hipertensivos (losartana e amlodipina) diurético (furosemida), hipoglicemiante orais\n(glibenclamida. metformina,dapaglifozina), ansiolítico (alprazolan) e antidepressivo (venlafaxina).\nO\npaciente mantém boa funcionalidade e cognição mas, durante uma consulta de rotina na Unidade\nBásica de Saúde, relata fadiga constante, fraqueza muscular, câimbras, dificuldade de deambular,\nperda de concentração e episódios ocasionais de tontura. Entre as medicações comumente\nprescritas em regime ambulatorial para diabetes mellitus tipo 2, indique a que aumenta o risco de\nhipoglicemia em idosos como esse, especialmente quando usada em conjunto com outros\nhipoglicemiantes:","options":{"A":"Metformina.","B":"Pioglitazona.","C":"Dapagliflozina.","D":"Glibenclamida."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-343159","number":"343159","sourceNumber":"343159","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em pessoas com DM2 e insuficiência cardíaca IC, em terapia combinada de metformina\ncom inibidores da proteína co-transportadora\nSGLT2 (ISGLT2) e HbA1c acima da meta:","options":{"A":"É recomendado adicionar um terceiro e, se necessário, um quarto fármaco de uso seguro na IC,\npara controle da hiperglicemia.","B":"É recomendado adicionar um terceiro e, nunca um quarto fármaco de uso seguro na IC, para\ncontrole da hiperglicemia.","C":"É recomendado adicionar um terceiro e, se necessário, um quarto fármaco de uso seguro na IC,\nmas não para controle da hiperglicemia.","D":"Nunca é recomendado adicionar um terceiro fármaco de uso seguro na IC, para controle da\nhiperglicemia."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-341077","number":"341077","sourceNumber":"341077","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Menino, 5 anos de idade, é trazido à Emergência com relato de que estava na escola,\napresentou dor abdominal, vomitou e passou a manifestar sonolência e letargia importantes. A\nprofessora assustou-se ao observar respirações longas e profundas. Ao interrogatório sistemático,\na genitora informou que tem observado cansaço e alguma perda de peso há, aproximadamente,\num mês. No momento, Peso: 16,8Kg. Ao exame, Escore de Glasgow (modificado para crianças):\n11; Oximetria de pulso: 99% em uso de O? sob máscara; tempo de enchimento capilar: 3s; FC:\n140bpm; PA: 90x50mmHg. Considerando o caso clínico, indique os exames essenciais que devem\nser realizados de imediato, ainda na Emergência:","options":{"A":"Hemograma e Estudo do Liquor.","B":"Hemograma e Sumário de Urina.","C":"Glicemia capilar, Cetonúria e Hemogasometria.","D":"Glicemia capilar, Hemograma e Hemoculturas."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-341078","number":"341078","sourceNumber":"341078","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Menino, 5 anos de idade, é trazido à Emergência com relato de que estava na escola,\napresentou dor abdominal, vomitou e passou a manifestar sonolência e letargia importantes. A\nprofessora assustou-se ao observar respirações longas e profundas. Ao interrogatório sistemático,\na genitora informou que tem observado cansaço e alguma perda de peso há, aproximadamente,\num mês. No momento, Peso: 16,8Kg. Ao exame, Escore de Glasgow (modificado para crianças):\n11; Oximetria de pulso: 99% em uso de O? sob máscara; tempo de enchimento capilar: 3s; FC:\n140bpm; PA: 90x50mmHg. Indique o dado de história clínica que, se presente, reforçaria a principal\nsuspeita diagnóstica por sua especificidade:","options":{"A":"Febre.","B":"Poliúria.","C":"Inapetência.","D":"Hiperatividade."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-341079","number":"341079","sourceNumber":"341079","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Menino, 5 anos de idade, é trazido à Emergência com relato de que estava na escola,\napresentou dor abdominal, vomitou e passou a manifestar sonolência e letargia importantes. A\nprofessora assustou-se ao observar respirações longas e profundas. Ao interrogatório sistemático,\na genitora informou que tem observado cansaço e alguma perda de peso há, aproximadamente,\num mês. No momento, Peso: 16,8Kg. Ao exame, Escore de Glasgow (modificado para crianças):\n11; Oximetria de pulso: 99% em uso de O? sob máscara; tempo de enchimento capilar: 3s; FC:\n140bpm; PA: 90x50mmHg. Especifique as condutas terapêuticas essenciais para esse paciente,\nimediatamente após a avaliação inicial:","options":{"A":"Reposição volêmica e administração de dobutamina.","B":"Oxigenoterapia e administração de dobutamina.","C":"Reposição volêmica e administração de insulina.","D":"Monitorização do ECG e antibioticoterapia empírica."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-314192","number":"314192","sourceNumber":"314192","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Devido à alta prevalência de Hipercolesterolemia Familiar (HF) na população geral e o\nseu grande impacto nas taxas de doença\ncardiovascular e mortalidade, está correto afirmar que:","options":{"A":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, de uso de\nmedicamentos hipolipemiantes e de doença aterosclerótica prematura, incluindo a idade de\nacometimento.","B":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, de uso de\nmedicamentos hipolipemiantes e de doença aterosclerótica prematura, excluindo a idade de\nacometimento.","C":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, nunca de\nuso de medicamentos hipolipemiantes e de\ndoença aterosclerótica prematura, incluindo a idade de\nacometimento.","D":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, de uso de\nmedicamentos hipolipemiantes e não de doença aterosclerótica prematura, incluindo a idade de\nacometimento."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-314193","number":"314193","sourceNumber":"314193","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os xantomas tuberosos amarelo-alaranjados e os xantelasmas de pálpebras não são\nespecíficos de Hipercolesterolemia Familiar (HF), sendo correto que:","options":{"A":"Não devem ser valorizados quando encontrados em pacientes com idade em torno de 20 a 25\nanos.","B":"Devem ser valorizados quando encontrados em pacientes com idade em torno de 5 a 10 anos.","C":"Devem ser desconsiderados quando encontrados em pacientes com idade em torno de 20 a 25\nanos.","D":"Devem ser valorizados quando encontrados em pacientes com idade em torno de 20 a 25 anos."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-314196","number":"314196","sourceNumber":"314196","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A determinação do perfil lipídico está sujeita a uma série de variações relacionadas:","options":{"A":"Tanto ao método e aos procedimentos utilizados, mas não aos fatores peculiares do indivíduo,\ncomo estilo de vida, uso de medicações e\ndoenças associada.","B":"Tanto ao método e aos procedimentos utilizados como aos fatores peculiares do indivíduo, como\nestilo de vida, uso de medicações e nunca de doenças associada.","C":"Tanto ao método e aos procedimentos utilizados como aos fatores peculiares do indivíduo,\nexcluindo o estilo de vida.","D":"Tanto ao método e aos procedimentos utilizados como aos fatores peculiares do indivíduo, como\nestilo de vida, uso de medicações e doenças associada."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-307033","number":"307033","sourceNumber":"307033","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, 27 anos de idade, comparece à Unidade Básica de Saúde, UBS, para consulta\nde rotina, sem queixas. Nega comorbidades\nconhecidas, tabagismo ou etilismo. Pratica\ncaminhadas 3 vezes na semana, de uma hora. De antecedentes familiares, diz que o pai faleceu de\ninfarto aos 49 anos. Ao exame físico, observam-se xantomas em tendão calcâneo bilateralmente,\nsem outras alterações. IMC: 24 kg/m². Realizados exames laboratoriais, com colesterol total de\n385mg/dL, HDL: 86mg/dL, LDL: 262mg/dL e triglicérides: 92mg/dL. Diante do quadro, Em relação\nao diagnóstico, pode-se afirmar que","options":{"A":"o mais provável é tratar-se de dislipidemia secundária.","B":"os xantomas em tendão calcâneo são sinais patognomônicos de dislipidemia primária.","C":"apesar da dislipidemia, a paciente apresenta baixo risco cardiovascular devido ao HDL elevado.","D":"a paciente possui critérios suficientes para o diagnóstico de hipercolesterolemia familiar."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-307034","number":"307034","sourceNumber":"307034","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, 27 anos de idade, comparece à Unidade Básica de Saúde, UBS, para consulta\nde rotina, sem queixas. Nega comorbidades\nconhecidas, tabagismo ou etilismo. Pratica\ncaminhadas 3 vezes na semana, de uma hora. De antecedentes familiares, diz que o pai faleceu de\ninfarto aos 49 anos. Ao exame físico, observam-se xantomas em tendão calcâneo bilateralmente,\nsem outras alterações. IMC: 24 kg/m². Realizados exames laboratoriais, com colesterol total de\n385mg/dL, HDL: 86mg/dL, LDL: 262mg/dL e triglicérides: 92mg/dL. Diante do quadro, Em relação à\nconduta terapêutica farmacológica, deve-se iniciar o tratamento, preferencialmente, com","options":{"A":"sinvastatina, em dose máxima.","B":"rosuvastatina ou atorvastatina.","C":"pitavastatina ou pravastatina.","D":"sinvastatina associada à ezetimibe."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-307035","number":"307035","sourceNumber":"307035","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, 27 anos de idade, comparece à Unidade Básica de Saúde, UBS, para consulta\nde rotina, sem queixas. Nega comorbidades\nconhecidas, tabagismo ou etilismo. Pratica\ncaminhadas 3 vezes na semana, de uma hora. De antecedentes familiares, diz que o pai faleceu de\ninfarto aos 49 anos. Ao exame físico, observam-se xantomas em tendão calcâneo bilateralmente,\nsem outras alterações. IMC: 24 kg/m². Realizados exames laboratoriais, com colesterol total de\n385mg/dL, HDL: 86mg/dL, LDL: 262mg/dL e triglicérides: 92mg/dL. Diante do quadro, Em relação à\nconduta não farmacológica, pode se afirmar que","options":{"A":"o cateterismo cardíaco deve ser realizado devido ao alto risco cardiovascular.","B":"a avaliação cardiovascular complementar é dispensável por se tratar de paciente jovem.","C":"o xantoma tendinoso, geralmente, é doloroso, devendo ser realizada excisão cirúrgica.","D":"os familiares de primeiro grau, da paciente, devem ser rastreados com perfil lipídico."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-314231","number":"314231","sourceNumber":"314231","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em pacientes com DM estabelecido e microalbuminúria, foi demonstrado que uma\nabordagem multifatorial sobre estilo de vida","options":{"A":"Diminuiu significativamente a morbi-mortalidade Cardiovascular (CV) em comparação ao\ntratamento convencional.","B":"Aumenta significativamente a morbi-mortalidade Cardiovascular (CV) em comparação ao\ntratamento convencional.","C":"Não altera a morbi-mortalidade Cardiovascular (CV) em comparação ao tratamento\nconvencional.","D":"Diminuiu insignificativamente a morbi-mortalidade Cardiovascular (CV) em comparação ao\ntratamento convencional."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-313467","number":"313467","sourceNumber":"313467","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"As variáveis incluídas no escore de risco de Framingham Heart Failure Risk Score são\nidade, sexo, DAC, diabetes, entre outros listados abaixo, indique o item errado:","options":{"A":"Hipertrofia ventricular esquerda não baseada em eletrocardiograma (ECG).","B":"Doença valvar.","C":"Frequência cardíaca.","D":"Pressão Arterial Sistólica (PAS)."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-314234","number":"314234","sourceNumber":"314234","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para a predição do Risco Individual de Doença Arterial Coronária em Pacientes com\nSíndrome Metabólica e Diabetes Mellitus, podemos entender que esta correto o item:","options":{"A":"O DM não é considerado fator de risco Cardiovascular - CV independente tanto em homens\nquanto em mulheres, elevando em cerca de duas\na quatro vezes a probabilidade de manifestar\nDAC, comparativamente àqueles indivíduos sem DM.","B":"O DM é considerado fator de risco Cardiovascular - CV dependente tanto em homens quanto em\nmulheres, reduzindo em cerca de duas a quatro vezes a probabilidade de manifestar DAC,\ncomparativamente àqueles indivíduos sem DM.","C":"O DM é considerado fator de risco Cardiovascular - CV dependente somente em homens ,\nelevando em cerca de duas a quatro vezes a probabilidade de manifestar DAC, comparativamente\nàqueles indivíduos com DM.","D":"O DM é considerado fator de risco Cardiovascular - CV independente tanto em homens quanto\nem mulheres, elevando em cerca de duas a quatro\nvezes a probabilidade de manifestar DAC,\ncomparativamente àqueles indivíduos sem DM."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-275967","number":"275967","sourceNumber":"275967","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Com relação ao diabetes mellitus podemos afirmar que:","options":{"A":"O tipo I e II são causados por fatores autoimunes.","B":"A diferenciação entre os dois tipos é apenas temporal, ou seja, surgem em fases distintas da\nvida.","C":"Em ambas a hiperglicemia está relacionada a resistência periférica a insulina.","D":"O tipo I é de caráter autoimune e no tipo II há resistência periférica a insulina.","E":"Nenhuma das alternativas anteriores."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283712","number":"283712","sourceNumber":"283712","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Considerando as Diretrizes da Sociedade Brasileira de\nDiabetes, em relação ao tratamento desse paciente, é correto afirmar:","options":{"A":"A dose total diária de insulina, inicialmente, deve ser em torno de 20 a 40 unidades.","B":"A dose de insulina basal deve ser entre 60% a 80% da dose total para evitar hipoglicemia.","C":"Devido à aderência, deve-se optar por administrar a insulina 1 a 2 vezes ao dia.","D":"O paciente não é candidato ao uso de bomba de insulina, por maior risco de hipoglicemia que\napresente."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283713","number":"283713","sourceNumber":"283713","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Identifique a alternativa que contém uma combinação\nadequada de insulinas para esse paciente.","options":{"A":"Glargina, degludeca.","B":"NPH, glargina.","C":"Lispro, regular.","D":"Glulisina, detemir."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-278608","number":"278608","sourceNumber":"278608","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Se a vítima de hipoglicemia estiver alerta, o socorrista pode administrar glicose por via\noral dando preferência para utilização de comprimidos de glicose, sendo correto que:","options":{"A":"Comprimidos de glicose que demostraram aliviar os sintomas da hipoglicemia de forma mais\nrápida em comparação a outras várias fontes\nde glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente podem ser utilizadas.","B":"Comprimidos de glicose que demostraram não aliviar os sintomas da hipoglicemia de forma mais\nrápida em comparação a outras várias fontes de glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente podem ser utilizadas.","C":"Comprimidos de glicose que demostraram aliviar os sintomas da hipoglicemia de forma mais\nlenta em comparação a outras várias fontes\nde glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente podem ser utilizadas.","D":"Comprimidos de glicose que demostraram aliviar os sintomas da hipoglicemia de forma mais\nrápida em comparação a outras várias fontes\nde glicose, como sacarose (açúcar comum/de mesa),\nalimentos contendo frutose, balas, entre outras. Na prática, os comprimidos de glicose não são uma\nrealidade disponível, e outras fontes de glicose descritas anteriormente não podem ser utilizadas."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283714","number":"283714","sourceNumber":"283714","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Adolescente, sexo masculino, 15 anos de idade, procura atendimento ambulatorial após\ninternação por cetoacidose diabética, quando foi diagnosticado com diabetes mellitus tipo 1. Teve\nalta com prescrição de insulina e, desde então (da alta médica), tem feito uso irregular, pois tem\nmedo de hipoglicemia. Peso 40Kg. Sem alterações no exame físico no momento. Glicemia capilar\nde 310mg/dL. Diante desse quadro, Indique a orientação que deve ser fornecida ao paciente em\nrelação à insulinoterapia:","options":{"A":"A insulina que ainda não foi aberta deve ser mantida no congelador, em torno de -10°C a -20°C.","B":"Após aberta, a insulina pode ser mantida em temperatura ambiente por 30 dias.","C":"A aplicação da insulina deve ser realizada sempre no abdome, na região próxima ao umbigo.","D":"A insulina de ação rápida nunca deve ser combinada com uma de ação intermediária na mesma\nseringa."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-278081","number":"278081","sourceNumber":"278081","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Inúmeras evidências têm demonstrado que o bom controle glicêmico, geralmente,\napresenta como correta a alternativa.","options":{"A":"Não previne o surgimento das complicações crônicas, que constituem as principais causas de\nmortalidade, morbidade e piora da qualidade de vida do paciente com diabetes.","B":"Previne o surgimento das complicações crônicas, que não constituem as principais causas de\nmortalidade, morbidade e piora da qualidade de vida do paciente com diabetes.","C":"Previne o surgimento das complicações crônicas, que constituem as principais causas de\nmortalidade, morbidade e não da piora da qualidade de vida do paciente com diabetes.","D":"Previne o surgimento das complicações crônicas, que constituem as principais causas de\nmortalidade, morbidade e piora da qualidade de vida do paciente com diabetes."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-280406","number":"280406","sourceNumber":"280406","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O Diabetes leva à depressão devido a fatores orgânicos através de alterações no ritmo\ncircadiano e na arquitetura do sono (diminuição de ondas lentas e aumento de movimentos\noculares) e apneia do sono, alteração do sistema imunológico levando a processos inflamatórios.\nSendo correto que:","options":{"A":"Ativação da imunidade inata, redução de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\nindução de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais.","B":"Ativação da imunidade inata, aumento de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\ninibição de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais.","C":"Ativação da imunidade inata, aumento de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\nindução de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais.","D":"Ativação da imunidade inata, aumento de citocinas pró-inflamatórias e estresse oxidativo,\nresistência à insulina no encéfalo com\nredução de formação de placas amiloides com destruição de\nneurônios e alterando a proteína TAU, responsável pela estrutura dos eixos neuronais."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-279080","number":"279080","sourceNumber":"279080","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para o diagnóstico de Síndrome Metabólica segundo o AdultTreatment Panel III\n(ATP-III), são consideradas as seguintes referências, exceto","options":{"A":"cintura abdominal maior que 88 cm.","B":"triglicerídeos acima de 150 mg/dl.","C":"HDL colesterol acima de 50 mg/dl.","D":"glicose acima de 100 mg/dl."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-280458","number":"280458","sourceNumber":"280458","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um controle menos rígido da glicemia também parece razoável em indivíduos com\nlonga duração do DM que tenham mantido inadequado controle metabólico por longos períodos,\nsendo compatível com o item correto.","options":{"A":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada não estiveram associadas ao aumento da mortalidade.","B":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada estiveram associadas à redução da mortalidade.","C":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada estiveram associadas ao aumento da mortalidade.","D":"O controle intensivo da glicemia em pacientes com DM2, a longa duração da doença e a HbA1c\nelevada estiveram associadas à manutenção da mortalidade."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-278669","number":"278669","sourceNumber":"278669","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Nos países desenvolvidos, o aumento da prevalência ocorrerá principalmente pela\ncontribuição de indivíduos com diabetes nas faixas etárias mais avançadas, em decorrência do\naumento da expectativa de vida e do crescimento populacional, podemos assim concordar com o\nitem:","options":{"A":"Nos países em desenvolvimento, indivíduos de todas as faixas etárias serão atingidos, com\ndestaque para a faixa etária de 60 anos, em que a prevalência deverá duplicar.","B":"Nos países em desenvolvimento, indivíduos de todas as faixas etárias serão atingidos, com\ndestaque para a faixa etária de 20 a 44 anos, em que a prevalência deverá duplicar.","C":"Nos países em desenvolvimento, indivíduos de todas as faixas etárias serão atingidos, com\ndestaque para a faixa etária de 20 a 44 anos, em que a prevalência deverá reduzir.","D":"Nos países em desenvolvimento, indivíduos de faixas etárias mais idosas somente serão\natingidos, com destaque para a faixa etária de\n20 a 44 anos, em que a prevalência deverá duplicar."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-279089","number":"279089","sourceNumber":"279089","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Ainda nos anos 1930, Himsworth e Kerr introduziram o primeiro procedimento-padrão\npara o estudo da resistência à insulina in\nvivo. Demonstrando que pequenas doses de insulina\neram adequadas para indivíduos jovens com formas mais intensas da doença e propensos à\ncetose. Sendo correto o item:","options":{"A":"Indivíduos jovens e magros, menos propensos à cetose, são mais sensíveis à insulina do que os\nmais velhos e obesos não propensos à cetose.","B":"Indivíduos jovens e magros, propensos à cetose, são mais sensíveis à insulina do que os mais\nvelhos e obesos propensos à cetose.","C":"Indivíduos jovens e magros, propensos à cetose, são mais sensíveis à insulina do que os mais\nvelhos e obesos não propensos à cetose.","D":"Indivíduos jovens e magros, propensos à cetose, são mais resistentes à insulina do que os mais\nvelhos e obesos não propensos à cetose."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-280459","number":"280459","sourceNumber":"280459","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A monitorização da glicemia capilar diariamente por indivíduos com DM1 de qualquer\nfaixa etária traz grandes benefícios, sendo\ncorreto o item:","options":{"A":"Por aumentar o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por\npermitir que o paciente entenda os determinantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos ou com a prática de atividade física, por\nexemplo.","B":"Por diminuir o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por não\npermitir que o paciente entenda os determinantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos ou com a prática de atividade física, por\nexemplo.","C":"Por diminuir o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por\npermitir que o paciente entenda os\ndeterminantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos ou com a prática de atividade física, por\nexemplo.","D":"Por diminuir o risco de complicações agudas, tais como cetoacidose e hipoglicemia, e por\npermitir que o paciente entenda os\ndeterminantes de sua glicemia ao correlacionar os resultados\nglicêmicos em tempo real com a ingestão de alimentos, mas não da prática de atividade física, por\nexemplo."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-279093","number":"279093","sourceNumber":"279093","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"É objetivo do tratamento do paciente com diabetes mellitus (DM) o bom controle\nmetabólico, diminuindo, assim, os riscos de\ncomplicações micro e macrovasculares. No arsenal\ndisponível à avaliação do controle glicêmico, podemos indicar como correto o item:","options":{"A":"Encontram-se a hemoglobina glicada (HbA1c), as glicemias capilares diárias (que permitem o\ncálculo da glicemia média estimada), o desvio-padrão da média da glicemia (que ilustra a\nvariabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve dentro da faixa\nrecomendada de glicemia.","B":"Encontram-se a hemoglobina glicada (HbA1c), as glicemias capilares diárias (que não permitem\no cálculo da glicemia média estimada), o\ndesvio-padrão da média da glicemia (que ilustra a\nvariabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve dentro da faixa\nrecomendada de glicemia.","C":"Encontram-se a hemoglobina glicada (HbA1c), as glicemias capilares diárias (que permitem o\ncálculo da glicemia média estimada), o desvio-padrão da média da glicemia (que ilustra a\nvariabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve fora da faixa\nrecomendada de glicemia.","D":"Encontram-se a hemoglobina glicada (HbA1c), e não as glicemias capilares diárias (que\npermitem o cálculo da glicemia média\nestimada), o desvio-padrão da média da glicemia (que ilustra\na variabilidade glicêmica) e o tempo no alvo, isto é, aquele em que o paciente esteve dentro da\nfaixa recomendada de glicemia."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-280463","number":"280463","sourceNumber":"280463","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A automonitorização evita glicemias fora do alvo além de possibilitar ajustes da insulina\nbasal, sendo adequado o item:","options":{"A":"Seja no esquema de múltiplas doses de insulina, mas não para bomba de infusão, para tanto, é\nimportante conhecer os objetivos glicêmicos para cada faixa etária.","B":"Seja no esquema de múltiplas doses de insulina, seja na bomba de infusão, para tanto, é\nimportante conhecer os objetivos glicêmicos para cada faixa etária.","C":"Seja no esquema de múltiplas doses de insulina, seja na bomba de infusão, para tanto, não\nsendo importante conhecer os objetivos glicêmicos\npara cada faixa etária.","D":"Somente no esquema de múltiplas doses de insulina, e não na bomba de infusão, para tanto, é\nimportante conhecer os objetivos glicêmicos para cada faixa etária."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-279095","number":"279095","sourceNumber":"279095","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"HbA1c é considerada o exame padrão-ouro para avaliar o controle metabólico do\nindivíduo com DM1, já que ficou\nconsistentemente demonstrada a relação entre níveis aumentados\ne risco de complicação microvascular. Podemos indicar como correto que:","options":{"A":"A determinação da HbA1c não possibilita estimar quão elevadas as glicemias estiveram nos\núltimos 3 a 4 meses. Tal estimativa torna-se possível pelo fato de a glicose sanguínea ligar-se de\nmaneira irreversível à hemoglobina durante o período de vida da hemácia, que tem essa duração.","B":"A determinação da HbA1c possibilita estimar quão elevadas as glicemias estiveram nos últimos\n3 a 4 meses. Tal estimativa torna- se\npossível pelo fato de a glicose sanguínea ligar-se de maneira\nirreversível à hemoglobina durante o período de vida da hemácia, que tem essa duração.","C":"A determinação da HbA1c possibilita estimar quão elevadas as glicemias estiveram nos últimos\n3 a 4 meses. Tal estimativa torna- se\npossível pelo fato de a glicose sanguínea ligar-se de maneira\nirreversível à hemoglobina durante o período de vida da hemácia, que não tem essa duração.","D":"A determinação da HbA1c possibilita estimar quão elevadas as glicemias estiveram nos últimos\n3 a 4 meses. Tal estimativa torna- se\nimpossível pelo fato de a glicose sanguínea ligar-se de\nmaneira irreversível à hemoglobina durante o período de vida da hemácia, que tem essa duração."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-280467","number":"280467","sourceNumber":"280467","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A automonitorização favorece estratégias a fim de tratar ou evitar glicemias fora do\nalvo, modificar a razão insulina/carboidrato, sendo adequado o item:","options":{"A":"Otimizando a contagem de carboidratos, ou ajustar o fator de sensibilidade e propiciando uma\ncorreção ineficaz da hiperglicemia.","B":"Otimizando a contagem de carboidratos, mas não para ajustar o fator de sensibilidade e\npropiciando uma correção eficaz da hiperglicemia.","C":"Otimizando a contagem de carboidratos, ou ajustar o fator de sensibilidade e propiciando uma\ncorreção eficaz da hiperglicemia.","D":"Otimizando a contagem de carboidratos, ou ajustar o fator de especificidade e propiciando uma\ncorreção eficaz da hiperglicemia."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-278149","number":"278149","sourceNumber":"278149","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A prevalência é um indicador da magnitude da carga atual que a doença representa\npara os serviços de saúde e para a sociedade,\nsendo adequado que:","options":{"A":"Não como um preditor da futura carga que as complicações crônicas do diabetes representarão.","B":"Como um preditor da atual carga que as complicações crônicas do diabetes representarão.","C":"Como um preditor da futura carga que as complicações crônicas do diabetes representarão.","D":"Como um desvinculador da futura carga que as complicações crônicas do diabetes\nrepresentarão."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-278680","number":"278680","sourceNumber":"278680","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Ao realizar o upload dos glicosímetros para análise dos gráficos ou diários de glicemias,\né possível obter duas outras ferramentas para o\ncontrole glicêmico: o desvio-padrão da média das\nglicemias e o tempo no alvo. O desvio-padrão avalia a variabilidade glicêmica, que, idealmente,\ndeve ser inferior a 50 mg/dL ou de, no máximo, 1/3 da média das glicemias. Está correto que:","options":{"A":"Quanto menor o desvio-padrão, mais instável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de muita hipoglicemia.","B":"Quanto maior o desvio-padrão, mais estável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de muita hipoglicemia.","C":"Quanto maior o desvio-padrão, mais instável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de muita hipoglicemia.","D":"Quanto maior o desvio-padrão, mais instável é a glicemia, muitas vezes produzindo HbA1c\npróxima dos valores ideais, às custas de raras hipoglicemias."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-279101","number":"279101","sourceNumber":"279101","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A porcentagem da hemoglobina que sofreu glicação será tanto maior quanto maior a\nconcentração de glicose sanguínea. Esse resultado expresso em porcentagem refere-se à média\ndas glicemias diárias, sendo 50% correspondente ao mês que precedeu o exame, 25% ao mês\nanterior à coleta e 25% ao terceiro e quarto meses anteriores. Sendo adequado o item:","options":{"A":"Em outras situações clínicas, como insuficiência renal ou hepática, que protegem ao\naparecimento de hipoglicemia, o alvo\nglicêmico pode ser um pouco mais elevado do que o habitual.","B":"Em outras situações clínicas, como insuficiência renal ou hepática, que predispõem ao\naparecimento de hipoglicemia, o alvo\nglicêmico pode ser um pouco mais baixo do que o habitual.","C":"Em outras situações clínicas, como insuficiência renal ou hepática, que predispõem ao\naparecimento de hipoglicemia, o alvo\nglicêmico pode ser um pouco mais elevado do que o habitual.","D":"Em outras situações clínicas, como insuficiência renal ou hepática, que não predispõem ao\naparecimento de hipoglicemia, o alvo glicêmico pode ser um pouco mais elevado do que o habitual."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-278682","number":"278682","sourceNumber":"278682","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O conceito de resistência à ação da insulina surgiu no final da década de 1930, quando\npesquisadores administraram extrato de pâncreas purificado a indivíduos com hiperglicemia e\nobservaram surpreendentes resultados quanto à variabilidade de resposta glicêmica entre eles.\n\nSendo correto o item:","options":{"A":"Grandes doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos mais velhos.","B":"Grandes doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos mais jovens.","C":"Mínimas doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos mais velhos.","D":"Grandes doses de insulina eram necessárias para o controle do diabetes leve não cetótico,\nespecialmente em indivíduos femininos e jovens."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249287","number":"249287","sourceNumber":"249287","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O controle intensivo do diabetes, com o objetivo de alcançar valores de glicemia\npróximos aos dos indivíduos sem diabetes, é capaz de prevenir ou pelo menos retardar o\ndesenvolvimento e a progressão da retinopatia. Somente se mostra errado o item:","options":{"A":"Essa proteção mostrou-se persistente em longo prazo.","B":"Dá-se o nome de legado glicêmico a esse fenômeno, obtido pelo controle rigoroso da glicose por\ndeterminado período de tempo.","C":"Esse ?legado? se deve, possivelmente, a alterações epigenéticas ocorridas na fase de mau\ncontrole.","D":"O contrário também não pode ocorrer, e pacientes que apresentaram mau controle podem\ndesenvolver quadros de complicações vasculares leves apenas quando passam a ter,\nposteriormente, bom controle da doença."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249390","number":"249390","sourceNumber":"249390","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Existem indicações relativas para o uso de SICI abaixo listada, qual não faz parte?","options":{"A":"Indivíduos não propensos a ter cetose.","B":"Ocorrência do fenômeno do alvorecer, com níveis de glicemia de jejum > 140 a 160 mg/dl.","C":"Pacientes com hipoglicemias noturnas frequentes e intensas.","D":"Ocorrência do fenômeno do entardecer."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249191","number":"249191","sourceNumber":"249191","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A insulina é medida em unidade internacional (UI). No Brasil, dispõe-se de preparações\nde insulina na concentração U100; indique o item\nerrado:","options":{"A":"A seringa possui escala graduada em unidades adequadas à concentração de insulina U100.","B":"Também é identificada como seringa U100.","C":"Não se deve usar seringa graduada em mL, pelo alto risco de erros no registro da dose.","D":"1 mL de solução tem 10 unidades de insulina."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249194","number":"249194","sourceNumber":"249194","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A absorção de insulina injetada em locais com lipo-hipertrofia é imprevisível, podendo\ncausar hiperglicemias, hipoglicemias inexplicáveis\ne maior variabilidade glicêmica. Sendo adequado\no item:","options":{"A":"Locais com lipo-hipertrofia, a sensibilidade à dor pode aumentar significativamente, o que leva\nalguns indivíduos ao reúso intensificado de agulhas.","B":"Locais com lipo-hipertrofia, a sensibilidade à dor não pode diminuir significativamente, o que\nleva\nalguns indivíduos ao reúso intensificado de agulhas.","C":"Locais com lipo-hipotrofia, a sensibilidade à dor pode diminuir significativamente, o que leva\nalguns indivíduos ao reúso intensificado de agulhas.","D":"Locais com lipo-hipertrofia, a sensibilidade à dor pode diminuir significativamente, o que leva\nalguns indivíduos ao reúso intensificado de agulhas."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249196","number":"249196","sourceNumber":"249196","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considerando como via de aplicação e velocidade de absorção da insulina, como usual\npara aplicação de insulina a subcutânea (SC), podemos concordar que:","options":{"A":"A extensa rede de capilares não possibilita a absorção gradativa da insulina e garante o perfil\nfarmacocinético descrito pelo fabricante.","B":"A extensa rede de capilares possibilita a absorção súbita da insulina e garante o perfil\nfarmacocinético descrito pelo fabricante.","C":"A extensa rede de capilares possibilita a absorção gradativa da insulina e garante o perfil\nfarmacocinético descrito pelo fabricante.","D":"A extensa rede de capilares possibilita a absorção gradativa da insulina e não garante o perfil\nfarmacocinético descrito pelo fabricante."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249325","number":"249325","sourceNumber":"249325","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os fatores de estratificação estão referidos abaixo. Na presença de qualquer um deles,\no paciente com diabetes passa a ser classificado\ncomo de risco alto, independentemente da idade.\nIndique o item com erro:","options":{"A":"Taxa de filtração glomerular estimada < 60 mL/min.","B":"Albuminúria > 10 mg/g de creatinina.","C":"Neuropatia autonômica cardiovascular.","D":"Retinopatia diabética."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249327","number":"249327","sourceNumber":"249327","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Além das dosagens bioquímicas, a eletroforese de lipoproteínas ainda é utilizada por\nalguns médicos na prática clínica. O item com erro é:","options":{"A":"Atualmente, esse exame só é necessário em casos muito isolados, como na constatação da\nausência de lipoproteínas.","B":"Na maioria dos casos, a eletroforese de lipoproteínas não auxilia na tomada de decisões\nclínicas.","C":"O perfil lipídico deve ser determinado em indivíduos com dieta habitual, estado metabólico e\npeso estáveis por pelo menos 2 meses antes da\nrealização do exame.","D":"Devem-se evitar a ingestão de álcool e a prática de atividade física vigorosa nas 72 e 24 horas\nque antecedem a coleta de sangue."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249452","number":"249452","sourceNumber":"249452","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Medidas não farmacológicas como cessação do tabagismo, perda de peso, atividade\nfísica regular, controle dietético e de fatores\nde risco estão indicadas para todos os pacientes com\nDM portadores de doença arterial coronariana (DAC). Nesse contexto, apenas não podemos\nconcordar que:","options":{"A":"a prevenção secundária com uso de AAS e estatinas (com alvo de LDL-C < 70 mg/dl) está\nindicada para todos, salvo contraindicações.","B":"o uso de IECAs está recomendado (salvo contraindicações) para pacientes portadores de DAC e\nDM para redução de risco cardiovascular.","C":"BRAs não devem substituir IECAs quando o paciente apresentar tosse relacionada com o IECA.","D":"betabloqueadores estão indicados para pacientes portadores de DAC e DM com disfunção\nventricular esquerda, observando-se as indicações da diretriz de IC."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249263","number":"249263","sourceNumber":"249263","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A diretriz brasileira para prevenção de doença cardiovascular no diabetes recomenda\nque se utilizem metas de tratamento para o\ncolesterol, apenas um dos itens abaixo está errado,\ndemonstre o item com erro:","options":{"A":"Pode servir de referência tanto o LDL-c como o não HDL-c.","B":"O não HDL-c é recomendado quando os níveis de TG estiverem acima de 300 mg/dL.","C":"A recomendação desta diretriz corresponde tanto a pacientes que nunca passaram por\ntratamento como a pacientes já em uso de estatina.","D":"O objetivo do uso de metas é, principalmente, garantir a adesão ao tratamento, visto que existe\npouca variabilidade de resposta a uma mesma dose de estatina."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249274","number":"249274","sourceNumber":"249274","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro dos cuidados e considerações especiais com ao abordagem do DM2 no idoso,\nnão é correto afirmar que:","options":{"A":"no idoso, além da perda de função da célula beta, ocorre aumento da adiposidade central, com\ndiminuição da massa magra e menor resistência à insulina.","B":"a resistência insulínica no idoso está relacionada, também, à diminuição do tecido muscular, que\npode configurar a sarcopenia, que aumenta o\nrisco de queda e fraturas, de eventos\ncardiovasculares e de perda da autossuficiência.","C":"a sarcopenia é três vezes mais frequente na pessoa com diabetes.","D":"o risco de sarcopenia aumenta com o tempo de diagnóstico, o mau controle glicêmico e o\nsedentarismo."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216221","number":"216221","sourceNumber":"216221","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A principal indicação do transplante isolado de pâncreas (TIP) é a ocorrência de\nhipoglicemia grave ou de internações por hiperglicemia ou cetoacidose, nesse contexto o item\nCORRETO é:","options":{"A":"Apesar do uso de terapia insulínica intensiva, seja com múltiplas doses de insulina, nunca por\nuso de bomba de infusão subcutânea de insulina.","B":"Sem tentar uso de terapia insulínica intensiva, seja com múltiplas doses de insulina, seja por\nuso\nde bomba de infusão subcutânea de insulina.","C":"Apesar do uso de terapia insulínica intensiva, seja com múltiplas doses de insulina, seja por uso\nde bomba de infusão subcutânea de insulina.","D":"Apesar do uso de terapia insulínica não intensiva, seja com múltiplas doses de insulina, seja por\nuso de bomba de infusão subcutânea de insulina."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215235","number":"215235","sourceNumber":"215235","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O Terapia Combinada de insulina com Drogas Antidiabéticas Orais ou DAOs permite\num controle similar ou até superior ao obtido\ncom o uso isolado de insulina, quando ela é\nadministrada. Podemos, apenas, concordar que, a eficácia dos resultados:","options":{"A":"Não dependerá, entretanto, das características clínicas e fisiológicas do paciente, tendo em\nvista, também, os potenciais efeitos colaterais individuais das diferentes drogas orais.","B":"Dependerá, entretanto, das características clínicas e fisiológicas do paciente, tendo em vista,\ntambém, os potenciais efeitos colaterais individuais das diferentes drogas orais.","C":"Independerá, entretanto, das características clínicas e fisiológicas do paciente, tendo em vista,\ntambém, os potenciais efeitos colaterais individuais das diferentes drogas orais.","D":"Dependerá, entretanto, das características clínicas e, mas não fisiológicas do paciente, tendo em\nvista, também, os potenciais efeitos colaterais individuais das diferentes drogas orais."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216294","number":"216294","sourceNumber":"216294","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os princípios básicos do diagnóstico e da classificação de idosos com diabetes não\ndiferem daqueles estabelecidos para indivíduos\nmais jovens. Não podemos apenas concordar que:","options":{"A":"Cabe ressaltar, apenas, que a solicitação do teste oral de tolerância à glicose (TOTG) é ponto\nfundamental para o diagnóstico precoce do diabetes mellitus (DM) nesse grupo etário.","B":"A primeira alteração fisiopatológica a ocorrer é justamente a diminuição da capacidade de\ncaptação da glicose pelos músculos e pelo tecido adiposo no período pós-alimentar.","C":"Aspecto da resistência à insulina relacionado com a sarcopenia, situação frequente no idoso.","D":"A alteração fisiopatológica a ocorrer é justamente a diminuição da capacidade de captação da\nglicose pelos músculos, mas não pelo tecido adiposo no período pós-alimentar."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216313","number":"216313","sourceNumber":"216313","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"As neuropatias diabéticas (NDs) são complicações crônicas em indivíduos com\ndiabetes mellitus (DM), são consideradas presentes corretamente de acordo com o item:","options":{"A":"As NDs são consideradas presentes somente após a exclusão de outras causas, tais como as\npolineuropatias (PNPs) resultantes de doenças metabólicas, sistêmicas, infecciosas, inflamatórias e\nnutricionais, a intoxicação por agentes industriais, drogas e metais, além das neuropatias\nhereditárias.","B":"As NDs são consideradas presentes mesmo após a exclusão de outras causas, tais como as\npolineuropatias (PNPs) resultantes de doenças metabólicas, sistêmicas, infecciosas, inflamatórias e\nnutricionais, a intoxicação por agentes industriais, drogas e metais, além das neuropatias\nhereditárias.","C":"As NDs são consideradas presentes somente após a exclusão de outras causas, tais como as\npolineuropatias (PNPs) resultantes de doenças metabólicas, sistêmicas, infecciosas, inflamatórias e\nnutricionais, a intoxicação por agentes industriais, drogas e metais, mas não das neuropatias\nhereditárias.","D":"As NDs não são consideradas presentes somente após a exclusão de outras causas, tais como\nas polineuropatias (PNPs) resultantes de doenças\nmetabólicas, sistêmicas, infecciosas,\ninflamatórias e nutricionais, a intoxicação por agentes industriais, drogas e metais, além das\nneuropatias hereditárias."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216332","number":"216332","sourceNumber":"216332","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro do quadro clinico de neuropatias diabéticas (NDs), podemos apenas concordar\nque:","options":{"A":"Tendo em vista a possibilidade de acometimento de todos os tipos de fibras nervosas, de todas\nas regiões do organismo, as manifestações\nclínicas não podem ser muito variadas.","B":"Tendo em vista a possibilidade de acometimento de todos os tipos de fibras nervosas, de todas\nas regiões do organismo, as manifestações\nclínicas podem ser muito variadas.","C":"Tendo em vista a possibilidade de acometimento somente de um dos tipos de fibras nervosas,\nde todas as regiões do organismo, as\nmanifestações clínicas podem ser muito variadas.","D":"Tendo em vista a impossibilidade de acometimento de todos os tipos de fibras nervosas, de\ntodas as regiões do organismo, as manifestações clínicas podem ser muito variadas."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215480","number":"215480","sourceNumber":"215480","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Felizmente, nos dias de hoje, com a melhora da expectativa de vida dos pacientes com\nDM1, observam-se cada vez mais indivíduos com DM1 que alcançam faixas etárias geriátricas.\n\nPodemos apenas aceitar como CORRETO:","options":{"A":"Eles, muitas vezes, desenvolvem sobrepeso, mas nunca obesidade; assim, acaba por coexistir a\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes duplo.","B":"Eles, muitas vezes, desenvolvem sobrepeso ou mesmo obesidade; assim, acaba por coexistir a\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes duplo.","C":"Eles, muitas vezes, desenvolvem sobrepeso ou mesmo obesidade; assim, acaba por coexistir a\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes simples.","D":"Eles, muitas vezes, desenvolvem sobrepeso ou mesmo obesidade; assim, acaba por se curar da\nresistência à insulina no que se convencionou chamar de diabetes tipo 1 + 2 ou diabetes duplo."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216226","number":"216226","sourceNumber":"216226","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O reconhecimento precoce e o tratamento das neuropatias diabéticas - NDs são\nimportantes pelos seguintes motivos explicado no item abaixo:","options":{"A":"À medida que progridem, as neuropatias diabéticas - NDs nunca são fatores de risco para\nulcerações nos pés, amputações e desequilíbrio ao andar.","B":"À medida que progridem, as neuropatias diabéticas - NDs tornam-se fatores de risco para\nulcerações nos pés e amputações, sem alterar o equilíbrio ao andar.","C":"À medida que melhoram, as neuropatias diabéticas - NDs tornam-se fatores de risco para\nulcerações nos pés, amputações e desequilíbrio ao andar.","D":"À medida que progridem, as neuropatias diabéticas - NDs tornam-se fatores de risco para\nulcerações nos pés, amputações e desequilíbrio ao andar."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215523","number":"215523","sourceNumber":"215523","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A diferenciação entre os tipos 1 e 2 pode não ser tarefa fácil, principalmente em\npacientes com DM1, observam-se cada vez mais\nindivíduos com DM1 que alcançam elevadas\nfaixas etárias e desenvolvem obesidade; assim, acaba por coexistir a resistência à insulina no que\nse convencionou chamar de diabetes tipo 1 + 2. Podemos aceitar como CORRETO:","options":{"A":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais não há dúvida diagnóstica, a\ndosagem de peptídeo C basal ou\n\napós estímulo com glucagon ou refeição mista pode ser utilizada.","B":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais há dúvida diagnóstica, a\ndosagem de peptídeo C basal ou após estímulo com glucagon ou refeição mista não pode ser\nutilizada.","C":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais há dúvida diagnóstica, a\ndosagem de peptídeo C basal ou após\nestímulo com glucagon ou refeição mista pode ser utilizada.","D":"Nesse cenário, ou seja, apenas em casos selecionados, nos quais há dúvida diagnóstica, a\ndosagem de peptídeo C basal, sem usar estímulo com glucagon ou refeição mista pode ser\nutilizada."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216251","number":"216251","sourceNumber":"216251","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Conforme progridem, as Neuropatias diabéticas ? NDs tornam-se fatores de risco para\nmanifestações clínicas relacionadas com distúrbios cardiovasculares, sendo CORRETO que:","options":{"A":"Assim, podem afetar a qualidade de vida pelas dores neuropáticas frequentemente associadas,\nmas são incapazes de provocar morte súbita por\narritmias cardíacas.","B":"Assim, podem afetar a qualidade de vida pelas dores neuropáticas frequentemente associadas,\nalém da possibilidade de morte súbita por\narritmias cardíacas.","C":"Assim, não podem afetar a qualidade de vida pelas dores neuropáticas frequentemente\nassociadas, e sim causar morte súbita por\narritmias cardíacas.","D":"Assim, podem afetar a qualidade de vida pelas dores neuropáticas frequentemente associadas,\nmas sem possibilidade de morte súbita por\narritmias cardíacas."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215548","number":"215548","sourceNumber":"215548","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O diabetes também tem um relevante impacto econômico nos países e nos sistemas de\nsaúde. Isso decorre de maior utilização dos serviços de saúde, perda de produtividade e cuidados\nprolongados requeridos para tratar suas complicações crônicas, como insuficiência renal, cegueira,\nproblemas cardíacos e pé diabético. Não consideramos apenas o seguinte item que se mostra\nERRADO:","options":{"A":"A maioria dos países despende em casos de diabetes entre 5 e 20% do seu gasto total com\nsaúde.","B":"O diabetes é um importante desafio para os sistemas de saúde e um obstáculo para o\ndesenvolvimento econômico sustentável.","C":"Indivíduos com diabetes apresentam maiores taxas de hospitalizações em comparação com os\nque não têm diabetes, além de menor duração\nda hospitalização para um mesmo problema de\nsaúde.","D":"As hospitalizações consomem parcela significativa dos recursos de saúde."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216277","number":"216277","sourceNumber":"216277","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Sociedade Brasileira de Diabetes (SBD) preconiza uma meta de tratamento\nindividualizada, de acordo com as características\napresentadas anteriormente, sendo necessário\nencontrar um ponto de equilíbrio, evitando-se hipoglicemias frequentes, mas, ao mesmo tempo,\nsem permissividade excessiva de hiperglicemia. Somente não podemos concordar que:","options":{"A":"Comorbidades associadas.","B":"Polifarmácia.","C":"Capacidade de autocuidado.","D":"Risco associado a uma eventual hipoglicemia não deve ser considerado."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215304","number":"215304","sourceNumber":"215304","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A maioria dos estudos compara o uso de insulina em monoterapia com o Tratamento\nCombinado (TC) de insulina com metformina, sulfonilureias ou ambas, por serem as drogas com\nmaior número de anos de utilização e mais amplamente empregadas. O terapia combinada de\ninsulina com o uso de metformina apresenta menor risco de hipoglicemia e de ganho de peso,\npodemos apenas considerar INADEQUADO que.","options":{"A":"DM2, o uso de terapia combinada de insulina com metformina, sulfonilureias ou ambas,\napresenta resultados semelhantes aos da insulinoterapia.","B":"Observando um maior ganho de peso quando se a metformina era adicionada e maior redução\ndo requerimento de insulina com o uso da\nsulfonilureias.","C":"Nos demais parâmetros, em todos os estudos com TC, poucos foram os pacientes que\napresentaram alguma alteração na qualidade de\nvida e nos níveis de lipoproteínas, triglicérides e\noutros lipídios.","D":"Faltam estudos que indiquem as vantagens do TC no desenvolvimento de complicações macro\ne microvasculares."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215194","number":"215194","sourceNumber":"215194","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O diagnóstico de Cetoacidose Diabética (CAD) envolve a caracterização de alterações\nclínicas e laboratoriais. Os principais\nsintomas dessa complicação são, EXCETO","options":{"A":"polidipsia.","B":"Poliúria.","C":"Náuseas e vômitos.","D":"Disúria."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215196","number":"215196","sourceNumber":"215196","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quanto à hidratação no tratamento da cetoacidose diabética, marque a afirmativa\nCORRETA.","options":{"A":"Tanto o soro de manutenção como o soro de reposição é administrado de forma isotônica.","B":"Deve ser realizada com soro hipotônico para evitar a ocorrência de edema cerebral.","C":"Deve ser realizada com correção rápida de hipercalemia.","D":"O soro de manutenção deve ser administrado junto com a solução hipotônica."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215200","number":"215200","sourceNumber":"215200","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quanto aos fatores relacionados à fisiopatologia da cetoacidose diabética (CAD),\nassinale a alternativa CORRETA.","options":{"A":"O aumento do fluxo de água livre do compartimento intracelular para o extracelular, decorrente\nda elevação da osmolaridade\n\nplasmática, leva à hipernatremia.","B":"O aumento do fluxo de água livre do compartimento intracelular para o extracelular, decorrente\nda elevação da osmolaridade plasmática, leva à\nhiponatremia dilucional.","C":"O equilíbrio entre os compartimentos intracelular e extracelular raramente leva à alteração nos\nníveis de sódio.","D":"A elevação de ácidos graxos livres no plasma contribui para o aumento da natremia."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215206","number":"215206","sourceNumber":"215206","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao tratamento da cetoacidose diabética\n(CAD).","options":{"A":"A reposição de insulina pode ser iniciada junto com a fase de expansão ou na segunda hora do\ntratamento, após a expansão inicial.","B":"A administração de insulina regular por via endovenosa e em infusão contínua é recomendada\npelos especialistas.","C":"A infusão endovenosa contínua de insulina deve ser evitada, pois leva à queda brusca de\nglicemia.","D":"A infusão de insulina por via endovenosa, de forma contínua, permite a redução gradual da\nglicemia, com menores riscos de complicações, como hipoglicemia e edema cerebral."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215210","number":"215210","sourceNumber":"215210","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à reposição do bicarbonato no tratamento\nda cetoacidose diabética.","options":{"A":"Atualmente não há indicação para que seja realizada no tratamento da cetoacidose diabética,\nexceto durante a ressuscitação, com o intuito\nde se preservar a ação da insulina.","B":"É considerada um dos recursos que evitam a ocorrência de edema cerebral em crianças.","C":"Pode levar à hipóxia cerebral decorrente da diminuição da afinidade da hemoglobina pelo\noxigênio.","D":"Também pode causar hiponatremia e hipocalemia."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-201752","number":"201752","sourceNumber":"201752","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Conforme a V Diretriz Brasileira de Dislipidemia, qual deve ser a meta de LDL colesterol\nao ser alcançada para uma mulher de 60 anos,\nhipertensa e que foi submetida à angioplastia\ncoronariana percutânea?","options":{"A":"< 160 mg/dl.","B":"< 130 mg/dl.","C":"< 100 mg/dl.","D":"< 70 mg/dl.","E":"< 50 mg/dl."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-212201","number":"212201","sourceNumber":"212201","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"As dislipidemias de causas secundárias são decorrentes do estilo de vida inadequado,\nde certas condições mórbidas, ou de\nmedicamentos. Entre essas causas secundárias encontra-se\no tabagismo, que tipicamente determina a","options":{"A":"redução do HDL-c.","B":"elevação do colesterol total.","C":"elevação dos triglicerídes e do HDL-c.","D":"redução do HDL-c e elevação dos triglicérides.","E":"elevação dos triglicérides e colesterol total associado a redução do HDL-c."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-212209","number":"212209","sourceNumber":"212209","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"P.J.M., 45 anos, assintomático, realizou exames laboratoriais de rotina após consulta\nmédica no posto de saúde. Paciente ficou\npreocupado com o resultado da glicemia de jejum de 138\nmg/dL. Retornou à unidade de saúde e o clínico geral solicitou uma nova glicemia de jejum, cujo\nresultado foi de 155 mg/dL. Dadas as afirmativas a respeito do mecanismo de ação dos\nmedicamentos antidiabéticos, I. As gliptinas aumentam o nível de GLP-1, com aumento da síntese\ne da secreção de insulina, além da redução de glucagon. II. As biguanidas reduzem a produção\nhepática de glicose com menor ação sensibilizadora da ação insulínica. III. As sulfonilureias\naumentam a sensibilidade à insulina em músculo, adipócito e hepatócito. IV. As glitazonas\npromovem retardo da absorção de carboidratos. verifica-se que está(ão) correta(s) apenas","options":{"A":"III.","B":"I e II.","C":"II e IV.","D":"I, II e III.","E":"I, III e IV."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-201776","number":"201776","sourceNumber":"201776","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente, com cinquenta e seis anos de idade, tabagista, diagnosticado com\ndiabetes mellitus há mais de vinte anos, não\ninsulinodependente, hipertenso controlado, em uso de\nanlodipino 10 mg/dia e metformina 850 mg duas vezes ao dia. Os exames laboratoriais com:\nmicroalbuminúria = 300 mg/24 horas; creatinina sérica =1,4 mg/dl; potássio sérico = 4,8 mEq/L e\nhemoglobina glicosilada = 7,5 %. Considerando o caso relatado, assinale a alternativa CORRETA:","options":{"A":"Os níveis de pressão arterial e o hábito de fumar não são fatores de risco para a progressão da\nnefropatia.","B":"A utilização de drogas inibidoras da enzima de conversão da angiotensina ou inibidoras do\nreceptor AT1 da angiotensina está contraindiciada no caso de tendência à hiperpotassemia.","C":"A ausência de elevada excreção urinária de albumina exclui o diagnóstico de nefropatia\ndiabética.","D":"Em pacientes com diabetes tipo II, o aparecimento da nefropatia diabética é muito raro.","E":"Em pacientes com diabetes tipo II, a presença de microalbuminúria é um marcador de risco para\ndoenças cardiovasculares."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216321","number":"216321","sourceNumber":"216321","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Analisando o impacto global do diabetes mellitus e sua epidemiologia, atualmente\npodemos aceitar como CORRETO que vários estudos epidemiológicos","options":{"A":"sugerem um importante papel do meio ambiente nos períodos iniciais da vida, tanto na fase\nintrauterina como nos primeiros anos de vida.","B":"negam um importante papel do meio ambiente nos períodos iniciais da vida, tanto na fase\nintrauterina como nos primeiros anos de vida.","C":"sugerem um importante papel do meio ambiente nos períodos iniciais da vida, mas não na fase\nintrauterina e nos primeiros anos de vida.","D":"sugerem um importante papel do meio ambiente nos períodos iniciais da vida, mas não na fase\nintrauterina."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216342","number":"216342","sourceNumber":"216342","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Na epidemiologia e impacto global do diabetes mellitus está determinado que ocorra\nimportante papel do meio ambiente nos períodos iniciais da vida, assim, podemos apenas\nACEITAR que","options":{"A":"indivíduos com peso elevado ao nascer apresentam níveis plasmáticos mais elevados de\n\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2, e menor da\nsíndrome metabólica.","B":"indivíduos com peso normal ao nascer apresentam níveis plasmáticos mais elevados de\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2 ou de\nsíndrome metabólica.","C":"indivíduos com baixo peso ao nascer não apresentam níveis plasmáticos mais elevados de\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2 ou de\nsíndrome metabólica.","D":"indivíduos com baixo peso ao nascer apresentam níveis plasmáticos mais elevados de\npró-insulina, indicativo de maior risco para o desenvolvimento futuro de diabetes tipo 2 ou de\nsíndrome metabólica."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-216216","number":"216216","sourceNumber":"216216","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Estudos sugerem um importante papel nos períodos iniciais da vida, tanto na fase\nintrauterina como nos primeiros anos de vida. Nesse momento atual, as evidencias INDICAM que\nestudos mais recentes","options":{"A":"evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é maior\nnos nascidos com baixo peso como nos com peso elevado (? 4 kg).","B":"não evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é\nmaior nos nascidos com baixo peso como nos com peso elevado (? 4 kg).","C":"evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é menor\nnos nascidos com baixo peso como nos com peso\nelevado (? 4 kg).","D":"evidenciam uma relação na forma de U, em que o risco de desenvolver diabetes tipo 2 é maior\nnos nascidos com baixo peso como nos com peso elevado (? 2 kg)."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183579","number":"183579","sourceNumber":"183579","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os linfócitos T, embora menos numerosos que os macrófagos no interior do ateroma,\nsão de grande importância na aterogênese.\nSendo assim, assinale a alternativa INCORRETA:","options":{"A":"Mediante interação com os macrófagos, por exemplo, as células T podem se diferenciar e\nproduzir citocinas que modulam o processo inflamatório local.","B":"As moléculas de adesão são responsáveis pela atração de monócitos e linfócitos para a\nintimidade da parede arterial.","C":"As citocinas amplificam a inflamação de enzimas proteolíticas, incapazes de degradar colágeno\ne outros componentes teciduais locais.","D":"Induzidos por proteínas quimiotáticas, os monócitos migram para o espaço subendotelial, onde\nse diferenciam em macrófagos, que por sua vez\ncaptam as LDL-ox, sem controle da quantidade\nrecebida."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183624","number":"183624","sourceNumber":"183624","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Existe considerável variação intraindividual nos lipídios plasmáticos. Estando\nINADEQUADO que:","options":{"A":"Decorre de fatores ambientais como atividade física, mas não variação sazonal.","B":"Tem sido descrita variação de 5% a 10% para o CT e superior a 20% para os TGs,\nparticularmente nos indivíduos que apresentam hipertrigliceridemia.","C":"Esta variação é de certa forma devida à variação analítica.","D":"Decorre de fatores ambientais como dieta."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-180116","number":"180116","sourceNumber":"180116","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"É correto afirmar sobre as manifestações cutâneas observadas no Diabetes Mellitus.","options":{"A":"A necrobiose lipoídica que acomete pacientes\n\ndiabéticos ocorre mais freqüentemente naqueles que são insulino-dependentes.","B":"A úlcera crônica do pé diabético está relacionada, na maioria dos casos, à isquemia vascular\nperiférica.","C":"A Doença Bolhosa (bullosis diabeticorum) é a\ndermatose mais comum em pacientes com diabetes.","D":"A dermopatia diabética manifesta-se por lesões\nacastanhadas nos membros inferiores, mais comum\nnas mulheres.","E":"A infecção fúngica mais comum no diabetes é a\npitiríase vesicolor."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183041","number":"183041","sourceNumber":"183041","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em geral, o acometimento patológico do sistema nervoso é muito amplo e, inúmeras\nvezes, bastante grave no diabetes mellitus (DM).\nMostra-se INADEQUADO o conceito de que","options":{"A":"As principais manifestações clínicas de comprometimento somático são de dormência ou\nqueimação em membros inferiores,\n\nformigamento, pontadas, choques, agulhadas em pernas e pés, desconforto ou dor ao toque de\nlençóis e cobertores e queixas de\n\ndiminuição ou perda de sensibilidade tátil ou dolorosa, apenas.","B":"O diagnóstico das formas mais frequentes de neuropatia diabética baseia-se na caracterização\ndo quadro clínico com os sintomas\n\ne sinais clínicos mais típicos e na realização de testes neurológicos.","C":"Os testes neurológicos básicos envolvem a avaliação de sensibilidade, pesquisa de reflexos\ntendinosos e medidas de pressão\n\narterial (deitado e em pé) e de frequência cardíaca.","D":"É importante destacar que a ausência de sintomas e sinais de parestesia anteriormente\nmencionada, não exclui a neuropatia, pois\n\nalguns pacientes evoluem direto para a perda total de sensibilidade."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183054","number":"183054","sourceNumber":"183054","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os testes neurológicos básicos para diagnóstico das formas mais frequentes de\nneuropatia diabética envolvem a avaliação de\nsensibilidade, pesquisa de reflexos tendinosos e\nmedidas de pressão arterial (deitado e em pé) e de frequência cardíaca. Podemos, apenas, aceitar\no seguinte:","options":{"A":"Medida de pressão arterial sistêmica em posição deitada, apenas. Frequência cardíaca de\nrepouso: sugestiva de disautonomia\n\ncardiovascular quando o valor estiver acima de 100 bpm.","B":"Medida de pressão arterial sistêmica em posições deitada e ortostática (hipotensão postural:\nqueda da pressão arterial sistólica >\n\n20 mmHg 1 min após assumir posição ortostática) Frequência cardíaca de repouso: sugestiva de\ndisautonomia cardiovascular\n\nquando o valor estiver acima de 60 bpm.","C":"Medida de pressão arterial sistêmica em posições deitada e ortostática (hipotensão postural:\nqueda da pressão arterial sistólica >\n\n30 mmHg ao assumir posição ortostática) Frequência cardíaca de repouso: sugestiva de\ndisautonomia cardiovascular quando o\n\nvalor estiver acima de 100 bpm.","D":"Medida de pressão arterial sistêmica em posições deitada e ortostática (hipotensão postural:\nqueda da pressão arterial sistólica >\n\n20 mmHg 1 min após assumir posição ortostática) Frequência cardíaca de repouso: sugestiva de\ndisautonomia cardiovascular\n\nquando o valor estiver acima de 100 bpm."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183636","number":"183636","sourceNumber":"183636","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os inibidores da alfa-glicosidase, como a acarbose, agem inibindo a digestão de\ncarboidratos complexos sendo, entretanto, INCORRETO que:","options":{"A":"Os inibidores da alfa-glicosidase, sendo a acarbose o principal representante desta classe, agem\ninibindo a digestão de carboidratos complexos e, com isso, diminuindo a incursão glicêmica\n\npós-prandial ? sabidamente um risco cardiovascular.","B":"O uso desta classe de medicamentos em pacientes com pré-DM diminui o risco de hipertensão,\nmas não de doença cardiovascular, todavia não\ntem ação aparente no desenvolvimento de\ninsuficiência cardíaca - IC.","C":"Não há estudos randomizados cujo objetivo seja avaliar a ação do uso da acarbose em\npacientes com IC.","D":"Em estudo em ratos, observou-se que o uso de inibidores de alfa-glicosidase (voglibose) levou à\ndiminuição do remodelamento cardíaco e da progressão para insuficiência cardíaca - IC."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183082","number":"183082","sourceNumber":"183082","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sabe-se que uma grande proporção dos leitos hospitalares e sem emergências e\nenfermarias nos países em desenvolvimento é ocupada por pé diabético e a causa mais comum de\ninternações prolongadas. Podemos aceitar como CORRETO que,","options":{"A":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular e do feedback da\n\npercepção de posição pelos receptores nas pernas e nos pés e, em estágios precoces ocorre\nfraqueza muscular e alterações\n\nestruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às fibras\nnervosas finas (tipos C e delta)\n\npela exposição rápida à hiperglicemia associada a fatores cardiovasculares.","B":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular e do feedback da\n\npercepção de posição pelos receptores nas pernas e nos pés e, em estágios avançados, fraqueza\nmuscular e alterações\n\nestruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às fibras\nnervosas finas (tipos C e delta)\n\npela exposição prolongada à hiperglicemia associada a fatores cardiovasculares.","C":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular, sem alterar o\n\nfeedback da percepção de posição pelos receptores nas pernas e nos pés e, em estágios\navançados, fraqueza muscular e\n\nalterações estruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às\nfibras nervosas finas (tipos C\n\ne delta) pela exposição prolongada à hiperglicemia associada a fatores cardiovasculares.","D":"Ocorre comprometimento das fibras grossas (beta, A alfa), com perda da propriocepção, do\nmovimento articular e do feedback da\n\npercepção de posição pelos receptores nas pernas e nos pés e, em estágios avançados, fraqueza\nmuscular e alterações\n\nestruturais dos pés pelo comprometimento motor. A insensibilidade resulta do agravo às fibras\nnervosas finas (tipos C e delta)\n\npela exposição aguda à hiperglicemia associada a fatores cardiovasculares."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183639","number":"183639","sourceNumber":"183639","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Neuropatia Autonômica Diabética (NAD) é uma complicação pouco reconhecida,\napesar da sua grande importância clínica e do\nimpacto negativo na morbimortalidade de pacientes\ncom DM. Quando detectada NAD sintomática, estima-se mortalidade cardiovascular de 50% em\ncinco anos. Estando equivocada, somente, a seguinte alternativa:","options":{"A":"O Sistema Nervoso Autônomo (SNA) é acometido de forma ampla, no setor simpático.","B":"A doença pode ser assintomática, diagnosticada apenas em exames complementares. A\nmanifestação clínica é resultante da disfunção de um ou mais órgãos (cardiovascular,\ngastrointestinal, genitourinário, sudomotor e ocular).","C":"Os sinais e sintomas clássicos da disautonomia cardiovascular são: taquicardia em repouso,\nhipotensão ortostática, pré-síncope, síncope,\nlabilidade hemodinâmica durante cirurgias, isquemia\nmiocárdica silenciosa e baixa tolerância ao exercício físico.","D":"Outros sintomas correlatos são resultantes da gastroparesia, da hipomotilidade dos cólons."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183125","number":"183125","sourceNumber":"183125","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Alguns estudos também sugerem que o bom controle metabólico pode melhorar a\nneuropatia já estabelecida, além disso, têm sido indicadas outras medidas terapêuticas. Sendo que\no bom controle metabólico do diabetes é o principal fator preventivo da neuropatia. Podemos,\napenas, aceitar que","options":{"A":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhipoglicemia, é a produção de superóxidos\n\npela cadeia de transporte mitocondrial de elétrons, que podem ser revertidos pela ativação da\ntranscetolase, uma enzima\n\ndependente dos níveis de tiamina, a benfotiamina pode representar uma opção de terapêutica.","B":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhiperglicemia, é a produção de superóxidos\n\npela cadeia de transporte mitocondrial de elétrons, que podem ser revertidos pela ativação da\ntranscetolase, uma enzima\n\ndependente dos níveis de tiamina, a benfotiamina pode representar uma opção de terapêutica.","C":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhiperglicemia, não é a produção de\n\nsuperóxidos pela cadeia de transporte mitocondrial de elétrons. Esses podem ser revertidos pela\nativação da transcetolase, uma\n\nenzima dependente dos níveis de tiamina, a benfotiamina pode representar uma opção de\nterapêutica.","D":"Uma vez que a base patológica geral das alterações no metabolismo, causadas pela\nhiperglicemia, é a produção de superóxidos\n\npela cadeia de transporte mitocondrial de proteínas, que podem ser revertidos pela ativação da\ntranscetolase, uma enzima\n\ndependente dos níveis de tiamina, a benfotiamina pode representar uma opção de terapêutica."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183050","number":"183050","sourceNumber":"183050","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Neuropatia diabética é o distúrbio neurológico demonstrável clinicamente ou por\nmétodos laboratoriais em pacientes diabéticos. A\npresença de neuropatia autonômica está\nassociada a aumento significativo de mortalidade na população diabética acometida. Podemos,\napenas, indicar como um conceito INADEQUADO o item:","options":{"A":"Neuropatia diabética é o distúrbio neurológico demonstrável clinicamente ou por métodos\nlaboratoriais em pacientes diabéticos, quando excluídas outras causas de neuropatia.","B":"O acometimento patológico na neuropatia diabética geralmente é amplo no organismo,\napresentando-se de duas formas principais:\npolineuropatia sensorimotora simétrica e neuropatia\nautonômica (cardiovascular, respiratória, digestiva e geniturinária).","C":"O bom controle metabólico do diabetes reduz apenas intensidade da lesão neurológica.","D":"Os testes neurológicos básicos envolvem a avaliação de sensibilidade, pesquisa de reflexos\ntendinosos e medidas de pressão arterial (deitado e em pé) e frequência cardíaca."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183618","number":"183618","sourceNumber":"183618","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Neuropatia Autonômica Diabética (NAD) é uma complicação de grande importância\nclínica e do impacto negativo na\nmorbimortalidade de pacientes com DM. NÃO podemos apenas\nconcordar que:","options":{"A":"Os fatores de risco para NAD são tempo de doença e controle glicêmico.","B":"A neuropatia mais comumente relacionada com a NAD é a polineuropatia periférica (PNP)\nclássica (simétrica, distal e com\n\npredomínio sensitivo).","C":"É recomendado investigação da NAD em todos os pacientes com diagnóstico na DM2 e após\ndez anos no DM1.","D":"No seguimento, os exames devem ser feitos anualmente."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-182750","number":"182750","sourceNumber":"182750","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma das premissas mais importantes é de que a decisão sobre o uso de estatinas em\npacientes com diabetes deve basear-se na estratificação do risco cardiovascular. Somente\npodemos CONCORDAR que, estudos recentes mostram que nem todos os pacientes com diabetes\nsão","options":{"A":"de alto risco, e quase 30% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco é questionável e tende a levar ao\nsupertratamento.","B":"de alto risco, e quase 60% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco é questionável e tende a levar ao\nsupertratamento.","C":"de médio risco, e quase 30% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco é questionável e tende a levar ao\nsupertratamento.","D":"de alto risco, e quase 30% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco não é questionável e tende a levar ao\nsupertratamento."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183631","number":"183631","sourceNumber":"183631","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Neuropatia Autonômica Diabética (NAD) é uma complicação clínica de impacto\nnegativo na morbimortalidade de pacientes com DM. Sendo ADEQUADO o seguinte conceito:","options":{"A":"Trata-se de uma polineuropatia de fibras grossas, cujo mecanismo é multifatorial ? estresse\noxidativo, disfunção de microcirculação por perda\nde óxido nítrico e lesão da célula de Schwann por\nacúmulo de radicais livres.","B":"Trata-se de uma polineuropatia de fibras finas, cujo mecanismo é multifatorial ? estresse\nreplicativo, disfunção de microcirculação por perda\nde óxido nítrico e lesão da célula de Schwann\npor acúmulo de radicais livres.","C":"Trata-se de uma polineuropatia de fibras finas, cujo mecanismo é multifatorial ? estresse\noxidativo, disfunção de microcirculação por\nperda de óxido nítrico e lesão da célula de Schwann por\nacúmulo de radicais livres.","D":"Trata-se de uma polineuropatia de fibras finas, cujo mecanismo é multifatorial ? estresse\noxidativo, disfunção de microcirculação por perda\nde óxido nítroso e lesão da célula de Schwann\npor acúmulo de radicais livres."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-181363","number":"181363","sourceNumber":"181363","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Senhora branca, 65 anos, há 10 anos hipertensa, com infecção urinária de repetição.\nEm uso de captopril. Queixa-se de\nemagrecimento, polidipsia, polifagia e poliúria. Ao exame físico,\nbom estado geral, peso 60 kg, pressão arterial sistêmica 150 x 85 mmHg; FC 65 bpm. Nos exames\nlaboratoriais observamos: sumário de urina com glicosúria; Hemoglobina 12 g/dL, hematócrito 36%;\nglicemia de jejum 260 mg/dL; hemoglobina glicada 11%; creatinina 2,5 mg/dl. Qual a melhor opção\nterapêutica, além de recomendações para modificação do estilo de vida?","options":{"A":"Insulina.","B":"Metformina.","C":"Glimepirida.","D":"Dapagliflozina.","E":"Clorpropamida."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-181339","number":"181339","sourceNumber":"181339","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Qual paciente é considerado pré-diabético, conforme os critérios propostos pela\nAmerican Diabetes Association em 2017?","options":{"A":"Homem, 38 anos, com glicemia de 150 mg/dL, após jejum de 8 h em duas ocasiões.","B":"Homem, 56 anos, com glicemia 2 h, após ingestão de uma sobrecarga de 75 g de glicose anidra,\ndissolvida em água de 210 mg/dL.","C":"Homem, 65 anos, com glicemia 2 h, após sobrecarga com 75 g de glicose de 160 mg/dL.","D":"Mulher, 70 anos, que da entrada na emergência com queixa de perda ponderal e fadiga e\nglicemia 230 mg/dL.","E":"Mulher, 48 anos, com hemoglobina glicada (A1C) de 8%."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183576","number":"183576","sourceNumber":"183576","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Diversos algoritmos e escores de risco baseados em estudos populacionais foram\ncriados nas últimas décadas, mas,\nconsiderando a ausência de dados brasileiros para uma\navaliação mais precisa do Risco Cardiovascular CV na nossa população, deve-se evitar o uso de\num único escore de risco para basear as decisões terapêuticas. É CORRETO que, o risco\nCardiovascular CV global","options":{"A":"deve ser avaliado em cada indivíduo hipertenso, pois auxilia na decisão terapêutica e permite\numa análise prognóstica. A identificação dos\nindivíduos hipertensos que estão mais predispostos às\ncomplicações CV, especialmente infarto do miocárdio e AVE, é fundamental para uma orientação\nterapêutica mais agressiva.","B":"não deve ser avaliado em cada indivíduo hipertenso, pois não auxilia na decisão terapêutica e\npermite uma análise prognóstica. A identificação dos indivíduos hipertensos que estão mais\npredispostos às complicações CV, especialmente infarto do miocárdio e AVE, é fundamental para\numa orientação terapêutica mais agressiva.","C":"deve ser avaliado em cada indivíduo hipertenso, pois auxilia na decisão terapêutica e permite\numa análise prognóstica. A identificação dos\nindivíduos hipertensos que estão mais predispostos às\ncomplicações CV, especialmente infarto do miocárdio e AVE, não é fundamental para uma\norientação terapêutica mais agressiva.","D":"deve ser avaliado em cada indivíduo hipertenso, pois auxilia na decisão terapêutica e permite\numa análise prognóstica. A identificação dos\nindivíduos hipertensos que estão mais predispostos às\ncomplicações CV, especialmente infarto do miocárdio e AVE, é fundamental para uma orientação\nterapêutica menos agressiva."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183108","number":"183108","sourceNumber":"183108","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Organização Mundial da Saúde passou a recomendar redução de açúcares e de\ncarboidratos, a partir de 2015, o consumo máximo de 5% em Kcal do valor energético da dieta na\nforma de açúcares de adição, nos quais se incluem a sacarose e o xarope de milho. Sobre isso,\nassinale o item INADEQUADO:","options":{"A":"Tanto a sacarose quanto os xaropes são constituídos por aproximadamente partes iguais de\nfrutose e glicose, os quais são metabolizados de forma diferente.","B":"Enquanto existe um mecanismo celular de feedback de regulação da glicose mediado pela\nfosfofrutoquinase, para a produção de piruvato e, consequentemente, de acetil-CoA e ácidos\ngraxos, o mesmo mecanismo não ocorre para metabolização da frutose, que é metabolizada pela\nfrutoquinase.","C":"Desta forma, a frutose gera ácidos graxos mais rapidamente do que a glicose, aumentando tanto\no depósito de gordura hepática, como o aumento\nda produção de VLDL.","D":"Estudos mostram que o consumo superior a 50 g de frutose ao dia abaixa o TG pós-prandial."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-182806","number":"182806","sourceNumber":"182806","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A análise dos níveis de TG sem jejum prévio fornece informações importantes sobre\nlipoproteínas remanescentes associadas com risco aumentado de doença coronária, estando\nINCORRETO apenas que:","options":{"A":"Níveis elevados de TG se associam frequentemente a elevados níveis de HDL-c.","B":"A avaliação de Triglicérides TG é determinada por técnica enzimática.","C":"A grande variabilidade biológica dos TG é a principal fonte de oscilações nos seus resultados.","D":"A técnica enzimática é método preciso e de baixo custo."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183120","number":"183120","sourceNumber":"183120","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Atualmente, as recentes diretrizes e guias internacionais apontam para os benefícios de\npadrões alimentares saudáveis, como demonstrado nos estudos que testaram a eficiência da Dieta\ndo Mediterrâneo, nos quais a matriz alimentar assume papel de destaque. Somente NÃO podemos\nconsiderar adequada uma das alternativas abaixo, assinale-a.","options":{"A":"Ocorre relevância de se manterem quantidades moderadas de gordura na dieta, eliminar ácidos\ngraxos trans, controlar o consumo de saturados, priorizar poliinsaturados e monoinsaturados,\nreduzir açúcares e incluir carnes magras, frutas, grãos e hortaliças na dieta.","B":"O alcance das metas nutricionais no tratamento é variável e depende da adesão à dieta e às\ncorreções no estilo de vida, como perda de peso, e pode resultar na redução de 20% da\nconcentração plasmática de TG.","C":"Além do controle de calorias na dieta (déficit de 500 a 1.000 Kcal), enfatiza-se a relevância da\nqualidade dos nutrientes em aspectos relacionados ao desenvolvimento da obesidade, como\nsaciedade, resposta insulínica, lipogênese hepática, adipogênese, gasto energético e microbiota.","D":"O consumo de bebida alcoólica é recomendado para indivíduos com hipertrigliceridemia, por não\ninterferir. Paradoxo francês."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183113","number":"183113","sourceNumber":"183113","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um consumo excessivo de etanol potencializa a elevação da trigliceridemia, mas ocorre\nalguma divergência no impacto da ingestão de etanol nos Triacilgliceróis (TAG) em situações de\nconsumo moderado (até 30g/dia). Sobre isso, podemos considerar INADEQUADO que:","options":{"A":"O consumo de bebida alcoólica não é recomendado para indivíduos com hipertrigliceridemia.","B":"A inibição da lipase das lipoproteínas pelo excesso de etanol e o cosequente aumento na\nhidrólise de quilomícrons parecem justificar a lipemia induzida pelo etanol.","C":"O produto da metabolização do álcool é a Acetilcoenzima A (acetil-CoA), principal precursora da\nsíntese de ácidos graxos.","D":"A combinação de um consumo excessivo de etanol e ácidos graxos saturados potencializa a\nelevação da trigliceridemia."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-182730","number":"182730","sourceNumber":"182730","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A identificação dos indivíduos hipertensos que estão mais predispostos às\ncomplicações Cardiovasculares ? CV, especialmente\nInfarto do Miocárdio e AVE, é fundamental\npara uma orientação terapêutica mais agressiva. Sobre isso, assinale a alternativa INCORRETA:","options":{"A":"O risco Cardiovascular global deve ser avaliado em cada indivíduo hipertenso, pois auxilia na\ndecisão terapêutica e permite uma análise prognóstica .","B":"Diversos algoritmos e escores de risco baseados em estudos populacionais foram criados nas\núltimas décadas, mas, considerando a ausência de dados brasileiros para uma avaliação mais\nprecisa do risco CV na nossa população, deve-se evitar o uso de um único escore de risco para\nbasear as decisões terapêuticas.","C":"Modelos multifatoriais de estratificação de risco podem ser utilizados para uma classificação de\nrisco individual mais precisa.","D":"Informar ao paciente os seus Fatores de Risco - FR pode piorar a eficiência das medidas\nfarmacológicas e não-farmacológicas para redução do risco global."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183123","number":"183123","sourceNumber":"183123","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"As diferentes fontes de ômega 3, por meio da diminuição da lipogênese hepática e da\nLPL, contribuem de forma significativa com a redução de triglicerídeos, somente sendo\nINADEQUADO o conceito de que:","options":{"A":"Os ácidos graxos saturados da dieta relacionam-se com a elevação da trigliceridemia, por\ndiminuírem a lipogênese hepática e a secreção de VLDL.","B":"É recomendada a inclusão de poli e monoinsturados. O ácido Alfalinolenico (ALA) produz\npequenas quantidades endógenas de EPA e DHA, e também\nexerce ação cardioprotetora.","C":"Para indivíduos com níveis de TG muito altos, se recomenda uma redução significativa em\ngordura saturada, o que diminui o risco de pancreatite.","D":"Dentre os ácidos graxos poliinsaturados, os da série ômega 3 são reconhecidos pela atividade\ncardioprotetora."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183037","number":"183037","sourceNumber":"183037","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A análise do ECG pode complementar a avaliação cardiológica e permitir a identificação\nde pacientes com alto risco cardíaco operatório.\nSendo INADEQUADO, apenas, o seguinte:","options":{"A":"O ECG proporciona a detecção de arritmias, distúrbios de condução, isquemia miocárdica ou\nInfarto Agudo do Miocárdio (IAM) prévio, sobrecargas ventriculares e alterações decorrentes de\ndistúrbios eletrolíticos ou de efeitos de medicamentos.","B":"A aplicação de rotina de um teste com especificidade limitada pode levar à ocorrência de\nresultados falso-positivos em pacientes\n\nassintomáticos, uma vez que as alterações eletrocardiográficas costumam ser causa de\npreocupação da equipe cirúrgica e anestésica\ne, muitas vezes, podem levar ao cancelamento\ndesnecessário da operação.","C":"As anormalidades encontradas no ECG tendem a aumentar com a idade e a existência de\ncomorbidades.","D":"Um traçado eletrocardiográfico basal não se mostra importante para a avaliação comparativa no\nperioperatório em pacientes com alto risco de ocorrência de eventos cardiovasculares."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183044","number":"183044","sourceNumber":"183044","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A aterosclerose é uma doença inflamatória crônica de origem multifatorial, que ocorre\nem resposta à agressão endotelial, acometendo\nprincipalmente a camada íntima de artérias de\nmédio e grande calibre. Sendo INADEQUADO que:","options":{"A":"em geral, as lesões iniciais, denominadas estrias gordurosas, formam-se ainda na infância e\ncaracterizam-se por acúmulo de\n\ncolesterol em macrófagos.","B":"com o tempo, mecanismos protetores levam à redução do tecido matricial, que circunda o núcleo\nlipídico mas, na presença de\n\nsubtipos de linfócitos de fenótipo mais inflamatório, a formação do tecido matricial se reduz.","C":"com o tempo, mecanismos protetores levam ao aumento do tecido matricial, que circunda o\nnúcleo lipídico.","D":"com o tempo, mecanismos protetores levam ao aumento do tecido matricial, na presença de\nsubtipos de linfócitos de fenótipo\n\nmais inflamatório."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183061","number":"183061","sourceNumber":"183061","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A formação da placa aterosclerótica inicia-se com a agressão ao endotélio vascular por\ndiversos fatores de risco, como dislipidemia, hipertensão arterial ou tabagismo. Sendo\nADEQUADO, apenas, que o depósito de lipoproteínas","options":{"A":"na parede arterial, processo secundário no início da aterogênese, ocorre de maneira\nproporcional à concentração dessas lipoproteínas no plasma.","B":"na parede arterial, processo chave no início da aterogênese, ocorre de maneira desproporcional\nà concentração dessas lipoproteínas no plasma.","C":"na parede arterial, processo chave no início da aterogênese, ocorre de maneira proporcional à\nconcentração dessas lipoproteínas no plasma.","D":"na parede venosa, processo chave no início da aterogênese, ocorre de maneira proporcional à\nconcentração dessas lipoproteínas no plasma."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-182765","number":"182765","sourceNumber":"182765","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Cetoacidose Diabética (CAD) e o Estado Hiperglicêmico Hiperosmolar (EHH) devem\nser tratados em Unidade De Terapia Intensiva\ne, fundamentalmente, são as duas complicações\nagudas graves que podem ocorrer durante a evolução do Diabetes Mellitus tipos 1 e 2 (DM1 e\nDM2). As principais causas de morte por CAD e EHH são edema cerebral, hipopotassemia,\nhipofosfatemia, hipoglicemia, complicações intracerebrais, trombose venosa periférica,\nmucormicose, rabdomiólise e pancreatite aguda. Quanto as taxas de mortalidade, assinale a\nalternativa CORRETA:","options":{"A":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 10%. Da\ndécada de 1950 em diante, com a evolução de\ntodo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle eletrolítico e o uso de insulina regular, essa taxa\nfoi\nreduzida para aproximadamente 5%. Atualmente, em centros de excelência no tratamento de CAD,\né inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 30% ou mais. Nos casos de\nEHH, ainda permanece elevada, ao redor de 15%.","B":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 90%. Da\ndécada de 1950 em diante, com a evolução de\ntodo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle eletrolítico e o uso de insulina regular, essa taxa\nfoi\nreduzida para aproximadamente 10%. Atualmente, em centros de excelência no tratamento de\nCAD, é inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 30% ou mais. Nos\ncasos de EHH, ainda permanece elevada, ao redor de 15%.","C":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 50%. Da\ndécada de 1950 em diante, com a evolução de\ntodo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle eletrolítico e o uso de insulina regular, essa taxa\nfoi\nreduzida para aproximadamente 30%. Atualmente, em centros de excelência no tratamento de\nCAD, é inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 30% ou mais. Nos\ncasos de EHH, ainda permanece elevada, ao redor de 15%.","D":"Antes do advento da insulina, a taxa de mortalidade da CAD oscilava em torno de 90%. Da\n\ndécada de 1950 em diante, com a evolução de todo o arsenal terapêutico, como antibioticoterapia,\na ênfase no processo de hidratação, o controle\neletrolítico e o uso de insulina regular, essa taxa foi\nreduzida para aproximadamente 10%. Atualmente, em centros de excelência no tratamento de\nCAD, é inferior a 5%, mas, quando evolui com edema cerebral, pode atingir 90% ou mais. Nos\ncasos de EHH, ainda permanece elevada, ao redor de 15%."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183081","number":"183081","sourceNumber":"183081","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro das limitações impostas à atividade física na presença de complicações crônicas\ndo Diabético, determine a alternativa CORRETA.","options":{"A":"A presença de retinopatia restringe o tipo de exercício que pode ser praticado, já que esforços\nque causem grandes elevações de pressão\narterial, especialmente contrações isométricas e\nmanobra de Valsalva, podem ser contraindicados dependendo da presença de retinopatia.","B":"A presença de retinopatia não restringe o tipo de exercício que pode ser praticado, já que\nesforços que não causam grandes elevações de\npressão arterial, mesmo contrações isométricas e\nmanobra de Valsalva, podem ser contraindicados dependendo da presença de retinopatia.","C":"A presença de retinopatia restringe o tipo de exercício que pode ser praticado, já que esforços\nque pequenas elevações de pressão arterial,\nespecialmente contrações isométricas e podem ser\ncontraindicados dependendo da presença de retinopatia.","D":"A presença de retinopatia proíbe qualquer tipo de exercício a ser praticado, ja que esforços que\ncausem grandes elevações de pressão arterial,\nespecialmente contrações isométricas e manobra\nde Valsalva, podem ser contraindicados independendo da presença de retinopatia."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183103","number":"183103","sourceNumber":"183103","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os macrófagos repletos de lípides são chamados de células espumosas e são o\nprincipal componente das estrias gordurosas, lesões macroscópicas iniciais da aterosclerose.\nSendo CORRETO, apenas, que","options":{"A":"uma vez desativados, os macrófagos são, em grande parte, responsáveis pela progressão da\nplaca aterosclerótica por meio da secreção de\ncitocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais.","B":"uma vez ativados, os macrófagos são, em grande parte, responsáveis pela progressão da placa\naterosclerótica por meio da secreção de citocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais.","C":"uma vez ativados, os macrófagos são raramente responsáveis pela progressão da placa\naterosclerótica por meio da secreção de citocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais.","D":"uma vez ativados, os macrófagos são, em grande parte, responsáveis pela regressão da placa\naterosclerótica por meio da secreção de citocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183114","number":"183114","sourceNumber":"183114","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Nas escolas e nos locais de treinamento, devem estar disponíveis alimentos que\ncontêm carboidratos, glucagon injetável e\norientações sobre o tratamento da hipoglicemia. Outros\ncuidados com diabéticos na prática esportiva são listados abaixo, determine o INADEQUADO.","options":{"A":"Anotar os dados referentes aos treinos, ao uso de insulina e à alimentação, além das glicemias\nrelacionadas, para possibilitar a individualização.","B":"Encorajar o uso de novas tecnologias, como sensores, monitores contínuos, aplicativos em\nsmartphones e relógios monitores.","C":"Para a reposição de CHO no caso de atividade física se deve esperar a queda dos níveis de\nglicose, quando a hipoglicemia já será inevitável.","D":"Os monitores de glicemia contínua e as bombas de insulina com tecnologias de autossuspensão\ne manejo programado de hipoglicemia são úteis e\npodem beneficiar pacientes que usam essas\ntecnologias."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161165","number":"161165","sourceNumber":"161165","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Você se encontrava de plantão em um grande hospital terciário, como clínico, e o\nresidente médico da oftalmologia solicitou o\nseu parecer clínico para um paciente diabético que\nestava internando de urgência por grave complicação oftalmológica. Sendo a Retinopatia Diabética\n(RD) umas das principais complicações relacionadas ao Diabetes Mellitus (DM) e a principal causa\nde cegueira em pessoas com idade entre 20 e 74 anos, para ajudar no controle do paciente, você\nCORRETAMENTE orientou que:","options":{"A":"O tempo de duração do diabetes e o controle glicêmico não se relacionam com a gravidade da\nRD.","B":"É fundamental que seja feito o controle glicêmico adequado para a prevenção e diminuição das\ncomplicações relacionadas à doença.","C":"Os pacientes submetidos ao controle intensivo não apresentaram redução no risco de\ndesenvolvimento de retinopatia.","D":"De maneira geral, a de redução da hemoglobina glicada não leva a uma diminuição no risco de\naparecimento da retinopatia, somente de sua progressão."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-158789","number":"158789","sourceNumber":"158789","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentre as opções de antidiabéticos orais, qual droga promove glicosúria, tem baixo\nrisco de hipoglicemia, promove perda de peso, redução da pressão arterial sistólica e tem como\nefeito colateral risco aumentado para infecções genitais e de trato urinário?","options":{"A":"Acarbose.","B":"Sitagliptina.","C":"Metformina.","D":"Pioglitazona.","E":"Dapagliflozina."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161198","number":"161198","sourceNumber":"161198","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Nesta manhã, durante seu atendimento ambulatorial, um paciente seu, que também é\nda área da saúde, na verdade Bioquímico,\npediu sua orientação a respeito de dieta, pois estava\npreocupado com sua hipertensão. Foi uma excelente discussão, uma vez que ele também conhecia\nbastante sobre assunto. Apenas um dos conceitos a seguir foi questionado por ele, sendo que você\nse prontificou a estudar e corrigir eventual ERRO, que está contido em uma das alternativas.\n\nIndique-a.","options":{"A":"De um modo geral, a base fisiopatológica para os eventos cardiovasculares é a aterosclerose,\nprocesso que se desenvolve ao longo de\ndécadas de maneira insidiosa, podendo os primeiros\nsinais ser fatais ou altamente limitantes.","B":"A formação da placa de ateroma na parede dos vasos sanguíneos, bem como suas\nconsequências clínicas (infarto do miocárdio e\nAcidente Vascular Encefálico ? AVE) associam-se\nintimamente com determinados fatores de risco cardiovascular, como\n\nhipercolesterolêmia, hipertrigliceridemia, diminuição do HDL-c, hipertensão arterial sistêmica,\nDiabetes Mellitus e obesidade.","C":"A aterosclerose caracteriza-se por um processo inflamatório agudo da parede vascular, e a\nelevação de marcadores inflamatórios\nséricos, como a proteína C-reativa, tem se associado a maior\nrisco de eventos cardiovasculares.","D":"A base para a prevenção de eventos cardiovasculares tem sido, nas últimas décadas, o controle\nrigoroso dos fatores de risco ardiovascular. O controle da pressão arterial efetivamente diminui a\nchance de eventos cardiovasculares, sobretudo de AVE."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161243","number":"161243","sourceNumber":"161243","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Cetoacidose Diabética (CAD) e o Estado Hiperglicêmico Hiperosmolar (EHH) são as\nduas complicações agudas graves que podem ocorrer\ndurante a evolução do Diabetes Mellitus. A\nCAD está presente em aproximadamente 25% dos casos no momento do diagnóstico do DM1 e é a\ncausa mais comum de morte entre crianças e adolescentes com DM1, sendo também responsável\npor metade das mortes nesses pacientes com DM1 com menos de 24 anos. São importantes\naspectos sobre sua gênese os descritos a seguir, com EXCEÇÃO de um deles. Indique-o.","options":{"A":"Os estados infecciosos são as etiologias mais comuns de CAD e EHH. Entre as infecções, as\nmais frequentes são as do trato respiratório superior, as pneumonias e as infecções de vias\nurinárias.","B":"Ocorre a necessidade valorizar outros fatores importantes, como Acidente Vascular Cerebral\n(AVC), ingestão excessiva de álcool, pancreatite\naguda, Infarto Agudo do Miocárdio (IAM), traumas\ne uso de glicocorticoides.","C":"Ocorre os maiores riscos com o uso de risperidona e quetiapina.","D":"Os distúrbios psiquiátricos associados a irregularidades na condução da dieta ou no uso diário\nde insulina também podem contribuir para a CAD."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161180","number":"161180","sourceNumber":"161180","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente masculino, 45 anos de idade, gostaria de realizar um Eletrocardiograma\n(ECG) e, por isso, procurou atendimento\nambulatorial referindo ser diabético e que tinha muito\nmedo de que apresentasse simultaneamente um problema cardíaco, isso porque seu irmão mais\nvelho e diabético acabara de falecer de ?ataque cardíaco. Em termos de diagnóstico de Isquemia\nMiocárdica no diabético, podemos ADEQUADAMENTE afirmar que:","options":{"A":"A sobrecarga ventricular esquerda no ECG indica risco baixo de eventos cardiovasculares no\nDM.","B":"A presença de ondas ?Q? no ECG indica risco moderado de eventos cardiovasculares no DM.","C":"A Isquemia Miocárdica ao Eletrocardiograma (ECG) indica risco moderado de eventos\ncardiovasculares no DM.","D":"O ECG se apresenta como um exame pouco sensível."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161184","number":"161184","sourceNumber":"161184","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Embora as diretrizes nacionais considerem os portadores de Diabetes Mellitus (DM) na\ncategoria de alto risco Doença Cardiovascular (DCV), o risco de desfechos cardiovasculares de\ncurto prazo nessa população é extremamente variável, sendo um dos grandes desafios clínicos a\ncorreta identificação de indivíduos assintomáticos, mas que apresentem risco elevado de desfechos\ncardiovasculares. Podemos assim considerar ADEQUADO que:","options":{"A":"Os diabéticos tipo 1, com o passar dos anos, apresentam maior risco de complicações\ncardiovasculares, principalmente após os\n\n60 anos de idade.","B":"Contudo, esse intervalo pode variar independente do tempo de duração da doença.","C":"O risco cardiovascular se mostra independente do aparecimento de nefropatia, da hipertensão\narterial e do descontrole da glicemia.","D":"Mais recentemente, a obesidade e a SM associam-se a esse risco aumentado de Doença\nCardiovascular."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161277","number":"161277","sourceNumber":"161277","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A presença de depressão tem impacto negativo sobre o controle metabólico e, por\noutro lado, o distúrbio psiquiátrico também\ninterage no tratamento medicamentoso do diabetes\ndevido à necessidade de uso de psicofármacos. Os efeitos dos antidepressivos sobre a glicose,\npeso, entre outros estão listados a seguir, com EXCEÇÃO de um. Assinale-o.","options":{"A":"O uso da fluoxetina parece estar associado à piora nos níveis de HbA1c, aumento da\nnecessidade de insulina e perda de peso. Esse efeito sobre a sensibilidade à insulina ocorre\nindependentemente do seu efeito sobre o peso.","B":"A sertralina pode também reduzir a HbA1c, e o seu efeito sobre o ganho de peso é incomum.","C":"Com o uso da paroxetina pode haver ganho de peso em uma significativa minoria.","D":"A nortriptilina melhorou a depressão, mas piorou o controle glicêmico em pacientes diabéticos."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161281","number":"161281","sourceNumber":"161281","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro do que consideramos modificações no estilo de vida na população exposta ao\ndiabetes, aponte a alternativa INCORRETA.","options":{"A":"As modificações positivas do estilo de vida podem ter papel decisivo na prevenção do diabetes.","B":"Pacientes devem alterar seu estilo de vida, com modificação dos hábitos alimentares, perda\nponderal (redução de ao menos 30% do peso\ncorporal) caso apresentem sobrepeso ou obesidade.","C":"Hábitos de vida mais saudáveis (dieta balanceada, rica em fibras, visando peso corporal\nrealisticamente adequado, associada à atividade\nfísica de, pelo menos, 150 minutos semanais) são\ncapazes ? em indivíduos pré-diabéticos de reduzir seu risco de DM.","D":"Estudos também demonstraram a eficácia da acarbose, da metformina e da pioglitazona na\nprevenção do DM2."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-158745","number":"158745","sourceNumber":"158745","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A hemoglobina glicada (HbA1c) é o resultado de uma reação não enzimática de ligação\nda glicose à hemoglobina. Reflete a média do\ncontrole glicêmico dos últimos 4 meses, sendo,\nportanto, um reflexo mais confiável da existência de hiperglicemia; porém existem condições\nclínicas e interferentes técnicos que podem alterar seu resultado. Qual a condição clínica que\npromove a redução do valor real da HbA1c?","options":{"A":"Policitemia.","B":"Mieloma múltiplo.","C":"Alcoolismo crônico.","D":"Hipertrigliceridemia.","E":"Deficiência nutricional de ferro."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161291","number":"161291","sourceNumber":"161291","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Durante a prática diária, é necessário valorizar outros fatores importantes, como\nAcidente Vascular Cerebral (AVC), ingestão\nexcessiva de álcool, pancreatite aguda, Infarto Agudo\ndo Miocárdio (IAM), traumas e uso de glicocorticoides, como associados à Cetoacidose Diabética\n(CAD) e o Estado Hiperglicêmico Hiperosmolar (EHH), que são as duas complicações agudas\ngraves que podem ocorrer durante a evolução do diabetes mellitus. Dentre essas associações,\naponte a ERRADA.","options":{"A":"Atualmente, com o uso mais frequente de bombas de infusão contínua subcutânea de insulina\nultrarrápida, tem-se observado aumento na incidência de CAD. Tal fato pode ocorrer em razão da\nobstrução parcial ou total do cateter, provocando redução aguda de infusão de insulina.","B":"A descompensação glicêmica costuma ser mais prolongada e mais grave em pacientes com\nDM1 recém-diagnosticados.","C":"A descompensação glicêmica costuma ser mais prolongada e mais grave em idosos com\ndiabetes associado a processos infecciosos ou\ncom limitações no autocontrole físico ou psíquico.","D":"A utilização crescente na prática psiquiátrica de compostos denominados de antipsicóticos\natípicos para tratamento de transtorno de humor\nbipolar e esquizofrenia (por ex.: clozapina,\nolanzapina, risperidona e quetiapina) é capaz de diminuir o risco de distúrbios metabólicos."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161295","number":"161295","sourceNumber":"161295","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A depressão pode ser estudada como um dos possíveis fatores etiológicos do diabetes.\nAlguns estudos evidenciaram que a depressão prediz a ocorrência posterior da doença. A partir\ndessa análise, é possível a existência de um efeito sinérgico entre a depressão e o diabetes, ou\nseja, o resultado das duas condições juntas seria maior do que apenas o somatório dos seus\nefeitos. Estudos demonstram que os hábitos de vida (exercícios, controle do peso corporal e\ntabagismo) explicam uma parte considerável da associação entre depressão e controle glicêmico\nem diabéticos tipo 2 ao longo de anos. São adequadas as alternativas a seguir, com EXCEÇÃO de\numa. Indique-a.","options":{"A":"Um estudo brasileiro avaliou pacientes diabéticos tipo 2 e encontrou não apenas elevada\nprevalência de depressão, mas também\ncorrelação positiva entre a gravidade do quadro depressivo\ne a gravidade da polineuropatia diabética distal simétrica.","B":"Na população geral, a depressão é responsável por piora na morbidade e na mortalidade,\nmesmo na ausência de diabetes.","C":"A presença de depressão tem impacto negativo sobre o controle metabólico e, por outro lado,\num mau controle metabólico não altera a depressão.","D":"Um estudo demonstrou que a depressão seria um importante fator de risco para doenças micro\ne macrovasculares, perda da autonomia e até mesmo\nmortalidade pelo diabetes."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161297","number":"161297","sourceNumber":"161297","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro dos aspectos de prevenção do Diabetes, tanto farmacológico quanto\ncomportamental, na população de risco, assinale a alternativa INCORRETA.","options":{"A":"A metformina é indicação prioritária, sobretudo, em paciente com menor peso e com idade\nsuperior a 65 anos.","B":"Acarbose pode ser considerado, para pacientes jovens, risco moderado/alto para\ndesenvolvimento de DM2.","C":"Pioglitazona pode ser considerado, para pacientes jovens, risco moderado/alto para\ndesenvolvimento de DM2.","D":"Medicações podem ser indicadas, desde que não apresentem contraindicações outras para tais\nmedicamentos."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161220","number":"161220","sourceNumber":"161220","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente masculino, 45 anos de idade, gostaria de realizar um Eletrocardiograma\n(ECG) e, para isso, procurou atendimento\nambulatorial referindo ser diabético e que tinha muito\nmedo de que apresentasse simultaneamente um problema cardíaco, isso porque seu irmão mais\nvelho, que também era diabético, acabara de falecer de ?ataque cardíaco?. Em termos de\ndiagnóstico de Isquemia Miocárdica no diabético, podemos ADEQUADAMENTE afirmar que","options":{"A":"sobrecarga ventricular esquerda no ECG indica risco baixo de eventos cardiovasculares no DM.","B":"presença de ondas ?Q? no ECG indica risco moderado de eventos cardiovasculares no DM.","C":"isquemia miocárdica ao Eletrocardiograma (ECG) indica risco moderado de eventos\ncardiovasculares no DM.","D":"o ECG se apresenta como um exame pouco sensível."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161229","number":"161229","sourceNumber":"161229","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Embora as diretrizes nacionais considerem os portadores de Diabetes Mellitus (DM) na\ncategoria de alto risco para Doença Cardiovascular (DCV), o risco de desfechos cardiovasculares\nde curto prazo nessa população é extremamente variável, sendo um dos grandes desafios clínicos\na correta identificação de indivíduos assintomáticos, mas que apresentem risco elevado de\ndesfechos cardiovasculares. Assim, podemos considerar ADEQUADO que","options":{"A":"os Diabéticos tipo 1, com o passar dos anos, apresentam maior risco de complicações\ncardiovasculares, principalmente após os 60 anos de idade.","B":"mais recentemente, a obesidade e a SM associam-se a esse risco aumentado de Doença\nCardiovascular.","C":"contudo, esse intervalo pode variar independente do tempo de duração da doença.","D":"o risco cardiovascular se mostra independente do aparecimento de nefropatia, da hipertensão\narterial e do descontrole da glicemia."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161234","number":"161234","sourceNumber":"161234","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quais são as metas de prevenção relacionadas ao tratamento de diabéticos jovens?","options":{"A":"As metas para o tratamento do DM2 no jovem são diferentes das propostas para o DM1.","B":"Manter assintomático, sustentar um ritmo normal de crescimento e desenvolvimento, além do\ncontrole do peso.","C":"Apenas prevenir complicações crônicas da hiperglicemia.","D":"Devemos tentar alcançar normoglicemia, mesmo causando hipoglicemias frequentes."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161375","number":"161375","sourceNumber":"161375","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Podemos determinar fortes relações epidemiológicas da presença simultânea de\nDiabetes e de doenças cardiovasculares, mas\napenas uma das opções é considerada ADEQUADA.\nAssinale-a.","options":{"A":"Aproximadamente um terço dos indivíduos com o diagnóstico de Diabetes Mellitus (DM) acabam\npor falecer devido à Doença Arterial\nCoronariana (DAC) ou Doença Cerebrovascular (DCV).","B":"A confluência da menor incidência com a menor mortalidade tornará imprescindível o esforço\nconjunto de diversas especialidades médicas para a prevenção.","C":"Ocorre incidência do DM associado, na maioria das vezes, à obesidade.","D":"Ocorrerá manutenção na prevalência do DM no futuro próximo, se não houver uma redução\nimportante na incidência desta doença."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161240","number":"161240","sourceNumber":"161240","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A importância do apoio familiar de crianças diabéticas pode ser determinada pelo\nseguinte achado contido em uma das opções. Aponte-a.","options":{"A":"A supervisão direta da criança com DM2 não obteve efeito positivo no controle glicêmico.","B":"Nos pais, que treinam seus filhos a alimentarem-se melhor, não ocorre redução significativa do\nIMC.","C":"Ocorre que a obesidade pediátrica é um problema do complexo familiar.","D":"O ponto pouco importante do tratamento é a modificação do estilo de vida, a qual inclui\nmodificações dietéticas e aumento das atividades físicas."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161390","number":"161390","sourceNumber":"161390","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considerando-se o conceito de risco cardiovascular, pacientes com DM, mesmo sem\ndoença aterosclerótica estabelecida, apresentam\nmaior risco de desenvolver eventos vasculares no\nfuturo. A Doença Aterosclerótica Coronariana é mais incidente e mais grave nos pacientes com DM\ndo que naqueles sem DM. Sobre isso, aponte a alternativa CORRETA.","options":{"A":"O risco relativo para DCV aumenta de dez vezes nos pacientes com DM2 em comparação com a\npopulação em geral.","B":"As mulheres com DM são particularmente afetadas pela DAC e seu risco de morte é 50% maior\ndo que o dos homens com DM.","C":"Estes pacientes apresentam raramente associação de fatores de risco cardiovascular: HAS,\nníveis séricos baixos de colesterol da\nlipoproteína de alta densidade (HDL-C), microalbuminúria e\ndoença renal, aumento do Índice de Massa Corporal (IMC) e da relação cintura-quadril.","D":"O DM, quando associado a fatores de risco clássicos para DAC, como hipercolesterolemia, fumo\ne HAS, aumenta o risco para DCV atribuído a\ncada um destes fatores de forma menos importante\ndo que é observado em indivíduos sem DM."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161407","number":"161407","sourceNumber":"161407","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Analisando o impacto da sobreposição de Hipertensão Arterial Periférica (DAP),\ndiabetes e doenças vasculares, o conhecimento dos dados epidemiológicos assume grande\nimportância. Acerca disso, marque a opção considerada INCORRETA.","options":{"A":"A Doença Arterial Periférica acomete duas a quatro vezes mais pacientes com DM.","B":"A presença do DM aumenta o risco de desenvolver isquemia crítica dos membros com Doença\nArterial Periférica.","C":"Além do aumento da frequência de DAP, o DM não afeta a distribuição da aterosclerose nos\nmembros inferiores, atingindo tipicamente as artérias tibiais, peroneais, femorais e poplíteas.","D":"A duração do DM e a hiperglicemia se associam positivamente à presença e à gravidade da\nDAP."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161264","number":"161264","sourceNumber":"161264","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro dos aspectos do diabético jovem, que apresentam vários desafios enfrentados\nno tratamento do DM2, podemos delimitar vários\nachados, com EXCEÇÃO","options":{"A":"da natureza insidiosa da síndrome.","B":"do atraso na procura pela assistência médica.","C":"do reconhecimento precoce pelo pediatra.","D":"da baixa adesão ao tratamento que decorre da resistência às mudanças de hábitos, somada às\ncaracterísticas próprias da idade."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161206","number":"161206","sourceNumber":"161206","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quando lidamos com conhecimento das complicações referente ao diabetes em longo\nprazo, assume grande importância o conhecimento dos conceitos referentes aos marcadores de\nhiperglicemia. Dentre esses conceitos, assinale o CORRETO.","options":{"A":"Genericamente, o termo hemoglobina glicada refere-se a um conjunto de substâncias formadas\ncom base em reações entre a hemoglobina A\n(HbA) e alguns açúcares.","B":"A HbA é a forma pouco importante e nativa da hemoglobina.","C":"No decorrer dos anos ou das décadas, a hiperglicemia prolongada promove o desenvolvimento\nde lesões orgânicas extensas e reversíveis.","D":"Os níveis de glicose sanguínea, persistentemente elevados, são atóxicos ao organismo."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161210","number":"161210","sourceNumber":"161210","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para entendermos a gênese dos achados clínicos decorrentes dos níveis,\npersistentemente elevados, de glicose sanguínea, que\npor sua vez são tóxicos ao organismo,\ndevemos considerar os diferentes mecanismos envolvidos, com EXCEÇÃO de um. Assinale-o.","options":{"A":"Mediante a promoção da glicação de proteínas.","B":"Hiperosmolalidade.","C":"Com manutenção dos níveis de sorbitol fora da célula.","D":"Aumento dos níveis de sorbitol dentro da célula."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161209","number":"161209","sourceNumber":"161209","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro da análise dos achados de alterações crônicas dos níveis de glicose sanguínea,\npodemos entender a importância de marcadores\nde elevação crônica da glicose. Assim, somente\numa das afirmativas se mostra completamente CORRETA. Aponte-a.","options":{"A":"A glicação da hemoglobina ocorre ao longo de todo o período de vida do glóbulo vermelho, que\né de aproximadamente 150 dias.","B":"Porém, dentro destes 150 dias, a glicemia recente é a que mais influencia o valor da HbA1c.","C":"O paciente em controle estável apresentará 50% de sua HbA1c formada no mês precedente ao\nexame, 25% no mês anterior a este e os 25% remanescentes no terceiro ou quarto mês antes do\nexame.","D":"O impacto de qualquer variação significativa (em sentido ascendente ou descendente), na\nglicemia média, será ?diluído? dentro de 6 meses, em termos de níveis de HbA1c."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161213","number":"161213","sourceNumber":"161213","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para o correto uso do exame de monitorização dos níveis de glicose, existe uma\nfrequência recomendada para a realização dos testes\nde hemoglobina glicada. Sobre isso, assinale\na alternativa CORRETA.","options":{"A":"A quantidade de glicose ligada à hemoglobina é inversamente proporcional à concentração\nmédia de glicose no sangue.","B":"Uma vez que as hemácias têm um tempo de vida de aproximadamente 140 dias, a medida da\nquantidade de glicose ligada à hemoglobina pode fornecer uma avaliação do controle glicêmico\nmédio no período de 140 dias antes do exame.","C":"Em virtude de os resultados do exame concederem informação retrospectiva sobre 6 meses\nprecedentes, a realização de um teste de HbA1c a cada 3 meses fornecerá dados que expressam\na glicose sanguínea média no passado recente.","D":"Os exames de HbA1c devem ser realizados regularmente em todos os pacientes com diabetes.\n\nA princípio para documentar o grau de controle glicêmico em sua avaliação inicial e,\nsubsequentemente, como parte do atendimento contínuo do paciente."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161286","number":"161286","sourceNumber":"161286","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quando lidamos com prevenção secundária, devemos considerar que existem\nevidências científicas dos efeitos benéficos do\nexercício físico na prevenção e no tratamento do\nDiabetes Mellitus (DM). Sobre isso, assinale a opção considerada INCORRETA.","options":{"A":"O exercício previne o DM tipo 2 (DM2), principalmente nos grupos de maior risco, como os\nobesos e os familiares de diabético.","B":"Em adição, indivíduos fisicamente ativos e aqueles com melhor condição aeróbica apresentam\nmenor incidência de DM2.","C":"Diabéticos apresentam menor condição aeróbica, menos força muscular e menos flexibilidade\ndo que seus pares da mesma idade e sexo sem a\ndoença.","D":"Essa menor capacidade, decorrente das alterações metabólicas e suas consequências, assim\ncomo a menor capilarização tipicamente observada nos diabéticos, não podem ser\ncontrabalanceadas com o exercício físico."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161245","number":"161245","sourceNumber":"161245","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro da análise da relação do exercício físico na população diabética, podemos\nafirmar diversos aspectos, com EXCEÇÃO de um deles. Assinale-o.","options":{"A":"Diabéticos fisicamente ativos ou em boa condição aeróbica apresentam melhor prognóstico do\nque aqueles inativos e com baixa condição\naeróbica.","B":"A observação, de que diabéticos sedentários têm maiores índices de consumo máximo de\noxigênio, de débito cardíaco e de\ncapacidade de extração tecidual de oxigênio, é refletida por uma\nmaior diferença arteriovenosa de oxigênio para exercícios submáximos e máximos, quando\ncomparados com sedentários não diabéticos.","C":"Ocorre importante impacto das alterações metabólicas que cronicamente atuam e comprometem\na capacidade física dos diabéticos.","D":"O treinamento aeróbico regular proporciona condições de reverter parcial ou totalmente algumas\ndas disfunções provocadas pela hiperglicemia\ncrônica."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161134","number":"161134","sourceNumber":"161134","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro da monitorização do controle metabólico durante a gestação em mulheres que\nsão diabéticas, NÃO podemos considerar que:","options":{"A":"os níveis de HbA1c recomendados para minimizar os riscos também são os menores possíveis,\nnão devendo ultrapassar o limite de 2% acima do\nvalor normal do método.","B":"Durante a gestação, a HbA1c não deve ser usada como parâmetro de avaliação para eventuais\nalterações da conduta terapêutica devido ao longo período necessário para que os níveis\nglicêmicos alterados possam se refletir nos níveis de HbA1c observados.","C":"Durante a gravidez, é muito mais importante o controle rígido dos níveis de glicemias de jejum e\npós-prandiais do que dos níveis de HbA1c.","D":"A mulher diabética que pretende engravidar deve ser encorajada a obter o melhor controle\nmetabólico possível antes de engravidar."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161257","number":"161257","sourceNumber":"161257","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Existem atualmente fortes evidências científicas dos efeitos benéficos do exercício\nfísico na prevenção e no tratamento do Diabetes\nMellitus (DM). O exercício previne o DM tipo 2\n(DM2), principalmente nos grupos de maior risco, como os obesos e os familiares de diabético.\nAponte a alternativa INCORRETA.","options":{"A":"O melhor momento do diabético se exercitar é cerca de 60 minutos após uma refeição, quando a\nglicose ingerida será utilizada como substrato energético, evitando a hiperglicemia pós-prandial.","B":"O exercício é um forte aliado na predição desse risco nos diabéticos, assim como na sua\nredução por meio da prática regular.","C":"O exercício físico reduz o risco cardiovascular também em pacientes com DM.","D":"Pacientes diabéticos que se exercitam regularmente mostram melhora clínica relevante no seu\nperfil lipídico, e diabéticos hipertensos tendem a ter um melhor controle dos níveis tensionais\nquando submetidos a treinamento."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161142","number":"161142","sourceNumber":"161142","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro do entendimento da atual epidemia de diabéticos Tipo 2, aponte a alternativa\nINCORRETA.","options":{"A":"O aumento da incidência do Diabetes Mellitus tipo 2 (DM2) entre crianças e adolescentes vem\nsendo observado em várias regiões do mundo.","B":"O aumento da prevalência de DM2 tem sido ainda associado ao crescimento da industrialização\ne desenvolvimento socioeconômico.","C":"Já são conhecidos todos os motivos responsáveis pela eclosão da doença nessa faixa etária\n(entre crianças e adolescentes).","D":"Inicialmente, há duas décadas, esses relatos referiam-se a grupos homogêneos com maior\nsuscetibilidade à doença."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161284","number":"161284","sourceNumber":"161284","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quanto aos benefícios no controle do diabético, relacionado ao tipo de exercício\nproposto, somente NÃO podemos relacionar como\ncorreta uma das alternativas a seguir. Indique-a.","options":{"A":"Exercícios aeróbicos são normalmente realizados usando grandes grupos musculares e\ncaracterizam-se por atividades que costumam não demandar habilidades muito específicas, sendo\na caminhada o melhor exemplo disso.","B":"Aquecimento e desaquecimento são fundamentais, principalmente no subgrupo que apresenta\ndisautonomia.","C":"Exercícios de resistência/fortalecimento muscular devem ser incluídos no plano de atividades do\ndiabético, já que eles provocam elevação da sensibilidade da insulina de maior duração, mediado\ntambém pelo aumento da massa muscular.","D":"Exercícios de flexibilidade não devem ser contemplados, pois há redução da flexibilidade pela\nação deletéria da hiperglicemia crônica sobre as articulações, além da decorrente do\nenvelhecimento."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161171","number":"161171","sourceNumber":"161171","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro do estudo do impacto da cada vez maior incidência de diabéticos na população\njovem, marque a opção INCORRETA.","options":{"A":"O aumento na predominância da obesidade na adolescência registrado nos últimos anos\nexplicaria, em grande parte, o avanço do DM2 nas populações jovens.","B":"O aumento na predominância da obesidade na adolescência, registrado nos últimos anos, se\nrelaciona com o desenvolvimento da síndrome metabólica e de doenças cardiovasculares na\nmaturidade.","C":"Em adolescentes com DM2, a avaliação do efeito do diabetes e da obesidade sobre\ncomplacência vascular encontrou aumento da rigidez dos vasos.","D":"DM2 de início precoce pode ser menos agressivo do ponto de vista cardiovascular do que em\nadultos."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161301","number":"161301","sourceNumber":"161301","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quando lidamos com prevenção e complicações relacionadas ao diabetes, podemos\nafirmar que existem diversos cuidados e considerações a respeito. Desse modo, indique a\nalternativa INCORRETA.","options":{"A":"Para os diabéticos, a recomendação de atividade aeróbica diária, ou pelo menos 3 dias da\nsemana sem permanecer mais de 2 dias sem\nrealizá-la, é reforçada para que os benefícios sobre o\nmetabolismo glicídico sejam alcançados.","B":"A duração necessária de uma sessão de exercício depende da intensidade e da frequência\nsemanal dos exercícios.","C":"Nos pacientes diabéticos, a duração de um exercício deve ser planejada para minimizar riscos\nde hipoglicemia, geralmente sendo necessária a\nreposição de carboidratos quando a atividade tiver\nduração > 30 minutos.","D":"A recomendação mais atual para diabéticos é de 150 minutos de exercícios de moderada\nintensidade ou 75 minutos de alta intensidade por semana ou uma combinação de ambos."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161179","number":"161179","sourceNumber":"161179","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre o estudo da interação entre obesidade, descontrole metabólicos e diabetes no\npúblico mais jovem, podemos relacionar diversos aspectos, com EXCEÇÃO de um deles.\n\nIndique-o.","options":{"A":"As elevadas taxas de obesidade na infância e na adolescência estão relacionadas com\nsedentarismo crescente e mudança nos hábitos\nalimentares, frequentemente associadas a dietas\nhipercalóricas e hipergordurosas.","B":"Os possíveis candidatos que ligam obesidade à alteração do metabolismo dos carboidratos\nseriam os ácidos graxos livres aumentados, as\ncitocinas inflamatórias e os baixos níveis de\nadiponectina.","C":"A transição de tolerância normal à glicose para a intolerância à glicose e dessa etapa para o\ndiabetes está associada a um aumento discreto de peso.","D":"A elevação contínua do peso tem efeito sobre os níveis glicêmicos, independentemente de\nmudanças na sensibilidade insulínica ou na\ndemanda da célula beta."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161307","number":"161307","sourceNumber":"161307","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Embora a taxa de complicações crônicas relacionadas ao DM venham diminuindo nas\núltimas duas décadas, ainda é muito grande o número de pacientes afetados, pois a incidência de\nDM continua aumentando. Por este motivo, a Doença Renal do Diabetes (DRD) permanece sendo\na principal causa de doença renal crônica em pacientes ao ingressarem em programas de diálise,\ninclusive no Brasil. A DRD está associada ao aumento de mortalidade, principalmente relacionada à\ndoença cardiovascular. Em referência à enorme importância do adequado conhecimento de\nalterações achadas devido à sua evolução, indique a opção considerada INADEQUADA.","options":{"A":"A diminuição rápida e acentuada da taxa de filtração glomerular (> 80%) após o início de terapia\ncom Inibidores da Enzima Conversora da Angiotensina (IECA) ou Bloqueadores do Receptor AT1\nda Angiotensina (BRA) sugere estenose da artéria renal, devendo esta possibilidade ser avaliada,\nespecialmente em pacientes com vasculopatia.","B":"Todo teste de albuminúria anormal deve ser confirmado em duas de três amostras coletadas em\num intervalo de 3 a 6 meses, devido à\nvariabilidade diária da excreção urinária de albumina (EUA).","C":"Embora seja sugerido que infecção urinária possa interferir nos valores de EUA, recentemente\nfoi constatado que a existência de bacteriúria não\ninterfere de maneira apreciável nas medidas de\nalbuminúria.","D":"Fatores como exercício durante o período de coleta de urina, febre, insuficiência cardíaca,\nhiperglicemia grave e hipertensão arterial não controlada podem elevar os valores de Excreção\nUrinária de Albumina (EUA)."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161313","number":"161313","sourceNumber":"161313","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Atualmente, o uso do termo nefropatia diabética deve ser reservado somente para\npacientes com proteinúria detectável persistente, em geral associada à elevação da pressão\narterial. A respeito da relação entre o diabetes e a lesão renal, podemos considerar ADEQUADO\napenas o seguinte. Assinale-o:","options":{"A":"A Doença Renal do Diabetes (DRD), na forma de elevação da Excreção Urinária de Albumina\n(EUA), pode acometer 90% dos pacientes com diabetes.","B":"Embora a taxa de complicações crônicas relacionadas ao DM venha aumentando nas últimas\nduas décadas, tendo ocorrido uma redução\naproximada de 30% na Doença Renal do Diabetes\n(DRD), em suas fases mais avançadas ainda é muito grande o número de pacientes afetados, pois\na incidência de DM continua aumentando.","C":"A Doença Renal do Diabetes (DRD) está associada ao aumento de mortalidade, principalmente\nrelacionada à doença cardiovascular.","D":"O aumento da Excreção Urinária de Albumina (EUA) apresenta pouca importância como fator de\nrisco para eventos coronarianos e para desenvolvimento e progressão da Doença Renal do\nDiabetes (DRD)."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161192","number":"161192","sourceNumber":"161192","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro da análise da associação entre a obesidade e o diabetes, indique a alternativa\nINCORRETA.","options":{"A":"A obesidade apresenta-se de modo constante no DM2 do jovem.","B":"Aproximadamente 70 a 90% das crianças são obesas; sendo que 38% apresentam obesidade\nmórbida.","C":"A obesidade e a história familiar parecem ter efeito aditivo no risco de desenvolvimento da\ndoença.","D":"O impacto da obesidade no risco do DM2 é menor em crianças com história familiar positiva\npara essa doença."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161315","number":"161315","sourceNumber":"161315","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A classificação atual da doença renal crônica, independentemente da etiologia, é\nbaseada na Taxa de Filtração Glomerular\n(TFG) e na Excreção Urinária de Albumina (EUA), pois\ntem sido extensamente reconhecida a relação desses dois parâmetros com desfechos adversos\nrenais e mortalidade. Sobre isso, marque a opção INCORRETA:","options":{"A":"Atualmente, tem havido uma ampliação do espectro das apresentações clínicas da Doença\nRenal do Diabetes (DRD), sendo o fenótipo da\ndoença renal não albuminúrica, caracterizada por\nredução isolada da TFG, cada vez mais reconhecido.","B":"Por este motivo, a Doença Renal do Diabetes (DRD) permanece sendo a quinta causa de\ndoença renal crônica em pacientes ao\ningressarem em programas de diálise, inclusive no Brasil.","C":"Em aproximadamente 1/5 dos casos, observa-se a redução isolada da Taxa de Filtração\nGlomerular (TFG). Em estudos realizados no Sul\ndo Brasil, verificou-se que 37% dos pacientes com\nDM tipo 2 (DM2) e 34% dos pacientes com DM tipo 1 (DM1) apresentam aumento da Excreção\nUrinária de Albumina (EUA).","D":"Atualmente, ainda é muito grande o número de pacientes afetados, pois a incidência de DM\ncontinua aumentando."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161199","number":"161199","sourceNumber":"161199","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre as características de fisiopatologia do diabetes que influenciam os achados\nepidemiológicos na população infantil, aponte a alternativa INCORRETA.","options":{"A":"Crianças que haviam nascido grandes para a idade gestacional (GIG) tinham menor risco de\nevoluir com obesidade, enquanto outras com antecedente familiar de DM2 apresentavam maior\nprevalência de síndrome metabólica.","B":"Ocorre elevação na Resistência à Insulina em portadores de excesso de peso com antecedentes\nfamiliares de DM2, sugerindo que, já nessa\nfaixa etária, como observado no adulto, a ação da\ninsulina pode ser dificultada pela obesidade, condição de risco para o desenvolvimento do diabetes.","C":"O antecedente familiar tem função fundamental na ocorrência do DM2 nessa faixa etária.","D":"Observou-se que irmãos de jovens com DM2, com sobrepeso, têm risco quatro vezes maior de\nmanifestar intolerância à glicose que outras crianças com sobrepeso."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161316","number":"161316","sourceNumber":"161316","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O rastreamento da doença renal do diabetes (DRD), para que seja adequado, deve ser\niniciado logo ao diagnóstico do DM nos pacientes com DM2 e após 5 anos do início no DM1. No\nentanto, pacientes com DM1, que se encontrem na puberdade ou com DM persistentemente\ndescompensado, têm de ser rastreados independentemente dessas indicações. Acerca disso,\naponte a alternativa considerada INADEQUADA.","options":{"A":"O rastreamento precisa ser mensal e basear-se na medida da albuminúrica e na estimativa da\ntaxa de filtração glomerular (TFG).","B":"O rastreamento deve ser iniciado preferencialmente pela medida de albumina em amostra\nisolada de urina (primeira da manhã ou\ncasual), devido à acurácia diagnóstica e à facilidade desse\ntipo de coleta.","C":"Pode ser medido o índice de albumina-creatinina ou apenas a concentração de albumina.","D":"A vantagem da utilização da concentração da albumina é um menor custo sem perda de\nacurácia diagnóstica quando comparada com o índice."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161202","number":"161202","sourceNumber":"161202","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"São achados do quadro clínico de jovens diabéticos os seguintes aspectos, com\nEXCEÇÃO de um deles. Marque-o.","options":{"A":"A idade de maior incidência do DM2 no jovem é próxima dos 13 anos, guardando relação com o\nestádio III da classificação de Tanner.","B":"Ocorre uma proporção de 2:1 em meninas, em relação aos meninos.","C":"As crianças com DM2 são geralmente assintomáticas ou oligossintomáticas por curtos períodos\nde tempo.","D":"Entre os pacientes, 30% apresentam poliúria, polidipsia leve e emagrecimento discreto. Algumas\npacientes podem revelar história de monilíase vaginal."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161317","number":"161317","sourceNumber":"161317","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Ocorre também importante necessidade de se conhecerem os diagnósticos diferencias\nde doenças renais dos diabéticos, devido ao fato\nde que o aumento da Excreção Urinária de\nAlbumina (EUA) ou a redução da Taxa de Filtração Glomerular (TFG), em pacientes com DM,\ntambém pode ser causado por outra doença renal não relacionada ao DM. O paciente deve ser\nsubmetido à avaliação adicional nas seguintes situações, com EXCEÇÃO de uma. Assinale-a.","options":{"A":"Quando há início da proteinúria em pacientes com duração do DM inferior a 5 anos, em especial\nno DM1.","B":"Devido ao início da proteinúria abrupto e rapidamente progressivo, não compatível com o curso\nclínico da Doença Renal do Diabetes (DRD).","C":"Achados alterações no sedimento urinário, como cilindros hemáticos, leucocitários e acantócitos;\nmanifestações clínicas de outra doença sistêmica e ausência de retinopatia e neuropatia em\npacientes com DM1, visto que nestes a retinopatia diabética precede o surgimento de Doença\nRenal do Diabetes (DRD).","D":"Nos pacientes com DM2, a ausência de retinopatia e neuropatia excluem Doença Renal do\nDiabetes (DRD), pois apenas 5% dos pacientes com DM2 proteinúricos, com diagnóstico de ND\nconfirmado por biópsia, apresentam retinopatia diabética."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161207","number":"161207","sourceNumber":"161207","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro dos critérios diagnósticos de diabetes na população pediátrica, marque a\nalternativa considerada INCORRETA.","options":{"A":"Um terço dos jovens com DM2 utilizava insulina, e somente 22% dos com DM1 não\napresentavam insulina endógena, sugerindo que uma\ngrande fração desses jovens parece ter\ndiabetes de etiologia mista.","B":"O diagnóstico de DM2 na infância deverá ser feito levando-se em consideração critérios clínicos,\ncomo idade e sexo do paciente, obesidade e história familiar positiva para DM2.","C":"Devido à alta miscigenação brasileira, não existem dados, até o momento, para considerar a cor\ncomo fator de risco.","D":"Os níveis para a glicemia de jejum, com base nos critérios atualmente adotados para o\ndiagnóstico do DM2, não são os mesmos para adultos ou crianças."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161308","number":"161308","sourceNumber":"161308","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentro dos conceitos de doença renal do diabetes (DRD), a base nos valores\ncrescentes de excreção urinária de albumina\n(EUA), a DRD tem sido historicamente classificada em\nfases. Entretanto, a progressão destes estágios não é inexorável, podendo ocorrer regressão da\nmicroalbuminúria em cerca de 30% dos pacientes, em geral associada a intervenções terapêuticas.\nAponte a alternativa que NÃO faz parte dessas fases.","options":{"A":"Normoalbuminúria.","B":"Hipoalbuminúria.","C":"Microalbuminúria.","D":"Macroalbuminúria."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161323","number":"161323","sourceNumber":"161323","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Síndrome Metabólica tem como características, com EXCEÇÃO de uma. Aponte-a.","options":{"A":"Representa um conjunto de importantes fatores de risco para doença cérebro-vascular.","B":"A obesidade abdominal e a resistência insulínica são fatores importantes na gênese do\nproblema.","C":"A terapia com Metformina, mesmo que isoladamente, pode reverter quadro de anovulação em\nalgumas pacientes.","D":"Os anticoncepcionais combinados orais não são de grande utilidade prática em casos de\nAnovulação Crônica relacionada à Síndrome Metabólica."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161196","number":"161196","sourceNumber":"161196","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Nos quadros de Cetoacidose Diabética (CAD), a maioria dos casos fatais está\nrelacionada ao desenvolvimento de edema\ncerebral, que ainda é uma complicação observada em\n0,5% a 2% dos pacientes com CAD, com mortalidade de 40 a 90%, e capaz de produzir sequelas\nentre 10 a 25% dos sobreviventes. Outras causas de mortalidade e morbidade frequentes são,\nEXCETO.","options":{"A":"Hipermagnesemia.","B":"Hipocalemia.","C":"Alterações do sistema nervoso central.","D":"Infecções."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161200","number":"161200","sourceNumber":"161200","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Entre os critérios laboratoriais para diagnóstico da Cetoacidose Diabética, aponte o\núnico INCORRETO.","options":{"A":"O pH (venoso ou arterial) inferior a 7,3 e/ou bicarbonato de sódio inferior a 15 mEq/L.","B":"Glicemia superior a 200 mg/dL.","C":"Presença de cetonemia e/ou cetonúria.","D":"Potássio sérico menor que 3 mEq/L."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-161119","number":"161119","sourceNumber":"161119","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Com relação à cetoacidose diabética, assinale a alternativa CORRETA.","options":{"A":"A cetoacidose diabética é considerada grave quando o bicarbonato sérico estiver entre 12 e 18\nmEq/L.","B":"A infusão contínua de insulina reduz a glicemia e também o potássio sérico.","C":"A infusão contínua de insulina reduz a glicemia e promove a entrada do sódio sérico.","D":"A infusão contínua de insulina reduz a glicemia e promove o aumento no ânion-gap."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-86802","number":"86802","sourceNumber":"86802","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"São causas de hipocalcemia, exceto:","options":{"A":"Sepse;","B":"Pós-operatório;","C":"Pancreatite aguda;","D":"Hiperparatireoidismo;","E":"Lise tumoral."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-108589","number":"108589","sourceNumber":"108589","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre a nefropatia diabética, é INCORRETO afirmar que:","options":{"A":"Microalbuminúria é marcador de lesão endotelial.","B":"Proteinúria instalada pode ser combatida com os IECA e BRA.","C":"Pacientes com nefropatia avançada também costumam ter lesões ao exame de fundo de olho.","D":"Proteinúria de Bence Jones deve ser solicitada rotineiramente para avaliação de lesão renal\ndeclarada.","E":"Todas as anteriores."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362423","number":"362423","sourceNumber":"362423","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Na cetoacidose diabética, qual é a principal alteração de eletrólitos que pode ocorrer\ndurante o tratamento?","options":{"A":"Hiponatremia","B":"Hipernatremia","C":"Hipocalemia","D":"Hipercalemia"},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-298199","number":"298199","sourceNumber":"298199","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre as medicações utilizadas no tratamento do DM2, assinale a alternativa\nCORRETA:","options":{"A":"A metformina reduz a absorção de cianocobalamina no íleo distal, podendo levar a deficiência\nde vitamina B12; por isso, é recomendado que\nseus níveis sejam dosados anualmente após 4 anos\nde início de seu uso.","B":"A pioglitazona promove redução da glicemia por meio da inibição do receptor SGLT-2, com\nconsequente inibição da reabsorção renal de glicose no túbulo contorcido proximal, levando à\nglicosúria.","C":"As gliflozinas podem, entre outros eventos adversos, levar a retenção hídrica; dessa forma,\npodem agravar ou desencadear insuficiência\ncardíaca (IC), estando contra- indicadas em pacientes\ncom IC classe III e IV da New York Heart Association (NYHA).","D":"Os análogos do receptor do GLP-1 agem no controle glicêmico ao reduzir a secreção de insulina\ndependente de glicose, ao mesmo tempo que aumentam a secreção de glucagon."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-298278","number":"298278","sourceNumber":"298278","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um dos principais motivos de consultas de condições crônicas em APS diz respeito ao\nacompanhamento de pacientes com Diabetes Mellitus, sendo necessário avaliação constante do\nrisco cardiovascular, da adesão ao tratamento, das metas glicêmicas e de lesões de órgãos-alvo.\nSobre a sistematização desse seguimento podemos afirmar CORRETAMENTE que:","options":{"A":"O exame de microalbuminúria deve ser solicitado somente em diabéticos com Hipertensão\nArterial Sistêmica associada, uma vez que sua\npresença isoladamente não possui bom valor\npreditivo positivo para nefropatia diabética.","B":"É necessário orientar sobre sinais de hipoglicemia, mais comuns em pacientes que usam\nmetformina quando comparados aos que utilizam insulina.","C":"O exame dos pés é essencial para avaliação do pé diabético e a presença de alterações\narticulares de qualquer grau é indicação de\nencaminhamento à cirurgia vascular para amputação.","D":"A investigação de retinopatia diabética deve se iniciar no momento do diagnóstico em pacientes\ncom DM2."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-286699","number":"286699","sourceNumber":"286699","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente 68 anos, chega à emergência com quadro de sonolência. Familiar refere\nperda ponderal, polidipsia, febre e tosse há 7\ndias. Glicemia na admissão: 900 mg/dl. Exames\nlaboratoriais mostram: sódio: 150 mEq/L, potássio: 3,0 mEq/L, HCO3: 18, cloro: 102. peso: 100 kg.\nQual hipótese mais provável do quadro?","options":{"A":"Hipernatremia sintomática.","B":"Cetoacidose diabética.","C":"Acidente vascular cerebral.","D":"Estado hiperosmolar não cetótico."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-286700","number":"286700","sourceNumber":"286700","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente 68 anos, chega à emergência com quadro de sonolência. Familiar refere\nperda ponderal, polidipsia, febre e tosse há 7\ndias. Glicemia na admissão: 900 mg/dl. Exames\nlaboratoriais mostram: sódio: 150 mEq/L, potássio: 3,0 mEq/L, HCO3: 18, cloro: 102. peso: 100 kg.\nO tratamento do quadro acima inclui várias condutas; em relação a insulina, qual seria sua\nprescrição?","options":{"A":"Insulina regular SC conforme esquema: 0-180mg/dl: 4U; 181-240: 6U; 241-300: 8U","B":"Insulina NPH SC 0,3u/kg de peso, dividido em 2/3 pela manhã e 1/3 a noite","C":"Insulina regular intravenosa em bomba infusora após bolus de 0,1u/kg","D":"Insulina lantus 0,3u por kilo de peso, 1x ao dia"},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-286701","number":"286701","sourceNumber":"286701","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente 68 anos, chega à emergência com quadro de sonolência. Familiar refere\nperda ponderal, polidipsia, febre e tosse há 7\ndias. Glicemia na admissão: 900 mg/dl. Exames\nlaboratoriais mostram: sódio: 150 mEq/L, potássio: 3,0 mEq/L, HCO3: 18, cloro: 102. peso: 100 kg.\nEm relação ao potássio, qual seria sua conduta?","options":{"A":"Não há necessidade de reposição, já que o tratamento do quadro irá normalizar essa alteração\nhidroeletrolítica.","B":"Repor 20-30meq de potássio nas primeiras 24 horas do tratamento.","C":"Repor 20-30meq de potássio a cada litro de solução usada na hidratação.","D":"Iniciar reposição de potássio, 20- 30meq/hora, antes da aplicação de insulina."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-252211","number":"252211","sourceNumber":"252211","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação à insulinoterapia no Diabetes Mellitus tipo 1 (DM1), assinale a alternativa\nINCORRETA:","options":{"A":"Na fase de ?lua de mel? do DM 1, ou seja, fase de remissão inicial, período compreendido até 2\nanos após o diagnóstico da doença, a dose de\ninsulina diária deve variar entre 0,8 a 1 U/kg/dia.","B":"Na prescrição de insulina para o DM 1, a dose depende da idade, do peso, tempo de doença,\nhorário das refeições, monitoramento glicêmico, HbA1c pretendida, nível de atividade física e\nintercorrências.","C":"A dose basal diária de insulina deve ser em torno de 40% a 60% da dose total de insulina\ncalculada, sendo o restante da dose administrada em forma de bolus antes das refeições.","D":"O esquema de insulinoterapia deve incluir insulina de ação intermediária ou lenta e a insulina de\nliberação rápida ou ultrarrápida, com doses fracionadas em três a quatro aplicações diárias,\nrespeitando a farmacocinética da insulina."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-252273","number":"252273","sourceNumber":"252273","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"F.T.S., 4 anos, 16 kg, masculino, teve diagnóstico de diabetes há 9 meses, chegou ao\npronto-socorro com quadro de desidratação, dor abdominal, hálito cetônico e os seguintes exames:\nglicose = 760 mg/dl; Na = 130 mEq/L; K = 4,4 mEq/L. Recebeu 1.500 ml de Soro Fisiológico (SF\n0,9%) e insulina regular contínua por 6 horas. Os exames após esse período são: pH = 7,1; pCO2 =\n20; Bic = 12; Na = 138; Cl = 117; K = 3,5; glicose = 180. A provável etiologia da acidose ao final\ndas\n6 horas do tratamento inicial é:","options":{"A":"Acidose por acúmulo de ácidos não mensuráveis, pois ânion-gap é normal.","B":"Acidose hiperclorêmica, pois ânion-gap é aumentado.","C":"Acidose hiperclorêmica, pois ânion-gap é normal.","D":"Acidose por acúmulo de ácidos não mensuráveis, pois ânion-gap é aumentado."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-252277","number":"252277","sourceNumber":"252277","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Menina de 5 anos comparece ao pronto-socorro com queixa de náusea, vômitos e dor\nabdominal há 1 dia, com piora agora após ingerir doce em uma festa infantil. Nega diarreia. Refere\nurina em grande quantidade, e voltou a ter enurese noturna há 1 semana. Nega alteração da cor ou\nodor da urina. Ao exame: criança desidratada de 2° grau, hipoativa, porém pedindo para beber\nágua, taquicárdica, porém sem alterações na ausculta cardíaca, taquipneica, porém sem alterações\nna ausculta pulmonar, abdome doloroso a palpação profunda difusamente, sem outras alterações.\nQual sua principal hipótese diagnóstica e conduta nesse caso?","options":{"A":"Diabetes Mellitus, solicitar para colher glicemia amanhã após jejum de 8 horas.","B":"Gastroenterocolite Aguda (GECA), soro de rehidratação via oral.","C":"Diabetes Mellitus, realizar glicemia agora.","D":"Gastroenterocolite Aguda (GECA), soro de rehidratação endovenoso."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-252307","number":"252307","sourceNumber":"252307","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um dos problemas mais frequentes que ocorrem nas UBS é o Diabetes Mellitus.\nAssinale a alternativa CORRETA com relação\naos métodos empregados como parâmetros de\ncontrole do diabetes:","options":{"A":"A HbA1c é um método consolidado que reflete a glicemia média nos últimos quatro meses, e\nseus níveis possuem um grande valor preditivo com o desenvolvimento de complicações.","B":"A glicemia plasmática em jejum é atualmente o mais preciso método para avaliar o controle do\ndiabetes a médio e longo prazos.","C":"A monitorização de glicemia capilar é um método amplamente disponível, que possui a melhor\nrelação custo-efetividade para pacientes que não utilizam insulina.","D":"Estudos comprovam que o uso, de maneira isolada, da monitorização de glicemia capilar como\nforma de avaliar o controle metabólico consiste na melhor maneira de reduzir os níveis glicêmicos."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-208450","number":"208450","sourceNumber":"208450","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Jovem de 22 anos, portador de Diabetes Mellitus tipo 1 desde os 11 anos de idade,\nsem complicações crônicas, em terapia insulínica\nbasal/bolus desde o início do quadro. Atualmente,\ncom insulina degludeca como insulina basal, e lispro como insulina para o bolus corretivo e\nalimentar antes das três principais refeições. Hoje, a glicemia capilar de jejum foi de 132 mg/dl,\nantes do almoço 142 mg/dl e antes do jantar 151 mg/dl, não precisando de bolus corretivo em\nnenhuma das refeições, somente bolus alimentar, ao qual fazia por contagem de carboidratos (CH).\nAjude o paciente efetuando o cálculo de quanto ele irá aplicar de insulina lispro ao ingerir 60 g de\nCH no café, 75 g no almoço e 45 g no jantar, utilizando a razão insulina/carboidrato de 1:15 no café\ne almoço, e 1:20 no jantar.","options":{"A":"06 U; 08 U e 10 U.","B":"04 U; 05 U e 02 U.","C":"18 U; 19 U e 14 U.","D":"08 U; 10 U e 06 U."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-151931","number":"151931","sourceNumber":"151931","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma senhora negra, de 58 anos, obesa (IMC: 39 kg/m²) deu entrada no pronto-socorro\nda cidade por apresentar, nas últimas semanas,\nquadro álgico de membros inferiores,\nacompanhado de sensação de \"agulhadas\" nas pernas e pés, principalmente ao se deitar. Ainda\ncitou poliúria, polidipsia e disúria, que acentuaram na última semana. Notou, também, perda de\npeso (em torno de 12 kg) no último mês, mesmo sem fazer modificações na dieta. Ao contrário, no\ninquérito alimentar, declarou ingerir maior quantidade de massas e frituras. Não costumava fazer\nexercícios regulares. Exames do PS: glicemia aleatória = 360 mg/dl. No dia seguinte, colheu\nexames em jejum, com os seguintes resultados: hemograma e ionograma normais; glicemia = 228\nmg/dl; HbA1c = 10,8%; ureia = 44; Cr = 0,98; TGP = 46; TGO = 38; GGT = 58 e EAS com\n\nincontáveis piócitos. Baseado no caso acima descrito, assinale a resposta CERTA. No caso\nespecífico, de acordo com as diretrizes da\nSociedade Brasileira de Diabetes (SBD), o diagnóstico\nde DM 2 foi dado a partir de qual critério abaixo?","options":{"A":"Pelos níveis de HbA1c > 6,5%.","B":"Pela glicemia \"maior ou igual a\" 200 mg/dl, colhida 2h pós-sobrecarga de 75 g de glicose.","C":"Devido aos sintomas de poliúria, polidipsia e perda ponderal, associado à glicemia casual \"maior\nou igual a\" 200 mg/d.","D":"Glicemia de jejum \"maior ou igual a\" 126 mg/d, sendo o diagnóstico confirmado pela repetição\nda glicemia no dia seguinte."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-103836","number":"103836","sourceNumber":"103836","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente do sexo masculino, 26 anos de idade com diagnóstico de LES (Lupus\nEritematoso Sistêmico) há 10 anos. Encontra-se\ncom doença controlada, usando prednisona em\nbaixas doses (7,5 mg/dia) e cloroquina (150 mg/dia). Tem história de litíase renal e precisa fazer\nreposição de cálcio para prevenção de osteoporose. Qual o cálcio deveria ser prescrito?","options":{"A":"Colecalciferol","B":"Citrato de cálcio","C":"Carbonato de cálcio","D":"Alendronato de sódio"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-46682","number":"46682","sourceNumber":"46682","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Recém-nascido apresenta genitália ambígua, destaca-se a possibilidade de tratar-se de\numa menina virilizada, devido hipoplasia\ncongênita de suprarrenal. O nível sério de 17 - hidróxido\nprogesterona encontra-se elevado. Neste caso, espera-se como principal complicação:","options":{"A":"Esterilidade","B":"Desidratação","C":"Tumor hipófise","D":"Infecção urinária","E":"Malformação renal"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-34141","number":"34141","sourceNumber":"34141","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Clinicamente, níveis aumentados de prolactina estão associados à:","options":{"A":"Amenorreia e galactorreia.","B":"Menometrorragia.","C":"Disforia pré-menstrual.","D":"Tensão pré-menstrual.","E":"Acne e hirsutismo."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-26599","number":"26599","sourceNumber":"26599","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"No hiperparatireoidismo primário, qual o sítio esquelético que usualmente exibe maior\nperda mineral?","options":{"A":"Fêmur total","B":"Porção distal do rádio","C":"Colo do fêmur","D":"Terço proximal do rádio","E":"Coluna vertebral"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-26620","number":"26620","sourceNumber":"26620","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Qual hormônio NÃO é liberado pelo hipotálamo?","options":{"A":"FSH","B":"GnRH","C":"CRH","D":"GHRH","E":"TRH"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-9979","number":"9979","sourceNumber":"9979","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Qual dos tumores da adrenal se apresenta clinicamente por: cefaleia, sudorese,\npalpitações e hipertensão arterial de\ndifícil controle assim como estudo de imagem por Ressonância\nMagnética do Abdome demonstrando nódulo tumoral com hipersinal em T2?","options":{"A":"Feocromocitoma.","B":"Adenoma da adrenal.","C":"Tumor metastático para adrenal.","D":"Tumor adrenal produtor de cortisol.","E":"Tumor de adrenal produtor de aldosterona."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-294482","number":"294482","sourceNumber":"294482","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Adolescente, 16 anos de idade, chega à UBS com quadro de poliúria há,\naproximadamente, 40 dias. Refere fadiga\nfrequente, o que atribui ao aumento de peso, durante a\npandemia. Nega febre, disúria e outros sintomas. Ao exame, IMC: 29kg/m²; acima do 95º percentil;\nbom estado geral, eupneica, hidratada, afebril, corada. Apresenta eritema macular hiperemiado sob\nambas as mamas, pruriginoso. O exame de urina I mostra: pH: 7,2; Densidade: de 1,01; Ausência\nde cetonas, bilirrubina, urobilinogênio, sangue e nitrito; presença de glicose ++; raros leucócitos\ne\nraras células epiteliais. Glicemia em jejum foi de 100mg/dL Indique o exame que permite melhor\navaliar o diagnóstico associado dessa paciente.","options":{"A":"Cortisol matinal.","B":"Hemoglobina glicada.","C":"Glicemia aleatória.","D":"Triglicérides."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-294492","number":"294492","sourceNumber":"294492","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O Brasil apresenta um perfil epidemiológico complexo, com uma sobreposição de\nproblemas de saúde, muitas vezes, no mesmo território: persistência de alguns agravos\ntransmissíveis e ocorrência de ciclos epidêmicos de outros; peso importante, e crescente, na\nmorbidade e na mortalidade das doenças crônicas não transmissíveis; e alta ocorrência de\nacidentes e violência. Essa múltipla carga se concentra, principalmente, nos grupos mais\nvulneráveis do ponto de vista social e econômico, como resultado das profundas desigualdades\nque ainda persistem. Esse quadro, também condicionado pelos rápidos processos de urbanização\ne de envelhecimento da população, exige que o SUS realize análises e planejamentos capazes de\nencontrar as melhores estratégias para garantir o efetivo acesso da população, ao mesmo tempo\nque lidere agendas multissetoriais que incidam nos determinantes sociais e econômicos. No grupo\ndas doenças crônico degenerativas, as doenças cardiovasculares ocupam importante papel como\ncausa de morbimortalidade no Brasil. A melhor forma de atenuar essa causa, em termos de\n\ncusto-eficácia, é","options":{"A":"promover o controle da hipertensão arterial.","B":"reduzir o sedentarismo da população.","C":"modificar hábitos alimentares.","D":"reduzir o tabagismo."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-284576","number":"284576","sourceNumber":"284576","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, 20 anos de idade, estava acompanhada da mãe no metrô quando apresentou\nperda da consciência, seguida de rigidez\nmuscular, abalos musculares difusos e perda\nesfincteriana. A equipe do metrô iniciou rapidamente os primeiros-socorros, colocando algo macio\nsob a cabeça da paciente até cessarem os abalos, que duraram cerca de um minuto. A mãe ficou\nbastante assustada e relatou que a paciente era portadora de diabetes mellitus tipo 1. Nega outras\ncomorbidades. Nunca havia apresentado quadro semelhante. Neste momento, a paciente\nencontra-se ainda inconsciente, com ventilação espontânea. Indique o exame complementar e a\nmedicação mais adequada nesse momento.","options":{"A":"Eletroencefalograma e diazepam intravenoso.","B":"Tomografia de crânio e diazepam intravenoso.","C":"Glicemia capilar e insulina subcutânea.","D":"Glicemia capilar e glucagon subcutâneo."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-62812","number":"62812","sourceNumber":"62812","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente, sexo masculino, 25 anos de idade, com história de perda de peso, astenia e\nquadro depressivo, há cerca de 3 anos. Admitido em hospital com quadro de vômitos e dor\nabdominal. Familiares relatam quadro de alteração do comportamento e fraqueza de membros\ninferiores (paraparesia) associado à disfunção esfincteriana. Avaliação laboratorial evidenciou\nglicose: 65 mg/dl; sódio: 124 mEq/L; potássio: 5,8 mEq/L. A principal suspeita diagnóstica para\njustificar a admissão hospitalar é:","options":{"A":"Síndrome carcinoide.","B":"Porfiria intermitente aguda.","C":"HIV agudo.","D":"Hipertireoidismo.","E":"Insuficiência adrenal."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-62817","number":"62817","sourceNumber":"62817","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente, sexo masculino, 25 anos de idade, com história de perda de peso, astenia e\nquadro depressivo, há cerca de três anos. Admitido em hospital com quadro de vômitos e dor\nabdominal. Familiares relatam quadro de alteração do comportamento e fraqueza de membros\ninferiores (paraparesia) associado à disfunção esfincteriana. Avaliação laboratorial evidenciou\nglicose: 65 mg/dl, sódio: 124 mEq/L, potássio: 5,8 mEq/L. A principal suspeita diagnóstica para\njustificar a admissão hospitalar é:","options":{"A":"adrenoleucodistrofia.","B":"infecção do sistema nervoso central.","C":"mielite transversa.","D":"compressão medular.","E":"neuropatia periférica."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-49290","number":"49290","sourceNumber":"49290","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem, 25 anos de idade, vem há um mês com cãibras e fadiga muscular, as quais\natribui a início de atividade física.\nRelata níveis elevados de PA em exames anteriores. Tem história\nfamiliar de hipertensão e pai faleceu aos 42 anos de idade de AVC hemorrágico. No exame,\napresenta IMC: 25, mucosas coradas, hidratado, PA: 160 x 100 mmHg, sem variação entre os\nmembros. Ausculta cardíaca e respiratória sem alterações, abdome sem visceromegalias e\nextremidades sem edemas, sem sopros à ausculta. Traz exames: hemograma normal, creatinina:\n0,9 mg/dl, ureia: 29 mg/dl. A melhor conduta inicial para esse paciente é dosar:","options":{"A":"Cortisol sérico e urinário;","B":"Potássio sérico e urinário;","C":"Metanefrinas na urina;","D":"Sódio em urina de 24 horas;","E":"ACTH sérico."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-13334","number":"13334","sourceNumber":"13334","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente, sexo masculino, 57 anos de idade, hipertenso e portador de fibrilação atrial\ncrônica, cursando há 3 horas com dor em membro inferior esquerdo, associado à palidez cutânea,\nparestesia e diminuição da força muscular. Não possui antecedente de claudicação. Ao exame\nfísico, apresenta fáscies de dor aguda, ausência, ausência de pulsos tibiais posteriores e pediosos\nno membro inferior esquerdo. Pulsos contralaterais normais. A síndrome de neoplasia endócrina\nmúltipla tipo I corresponde às seguintes neoplasias:","options":{"A":"Adenomas da hipófise, hiperplasia paratireoidea e neoplasias das ilhotas pancreáticas","B":"Carcinoma medular da tireoide, feocromocitoma suprarrenal e hiperplasia paratireoidea","C":"Carcinoma medular da tireoide, feocromocitoma suprarrenal e neuromas mucosos","D":"Adenomas da hipófise, hiperplasia paratireoidea e feocromocitoma suprarrenal","E":"Feocromocitoma suprarrenal, hiperplasia paratireoidea e adenomas da hipófise"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-281900","number":"281900","sourceNumber":"281900","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Pesquisa Nacional de Saúde realizada pelo Instituto Brasileiro de Geografia e\nEstatística (IBGE) mostrou prevalência de\ndiabetes melito de 19,9% nos indivíduos na faixa etária\nde 65 a 74 anos de idade. Está correto o item:","options":{"A":"No idoso diabético há redução da mortalidade e redução da capacidade funcional com\nconsequente aumento do risco de institucionalização.","B":"No idoso diabético há aumento da mortalidade e aumento da capacidade funcional com\nconsequente aumento do risco de institucionalização.","C":"No idoso diabético há aumento da mortalidade e redução da capacidade funcional com\nconsequente aumento do risco de institucionalização.","D":"No idoso diabético há aumento da mortalidade e redução da capacidade funcional com\nconsequente menor risco de institucionalização."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-281904","number":"281904","sourceNumber":"281904","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"É fundamental, além do rastreamento para complicações, uma avaliação\nmultidimensional do indivíduo idoso diabético. Sendo correto o item:","options":{"A":"Pelo benefício do diagnóstico e do tratamento precoce na prevenção de complicações.","B":"Pelo benefício do diagnóstico e do tratamento tardio na prevenção de complicações.","C":"Pelo benefício do diagnóstico e não do tratamento precoce na prevenção de complicações.","D":"Pelo benefício do diagnóstico e do tratamento precoce na manutenção de complicações."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249975","number":"249975","sourceNumber":"249975","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considerando a avaliação da neuropatia autonômica cardiovascular NAC por diabetes,\npodemos concordar que:","options":{"A":"Apresentam achados que estão relacionados com baixa frequência de hipertrofia ventricular\nesquerda e eventos cardiovasculares sérios,\nfatais e não fatais, em pacientes diabéticos com NAC.","B":"Apresentam achados que estão relacionados com alta frequência de hipotrofia ventricular\nesquerda e eventos cardiovasculares sérios,\nfatais e não fatais, em pacientes diabéticos com NAC.","C":"Apresentam achados que estão relacionados com alta frequência de hipertrofia ventricular direita\napenas, e eventos cardiovasculares sérios, fatais e não fatais, em pacientes diabéticos com NAC.","D":"Apresentam achados que estão relacionados com alta frequência de hipertrofia ventricular\nesquerda e eventos cardiovasculares sérios,\nfatais e não fatais, em pacientes diabéticos com NAC."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-249735","number":"249735","sourceNumber":"249735","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A nefropatia diabética pode ser diagnosticada através da obtenção de exames\nalterados em duas de três avaliações realizadas em intervalos de três a seis meses.\n\npode ser considerado um valor alterado. A alternativa que preenche,\nCORRETAMENTE, a lacuna do trecho acima é:","options":{"A":"Ureia sérica de 60 mg/dl.","B":"Creatinina sérica de 1,7 mg/dl.","C":"Microalbuminúria de 24h ? 14 mg/24h.","D":"Concentração de albumina de 10 mg/dl em amostra isolada de urina.","E":"Índice albumina-creatinina ? 30 mg/g obtido em amostra isolada de urina."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215601","number":"215601","sourceNumber":"215601","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A monitorização de glicose em sistema flash (Flash Glucose Monitoring ? FGM):\n\ntrata-se de um sensor de glicose que pretende substituir as medidas de glicemia capilar, com uma\ntecnologia que utiliza glicose oxidase e complexos de ósmio para evitar interferência de oxigênio;\npor isso, não requer calibração por glicemia capilar. Somente se mostra INCORRETO que:","options":{"A":"Nele, o usuário sabe o valor e a tendência de glicose apenas passando o leitor sobre o sensor, o\nque pode ser feito múltiplas vezes ao dia,\ncom atualizações a cada minuto.","B":"Suas principais limitações são o lag time, em torno de 5 minutos, e as discrepâncias que podem\nocorrer entre os valores de glicose\nintersticial nos momentos de hipoglicemia e de queda ou\naumento abrupto da glicose intersticial, de acordo com as setas de tendência.","C":"Nessas situações específicas, não se recomenda medir a glicemia capilar, caso se trate de um\nmomento de tomada de decisão pelo paciente.","D":"Alguns usuários relatam falta de acurácia do sensor nas primeiras horas de uso, o que não\ncostuma persistir nos dias subsequentes."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215610","number":"215610","sourceNumber":"215610","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Marque, apenas, a CORRETA sobre as indicações para o uso de monitorização\ncontínua de glicose Diabetes mellitus tipo 1.","options":{"A":"Recomenda-se CGM para todos os pacientes adultos com DM2, especialmente nos casos de\nhistória de hipoglicemia grave e hipoglicemia assintomática, assim como para auxiliar na correção\ndas hiperglicemias.","B":"Recomenda-se CGM para pacientes adultos com DM1, especialmente nos casos de história de\nhipoglicemia grave e hipoglicemia assintomática, assim como para auxiliar na correção das\nhiperglicemias.","C":"Recomenda-se CGM para pacientes adultos com DM1, exceto nos casos de história de\nhipoglicemia grave e hipoglicemia assintomática, assim como para auxiliar na correção das\nhiperglicemias.","D":"Recomenda-se CGM para pacientes adultos com DM1, especialmente nos casos de história de\nhipoglicemia grave e hipoglicemia assintomática, mas não para auxiliar na correção das\nhiperglicemias."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215616","number":"215616","sourceNumber":"215616","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A monitorização contínua de glicose (Continuous Glucose Monitoring ? CGM) possibilita\nmedir a concentração de glicose no líquido\nintersticial, seu sensor é implantado de maneira quase\nsempre indolor, por meio de um aplicador específico. O filamento do sensor tem espessura capilar\ne contém glicose oxidase. A glicose difunde-se por uma membrana para alcançar a camada com a\nenzima, que converte a concentração de glicose em um sinal eletrônico diretamente proporcional a\nela. Marque a opção INCORRETA.","options":{"A":"Além do valor absoluto de glicose intersticial, o indivíduo que realiza CGM observa setas de\ntendência, que indicam se a glicose está subindo, apenas.","B":"A seta de estabilidade denota alteração da glicose intersticial em velocidade inferior a 1\nmg/dl/min.","C":"As setas de subida ou descida lenta indicam alteração da glicose em velocidade entre 1 e 2\nmg/dl/min.","D":"As setas de subida ou descida rápida, finalmente, indicam alteração da glicose em velocidade\nsuperior a 2 mg/dl/min."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-218115","number":"218115","sourceNumber":"218115","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"João, 48 anos, vai à consulta, levando exames laboratoriais (glicemia de jejum 150\nmg/dl) realizados, porque \"sua mãe tem\ndiabetes\". Nega comorbidades, é sedentário, nega\ntabagismo, tem alimentação rica em carboidratos de alto índice glicêmico, diz não gostar muito de\nfrutas e verduras. Ao exame, IMC de 27, circunferência abdominal 93 cm. Considerando a\nabordagem inicial mais adequada nesse caso clínico, é CORRETO afirmar que:","options":{"A":"Como João é classificado como baixo risco, deve-se repetir o rastreamento em 3 a 5 anos\ndepois.","B":"Por João ser classificado como alto risco, está indicado o encaminhamento para\nendocrinologista.","C":"Se deve ofertar rastreamento para diabetes já que ele tem alto risco para o desenvolvimento\ndeste agravo.","D":"Um antidiabético oral, sulfonílureia, metformina, 850 mg deve ser prescrito, para tratamento da\npré-diabetes.","E":"João deve ser orientado para que sejam feitas intervenções para mudanças do estilo de vida,\nnão sendo necessários testes laboratoriais."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-218125","number":"218125","sourceNumber":"218125","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"João, 48 anos, vai à consulta, levando exames laboratoriais (glicemia de jejum 150\nmg/dl) realizados, porque \"sua mãe tem diabetes\".\nNega comorbidades, é sedentário, nega\ntabagismo, tem alimentação rica em carboidratos de alto índice glicêmico, diz não gostar muito de\nfrutas e verduras. Ao exame, IMC de 27, circunferência abdominal 93 cm. João retorna à consulta\nna Unidade de Saúde da Família para acompanhamento do seu tratamento para diabetes. Hoje,\ncom 52 anos, está em uso de 14 unidades de insulina NPH à noite, além de metformina 3 vezes ao\ndia. Algumas das complicações às quais este paciente com diabetes pode desenvolver estão\ndescritas nas alternativas abaixo, assinale a CORRETA.","options":{"A":"O rastreamento da retinopatia e microalbuminúria devem ser realizados após 10 anos de\ndiagnóstico de DM.","B":"A avaliação da sensibilidade tátil dos pés é realizada com monofilamento de 50 g em um ponto\nde cada pé.","C":"As complicações agudas, que podem ocorrer com João, são: hipoglicemia, cetoacidose e\nretinopatia.","D":"Um orientação aconselhada na consulta com João deve ser o reconhecimento dos sintomas de\nhipoglicemia.","E":"Caso João chegasse à unidade com tontura, sudorese e tremor, dever-se-ia suspeitar de\nhiperglicemia."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-157616","number":"157616","sourceNumber":"157616","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre o Hiperparatiroidismo Primário, marque a alternativa INCORRETA.","options":{"A":"Dentre as manifestações clínicas do Hiperparatiroidismo Primário, podemos destacar: dor óssea,\npolidpsia, anorexia, depressão, coma.","B":"Indicações cirúrgicas para Hiperparatiroidismo Primário incluem indivíduos menores que 50\nanos, avaliação densitométrica com perda óssea\nsuperior a 2,5 desvios-padrão em relação ao pico\nde massa óssea, redução do clearance de creatinina em 30%, excreção urinária de cálcio superior\na 400 mg, nível de calcemia total de 1,0 mg/dL acima do limite superior da normalidade.","C":"O tratamento cirúrgico é a única terapêutica definitiva para o hiperparatiroidismo primário,\nembora haja alguma perspectiva de tratamento clínico no futuro com agonistas do receptor\nextracelular de cálcio.","D":"Em geral, o doente com Hiperparatiroidismo Primário que vai ser submetido a tratamento\ncirúrgico não requer preparo pré-operatório\nespecífico. Se os níveis de cálcio estiveram maior que\n14mg/dl, podem requerer preparo com hiper-hidratação, diuréticos e Fósforo."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-350854","number":"350854","sourceNumber":"350854","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 58 anos teve um infarto agudo do miocárdio (IAM) há 3 meses, quando foi\ndiagnosticado como hipertenso. Está em uso de losartana 50 mg/dia, sinvastatina 10 mg/dia e AAS\n100 mg/dia, com boa tolerância. É sedentário e refere ingestão diária de frituras. Informa pai\nfalecido aos 54 anos por IAM e mãe diabética. Ao exame físico: acantose nigricans cervical,\npressão arterial 124/80 mmHg, IMC 33 kg/m², circunferência abdominal 108 cm, ausculta\ncardiopulmonar fisiológica, sem edemas. Os exames laboratoriais evidenciaram TSH 3,0 uUI/mL\n(VR: 0,5-5,0 uUI/mL), TGO 38 U/L (VR até 40 U/L), TGP 40 U/L (VR até 41 U/L), glicemia de jejum\n98 mg/dL (VR: 70 a 99 mg/dL), colesterol total 224 mg/dL (VR menor que 190 mg/dL), HDL 36\nmg/dL (VR maior que 40 mg/dL), LDL 148 mg/dL (VR menor que 50 mg/dL), triglicerídeos 180\nmg/dL (VR menor que 150 mg/dL). Assinale a abordagem terapêutica mais adequada para\ndislipidemia desse paciente:","options":{"A":"Aumentar sinvastatina para 20 mg/dia e estabelecer dieta hipolipídica.","B":"Associar ezetimiba 10 mg/dia e iniciar ciprofibrato 100 mg/dia.","C":"Trocar sinvastatina por rosuvastatina 20 mg/dia.","D":"Trocar sinvastatina por atorvastatina 20 mg/dia."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-350853","number":"350853","sourceNumber":"350853","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 56 anos, tabagista, hipertenso há 5 anos, descobriu ter Diabetes Mellitus\ntipo 2 (DM2) há 1 ano, em exames de\nrotina. Recentemente, iniciou dor precordial em aperto, aos\ngrandes esforços, com irradiação para o pescoço, intensidade moderada, que alivia com o repouso.\nFaz uso de losartana 100 mg/dia, AAS 100 mg/dia e há 3 meses ajustou posologia da metformina\npara 850 mg 3 vezes ao dia. Ganhou 3 kg nos últimos 6 meses e reconhece exagerar nos\ncarboidratos. Ao exame físico: bom estado geral, eupneico, acantose nigricans e acrocórdons\ncervicais, pressão arterial 110/70 mmHg, frequência cardíaca 68 bpm, IMC 29 kg/m², circunferência\nabdominal 98 cm, ausculta cardiopulmonar fisiológica, sem edemas. Os exames laboratoriais\nevidenciaram hemoglobina 13,6 g/dL, creatinina 0,9 mg/dL, glicemia de jejum 166 mg/dL, HbA1c\n8,0%. Para tratamento do DM2 desse paciente, qual a conduta mais adequada?","options":{"A":"Manter metformina e iniciar liraglutida.","B":"Reduzir a dose da metformina e iniciar pioglitazona.","C":"Prescrever uma combinação de metformina com gliptina.","D":"Manter metformina e associar uma sulfoniureia em dose baixa."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-350891","number":"350891","sourceNumber":"350891","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 18 anos é admitido na emergência com náuseas, vômitos e sonolência.\nExame físico não evidencia hipoperfusão\ntecidual. Glicemia capilar 258mg/dL. Coletada gasometria\narterial: pH 7,2 Bicarbonato 10mEq/L PaCO? 30mmHg Na 142mEq/L Cloro 98mEq/L Lactato\n0,8mmol/L. Qual a principal hipótese diagnóstica?","options":{"A":"Sepse.","B":"Cetoacidose diabética.","C":"Síndrome de Fanconi.","D":"Gastroenterite aguda."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-321300","number":"321300","sourceNumber":"321300","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 24 anos, portador de Diabetes Mellitus tipo 1, desde os 11 anos, deu\nentrada no Pronto-Socorro com quadro de dor\nabdominal, náuseas e vômitos, há 10 horas, tendo\nevoluído com rebaixamento do nível de consciência. História de poliúria e polidipsia, há 5 dias. Ao\nexame físico: sonolento, desidratado (++/4+), emagrecido; Ausculta Cardíaca: RCR em 2T, BNF,\nsem sopros, Pressão Arterial: 90 / 60 mmHg, Frequência Cardíaca: 104 bpm; Ausculta Pulmonar:\nMVU, presença de crepitações finas em base direita, taquipneico, saturação de oxigênio: 90%;\nabdome flácido, indolor à palpação, sem visceromegalias. Exames laboratoriais: gasometria com\npH 7,1; hemograma: leucócitos 16.000/mm³ com desvio à esquerda; glicemia 352 mg/dl (VR 70 a\n99); potássio 3,0 mEq/L (VR 3,5 a 5,0); cetonúria fortemente positiva. Considerando a principal\nhipótese diagnóstica, além da antibioticoterapia, qual a conduta inicial adequada?","options":{"A":"Hidratação endovenosa e insulinoterapia.","B":"Insulinoterapia e reposição de bicarbonato.","C":"Hidratação endovenosa e reposição de potássio.","D":"Insulinoterapia, reposição de potássio e bicarbonato."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-292817","number":"292817","sourceNumber":"292817","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 18 anos é admitido na emergência com quadro de redução do nível de\nconsciência, náuseas, vômitos e dor abdominal difusa. Apresenta glicemia capilar de 300 mg/dL e\ngasometria com acidose metabólica. Com o objetivo de confirmar o diagnóstico da emergência\nclínica em questão, qual exame deveria ser solicitado?","options":{"A":"Hemoglobina glicada.","B":"Sumário de urina.","C":"Lactato sérico.","D":"Hemograma."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-292826","number":"292826","sourceNumber":"292826","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, 24 anos, diagnóstico de diabetes mellitus tipo 1 aos 10 anos, em uso de\ninsulina e losartana 50 mg/dia, e\ndiagnóstico de lúpus eritematoso sistêmico aos 20 anos, em uso\nde hidroxicloroquina 400 mg/dia, prednisona 5 mg/dia, e vitamina D3 1.000 UI/dia, relata há 4\nmeses apresentar turvação visual, fadiga, dispneia aos médios esforços e ganho de peso. Ao\nexame: anasarca e PA 150 x 80 mmHg. Exames complementares: hemograma, PCR, TGO, TGP,\nTP: normais; VHS 28 mm/h (VR 20 mm na 1ª hora); Cr 1.5 mg/dl (VR 1,2 mg/dl); Ur 60 mg/dl (VR\n15?45 mg/dl); albumina 3,0 mg/dl (VR 3,5?4 mg/dl); Hb glicada 6,6%; colesterol total 250 mg/dl (VR\n\n< 200 mg/dl), LDL 140 mg/dl (VR < 100 mg/dl); triglicerídeos 300 (VR < 150 mg/dl); SU: proteína 4+;\nproteinúria em 24h: 4 g/24h; fator antinúcleo reagente 1:160 padrão pontilhado fino denso.\n\nSorologias HIV, anti-HBsAg, anti-HCV e VDRL: negativas. Que alteração na investigação\ncomplementar confirmaria o diagnóstico mais provável?","options":{"A":"Dosagem sérica elevada de CH50, C3 e C4.","B":"Nódulos de Kimmelstiel-Wilson na biópsia renal.","C":"Depósitos imunes subendoteliais focais glomerulares na biópsia renal.","D":"Anticorpo anticitoplasma de neutrófilos reagente no padrão citoplasmático."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-292866","number":"292866","sourceNumber":"292866","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Ainda na consulta de Edberto, foi verificada glicemia capilar em jejum de 158 mg/dl, e o\nmesmo questiona o significado clínico desse achado. Corretamente, você responde que a glicemia\ncapilar ainda não está validada para diagnóstico, mas a glicemia capilar alterada sugere alteração\nno exame de glicemia sérica plasmática. Vendo que não constam exames prévios no prontuário de\nEdberto, você, então, solicita exames laboratoriais para avaliação metabólica e agenda o retorno.\nApós um mês, Edberto retorna com os exames complementares, que trazem glicemia de jejum de\n160 mg/dl, HbA1c = 8,0%, Colesterol Total = 270 mg/dl, HDL = 30 mg/dl, Triglicerídeos séricos =\n300 mg/dl. Não havia alterações em eletrólitos, nem alterações sugestivas de nefropatia diabética\nou doença coronariana isquêmica. Assinale a alternativa que contempla a opção terapêutica\nadequada quanto à hiperglicemia.","options":{"A":"Orientar mudanças de estilo de vida (MEVs) e retorno em seis meses com os mesmos exames\nlaboratoriais para nova avaliação.","B":"Introduzir Metformina associada a MEVs. A associação de um segundo antidiabético pode ser\nconsiderada e pactuada individualmente.","C":"Iniciar a Insulinoterapia plena para o controle glicêmico precoce de imediato. Depois, descalonar\npara terapia oral associada a MEVs.","D":"Iniciar terapia farmacológica em esquema de Insulinoterapia Basal Plus: (Insulinoterapia Basal +\nInsulinoterapia Prandial + Hipoglicemiantes orais)."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-259759","number":"259759","sourceNumber":"259759","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente, sexo masculino, 53 anos, hipertenso e diabético há 10 anos, comparece em\nconsulta de rotina para mostrar exames. Queixa-se de perda de peso. Ao exame apresenta BEG,\ncorado, hidratado, eupneico, PA=120x80, 70 kg, AP fisiológica AC RCR 3T B4, Extremidades: ppp,\nedema de mmii+/4+ sem cacifo. Exames complementares: GJ=180mg/dl; HbA1c=8%,\ncreatinina=1,8, TFG=42ml/min. Medicação em uso: gliclazida MR 120 mg/d, metformina 2,5 g/d,\nenalapril 40 mg/d, furosemida 40 mg/d. Qual a conduta CORRETA em relação ao tratamento\nfarmacológico da diabetes?","options":{"A":"Iniciar insulina ?bed time? e reduzir metformina.","B":"Associar terceiro antidiabético oral e reduzir a gliclazida.","C":"Iniciar insulina ?bed time?, mantendo as outras medicações.","D":"Associar terceiro antidiabético oral, mantendo as outras medicações."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-234073","number":"234073","sourceNumber":"234073","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher de 24 anos procura unidade básica de saúde preocupada com o risco de\ndesenvolver diabetes (DM), uma vez que a mãe\nfoi diagnosticada recentemente com pré-diabetes.\nTrouxe exames de glicemia de jejum, hemoglobina glicada e teste de tolerância oral à glicose com\n75g com valores de 94 mg/dL, 5,5% e 136 mg/dL, respectivamente. Antecedentes: DM gestacional\nhá 2 anos; acompanhamento psiquiátrico por motivo desconhecido. Ao exame: Normotensa, IMC\n22,7 kg/m². O médico orienta quanto ao estilo de vida e decide rastrear para DM a cada 3 anos.\n\nEntretanto, recebe informação durante a consulta que o psiquiatra está cogitando iniciar uma\nmedicação. Qual das medicações abaixo, caso prescrita, terá a maior probabilidade de fazer com\nque o médico necessite modificar o rastreamento inicialmente proposto?","options":{"A":"Setralina.","B":"Topiramato.","C":"Olanzapina.","D":"Bupropiona."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-199770","number":"199770","sourceNumber":"199770","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem, 62 anos, obeso e hipertenso, procurou assistência médica na UPA com queixa\nde cansaço, perda de peso, poliúria e\npolidipsia. Ao exame, IMC = 31 kg/m², desidratado +/4+, sem\noutros achados clínicos relevantes. Exames laboratoriais: glicemia = 258 mg/dl, creatinina = 1,7\nmg/dl; taxa de filtração glomerular estimada (CKD-EPI) = 42,3 ml/min/1,73 m² e A1C = 9,8%.\n\nSumário de urina: glicose+++ /cetonas negativo. LEGENDA: IMC: Índice de Massa Corpórea;\nCKD-EPI: Chronic Kidney Disease Epidemiology\nCollaboration; AIC: hemoglobina glicada. Qual o\nesquema terapêutico mais apropriado para este paciente?","options":{"A":"Gliclazida e insulina.","B":"Metformina e insulina.","C":"Gliclazida e sitagliptina.","D":"Sitagliptina e metformina."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-172985","number":"172985","sourceNumber":"172985","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente feminina, 24 anos, moradora de rua, admitida com quadro relatado de\nnáuseas, vômitos e dor abdominal há 3 dias, com\npiora progressiva e obnubilação mental nas\núltimas 24 horas. Sem uso de drogas ou álcool. Comorbidades e uso de medicações são\ndesconhecidas. Ao exame físico: PA = 90 x 60 mmHg; FC = 120 bpm; FR = 32 irpm; sonolenta,\ndesidratada 3+/4+, presença de hálito cetônico. Exames laboratoriais: hemograma com leucocitose\nsem desvio; urina com cetonúria 3+/4+ e glicosúria 4+/4+; glicemia = 500 mg/dl; Na = 135 mg/dl\n(VR: 135-145 mg/dl); K = 5,5 mEq/L; pH = 7,16 HCO? = 12 mEq/L (VR: 22-26 mEq/L); pCO? = 28\n\nmmHg (VR: 35-45 mmHg); lactato = 2,5 mEq/L (VR: até 2 mEq/L); radiografia de tórax normal;\neletrocardiograma com taquicardia sinusal. LEGENDA: PA: Pressão Arterial; FC: Frequência\nCardíaca; bpm: batimentos por minuto; FR: Frequência Respiratória; irpm: incursões respiratórias\npor minuto; Na: sódio; K: potássio; HCO?: bicarbonato; VR: Valor de Referência. Considerando o\ndiagnóstico mais provável e sua fisiopatologia, qual a afirmativa CORRETA?","options":{"A":"O quadro é de acidose metabólica com ânion-gap elevado, causada primariamente pela perda\nde bicarbonato.","B":"Com o tratamento adequado, a hiperglicemia deve apresentar resolução posterior à correção da\ncetose.","C":"Níveis elevados de glucagon e catecolaminas, isoladamente, são capazes de produzir o quadro\nclinicolaboratorial.","D":"A cetose que ocorre se relaciona à lipólise, liberação de ácidos graxos livres e formação\nhepática de corpos cetônicos."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-172961","number":"172961","sourceNumber":"172961","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente masculino de 59 anos, com diagnóstico de diabetes há 10 anos, comparece a\nUBS para consulta de rotina, apresentando\núlcera superficial em pododáctilo, com eritema e celulite\nao redor (atingindo 1,0 cm da sua borda). Estado geral bom, afebril, normotenso, orientado e\ncomunicativo, com frequência cardíaca de 72 bpm. Negava internações anteriores para tratamento\nde infecções ou feridas no corpo ou uso recente de glicocorticoide ou antibióticos. Qual deve ser a\nterapêutica medicamentosa de primeira escolha?","options":{"A":"Amoxicilina-Clavulanato por 7 dias.","B":"Penicilina benzatina em dose única.","C":"Ciprofloxacino por 21 dias.","D":"Cefalexina por 15 dias."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-2/172961.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-150854","number":"150854","sourceNumber":"150854","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente masculino, 48 anos, hipertenso e diabético tipo 1, comparece a serviço de\nemergência com queixa de náuseas, vômitos e dor abdominal que se iniciaram há 2 dias. Uma\nsemana antes do início dos sintomas, relatou quadro de febre baixa e diarreia aguda, que\napresentou melhora sem terapêutica específica ao longo dos dias. Por não se alimentar devido\nhiporexia, diminuiu a dose de suas medicações orais e da insulina. Ao exame físico: PA 102 x 72\nmmHg, P 118 bpm, FR 28 rpm. Apresenta-se em estado regular, com respirações profundas,\nabdome dolorido difusamente, com ruídos levemente diminuídos. Paciente é submetido à\noxigenioterapia e expansão volêmica. Bioquímica sérica evidencia: Glicemia 500 mg/dL, sódio 127\nmEq/L, potássio 3,0 mEq/L, cloro 99 mEq/L, creatinina sérica 1,5 mg/dL, ureia 72 mg/dL.\nGasometria arterial (em Venturi 40%): pH 7,16, pCO2 31 mmHg, Bic 10 mEq/L, pO2 236 mmHg,\nSO2 99,6%, sumário de urina positivo para cetonas 2+. Qual terapêutica endovenosa deve ser\ntomada a seguir?","options":{"A":"Infusão de insulina.","B":"Reposição de sódio.","C":"Reposição de potássio.","D":"Reposição de bicarbonato."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-127010","number":"127010","sourceNumber":"127010","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente feminina, primeiro pós-operatório de tireoidectomia por suspeita de câncer de\ntireoide, encontra-se bastante ansiosa e referindo adormecimento perioral. O médico faz o sinal de\nChvostek que é francamente positivo. Qual o diagnóstico dessa paciente?","options":{"A":"Hipocalcemia devido a hipoparatireoidismo iatrogênico.","B":"Crise tireotóxica devido manipulação da glândula tireoide.","C":"Transtorno de ansiedade generalizado com alcalose devido hiperventilação.","D":"Hipotireoidismo agudo devido a reposição ineficiente dos hormônios tireoideanos."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-127016","number":"127016","sourceNumber":"127016","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 56 anos, hipertenso, obeso, sedentário, recebeu diagnóstico recente de\ndiabetes mellitus. Seus exames na consulta\ninicial revelaram uma glicemia de jejum de 126 mg/dl;\nhemoglobina glicada de 8,0%; triglicerídeos de 250 mg/dl e HDL-colesterol de 30 mg/dl. Retornou\npara consulta de reavaliação referindo intolerância gastrointestinal à metformina. Além das medidas\nnão farmacológicas, a conduta medicamentosa mais adequada nesse momento é prescrever:","options":{"A":"Gliptina.","B":"Metiglinida.","C":"Sulfonilureia.","D":"Insulina NPH subcutânea."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-81290","number":"81290","sourceNumber":"81290","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente feminina, 70 anos, em tratamento quimioterápico para carcinoma escamoso\nde pulmão com metástases ósseas e pulmonares,\nprocura atendimento por apresentar\ndesorientação, anorexia e vômitos com início há uma semana. Está desidratada 2+/4+.\n\nNormotensa. Considerando uma síndrome paraneoplásica como causa provável do quadro clínico\nda paciente, qual dosagem sérica tem maiores\nchances de estabelecer o diagnóstico?","options":{"A":"Sódio.","B":"Cálcio.","C":"Cortisol.","D":"Glicemia."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-81292","number":"81292","sourceNumber":"81292","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente masculino, 72 anos, sem comorbidades, vem à consulta de rotina. Quando\nquestionado, refere que apresentou uma queda da própria altura há 4 meses. Sem outros episódios\nprévios ou posteriores; sem outras queixas. Não usa medicações. Marcha e equilíbrio normais.\n\nQual a recomendação mais adequada para prevenir queda nesse paciente?","options":{"A":"Suplementar vitamina D.","B":"Indicar uso de sapato ortopédico.","C":"Recomendar programa de exercício.","D":"Encaminhar para avaliação oftalmológica."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-65766","number":"65766","sourceNumber":"65766","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente de 60 anos é internado na UTI, no pós-operatório de necrosectomia por\npancreatite necro-hemorrágica. Apresenta estado geral\ngrave, taquicardia, hipotensão responsiva à\nadministração de fármacos vasoativos, fraqueza muscular que impede desmame de ventilador\npulmonar mecânico, náusea, vômitos e febre. As culturas são negativas para crescimento\nbacteriano. Os exames laboratoriais indicam: hipoglicemia, hiponatremia e hipercalemia. Dentre as\nalterações hormonais que ocorrem no período perioperatório de pacientes graves, assinale a\nalternativa que justifica os achados clínicos e laboratoriais descritos no caso acima.","options":{"A":"Insuficiência adrenal.","B":"Resistência à insulina.","C":"Excesso de catecolaminas.","D":"Resistência adquirida ao GH.","E":"Insuficiência de produção de TSH."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-65771","number":"65771","sourceNumber":"65771","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 47 anos comparece com dispneia aos moderados esforços e parestesias\nnas mãos. Tem diagnóstico de diabetes e\nhipertensão há 5 anos. Durante o interrogatório por\nórgãos, o médico descobre crescimento dos pés e mãos, hiper-hidrose, ronco e mudança da voz.\nNo exame físico, há quarta bulha, prognatismo e macroglossia. Qual dos exames abaixo deve ser\nusado como screening para o diagnóstico desse paciente?","options":{"A":"Imunofixação sérica e urinária.","B":"Dosagem do hormônio do crescimento (GH).","C":"Dosagem do índice de saturação da transferrina.","D":"Dosagem do hormônio estimulante da tireoide (TSH).","E":"Dosagem do fator de crescimento ?insulina-like? 1 (IGF-1)."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-51164","number":"51164","sourceNumber":"51164","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher de 38 anos comparece para consulta com quadro de redução da libido, atrofia\nmamária, ganho de peso, fala arrastada e astenia intensa. Exame físico: mamas atróficas, anasarca\n(+/4+) e redução da pilificação genital. Uma avaliação laboratorial mostra T4 livre baixo; TSH no\nlimite inferior; cortisol basal = 05 mcg/dl após estimulação com ACTH (valor de referência > 18\nmcg/dl); testosterona baixa e FSH e LH nos limites inferiores. Qual o exame mais provavelmente\nrevelará a causa da sua doença?","options":{"A":"Tomografia de abdome.","B":"Cintilografia de tireoide.","C":"Teste combinado da pituitária anterior.","D":"Ressonância nuclear magnética de encéfalo."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-51234","number":"51234","sourceNumber":"51234","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher de 60 anos, em primeiro dia pós-operatório de tiroidectomia total, apresenta\nagitação na enfermaria. Ao ser abordada, a\npaciente encontra-se alerta, porém com desorientação\nespacial e alucinações visuais (descrevia animais e monstros circulando seu leito). A cicatriz\ncirúrgica estava limpa. Ao aferir a pressão arterial da paciente, observa-se intenso espasmo carpal.\nNão havia outros achados no exame físico. Qual alteração deve estar presente no\neletrocardiograma desta paciente?","options":{"A":"Alargamento do QRS.","B":"Aumento do intervalo PR.","C":"Elevação do segmento ST.","D":"Prolongamento do intervalo QT."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-37402","number":"37402","sourceNumber":"37402","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente apresenta hipercalcemia relacionada a um câncer de esôfago. Sobre o\ntratamento deste distúrbio eletrolítico, podemos afirmar que:","options":{"A":"O início imediato de hidrocortisona intravenosa é a principal medida a ser realizada.","B":"O pamidronato e zoledronato inibem a ação dos\n\nosteoblastos, em consequência, reduzindo a liberação do cálcio no sangue.","C":"Calcitonina subcutânea é a medida de maior impacto no tratamento da hipercalcemia tumoral.","D":"Deve-se evitar diuréticos de alça, pelo risco de\ndesidratação e acúmulo de ácido úrico.","E":"O aspecto mais importante é a hidratação para assegurar boa volemia e diurese."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-22954","number":"22954","sourceNumber":"22954","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A incidência do hiperparatireoidismo primário (HPT) é de aproximadamente 25 por\n\n100.000 da população em geral, aumentando com a idade. A sua causa ainda é desconhecida.\n\nSobre essa patologia, assinale o item ERRADO.","options":{"A":"As complicações renais são frequentemente as manifestações mais graves, tais como\nnefralitíase, nefrocalcinose, nictúria e polidipsia","B":"a hipertensão no HPT é um fenômeno frequente e parece estar relacionada com o grau do\ndistúrbio renal","C":"pacientes com hipercalcemia podem manifestar distúrbios psiquiátricos ou nervosos, variando\ndesde depressão e ansiedade até psicose ou coma","D":"o diagnóstico de HPT primário é tipicamente feito com a documentação de uma elevação da\nconcentração de cálcio sérico em conjunto a uma elevação do PTH","E":"apesar do PTH exercer efeito sobre a excreção de bicarbonato pelo rim, pacientes com HPT\nraramente apresentam acidose metabólica hiperclorêmica"},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-22962","number":"22962","sourceNumber":"22962","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Feocromocitomas são tumores adrenais secretores de catecolaminas que derivam das\ncélulas cromafins da medula adrenal. São tumores raros e podem se apresentar na forma\nesporádica ou familiar. São afirmativas corretas a respeito dos feocromocitomas, EXCETO:","options":{"A":"apresentam-se com sinais e sintomas de excesso de catecolaminas, como hipertensão arterial,\npalpitações, ansiedade, cefaleia e rubor. Podem também manifestar complicações cardiovasculares\ncomo infarto, arritmias e apoplexia","B":"um dado para o diagnóstico é a demonstração de aumento das catecolaminas plasmáticas e\nurinárias e de seus metabólitos. Apesar da dosagem urinária em 24 horas de ácido vanil mandélico\npossuir baixa especificidade, a dosagem sérica de metanefrinas fracionadas tem sido utilizada\ncomo método inicial de avaliação bioquímica por ser altamente sensível","C":"dentre os feocromocitomas, até 98% são encontrados no abdome, 2 a 3% no tórax e 1% no\npescoço. De todos eles, 10% são\nextra-adrenais ou bilaterais ou familiares ou malignos. Esta é uma\nregra regularmente acurada e utilizada","D":"o tratamento pré-operatório de pacientes com feocromocitoma centraliza-se em controle da\nhipertensão, bloqueio a-adrenérgico para evitar crise hipertensiva intraoperatória e reposição de\nfluidos para evitar colapso circulatório após a retirada do tumor","E":"para ressecção dos feocromocitomas opta-se por uma abordagem aberta e ampla para completa\nexploração do abdome. Independente do tamanho da lesão, o uso da laparoscopia é bastante\nrestrito nessas situações por não permitir um inventário adequado da cavidade"},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-25472","number":"25472","sourceNumber":"25472","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, 48 anos, obesa, hipertensa e diabética com fácies cushingoide. As dosagens\nde ACTH e cortisol matinal mostraram-se\ndiminuídas. Qual o provável diagnóstico?","options":{"A":"Síndrome de Cushing por adenoma adrenal","B":"Síndrome de Cushing por carcinoma adrenal","C":"Síndrome de Cushing iatrogênico","D":"Síndrome de Cushing central (doença de Cushing)","E":"Síndrome de Cushing ectópico por produção de ACTH ectópico."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-27721","number":"27721","sourceNumber":"27721","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre as doenças da medula adrenal todas são verdadeiras, EXCETO:","options":{"A":"feocromocitomas são tumores adrenais secretores de catecolaminas.","B":"feocromocitomas em 10% são bilaterais, extra-adrenais, familiares, malignos e em 10% ocorrem\nem crianças.","C":"o efeito máximo do bloqueio alfa-adrenérgico é alcançado com o uso do nitroprussiato de sódio.","D":"feocromocitoma está associado com a MEN (neoplasia endócrina múltipla) tipo II.","E":"o feocromocitoma maligno é mais comum nas mulheres (3M: 1H)."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-24354","number":"24354","sourceNumber":"24354","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Indique qual das seguintes drogas é utilizada no tratamento da hiperprolactinemia, na\npresença ou não de adenoma hipofisário:","options":{"A":"Citrato de clomifeno.","B":"Tamoxifen.","C":"Bromoergocriptina.","D":"Progesterona."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-27783","number":"27783","sourceNumber":"27783","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um bebê de três semanas do sexo feminino apresenta-se ao Pronto-Socorro com\nvômitos, falta de apetite e diminuição da\nprodução de urina durante as últimas 24 horas. O bebê\nprovém de parto vaginal a termo, sem complicações perinatais. Ao exame, a criança aparece com\nhipotermia e desidratado, com fontanela deprimida, preenchimento capilar retardado, taquicardia e\nhipotensão moderada. O médico também observa clitoromegalia leve e hiperpigmentação da área\ngenital. Exames iniciais revelam o seguinte: Na+ 129 mEq/L, K+ 6,8 mEq/L, Cl- 88 mEq/L. Ureia e\ncreatinina estão dentro dos limites normais. Pressão liquórica à punção lombar e radiografia de\ntórax são normais. Hemograma, sumário de urina e bioquímica do liquor estão pendentes. Com\nbase nestas informações, o exame mais apropriado para confirmação do diagnóstico é:","options":{"A":"teste de estímulo com hormônio adrenocorticotrófico (ACTH).","B":"tomografia computadorizada axial do crânio para visualização da glândula adrenal.","C":"ultrassonografia pélvica.","D":"concentração sérica de 11-desoxicortisol.","E":"concentração sérica de 17-hidroxiprogesterona."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-9010","number":"9010","sourceNumber":"9010","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher de 45 anos admitida com queixas de cefaleia intensa, sudorese, taquipneia,\npalpitações e vômitos. Ao exame,\napresentava PA: 220 x 110 mmHg, FC: 112 bpm , rubor facial e\nextrema ansiedade. Qual a MELHOR hipótese diagnóstica para o caso?","options":{"A":"Hiperaldosteronismo primário","B":"Feocromocitoma","C":"Síndrome de Cushing","D":"Hipotireoidismo"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-9011","number":"9011","sourceNumber":"9011","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Qual das seguintes manifestações clínicas é comum na Síndrome de Cushing?","options":{"A":"Hipoglicemia","B":"Hipercalemia","C":"Alopecia","D":"Hipertensão arterial"},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-349760","number":"349760","sourceNumber":"349760","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa correta sobre Diabetes na infância.","options":{"A":"Diabetes na infância é uma condição muito rara abaixo dos 10 anos de idade.","B":"Diabetes tipo I é a mais frequente na infância.","C":"Diabetes do tipo gestacional é mais prevalente na pré-adolescência do que nas demais faixas\netárias das mulheres.","D":"Diabetes na infância acomete apenas meninos.","E":"A resistência insulínica nos lactentes é de grande importância para a manutenção da glicemia."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-365643","number":"365643","sourceNumber":"365643","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A respeito do tratamento de um adolescente que apresenta cetoacidose diabética com\ndesidratação grave, assinale a alternativa correta.","options":{"A":"O soro de manutenção deve receber glicose apenas quando o paciente estiver normoglicêmico.","B":"A administração de insulina venosa deve ser iniciada apenas após correção da volemia.","C":"Deve-se administrar bicarbonato durante a fase de expansão volêmica, até que ocorra\nnormalização do pH sanguíneo.","D":"A infusão de potássio está contraindicada se os níveis séricos estiverem dentro da normalidade."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-349694","number":"349694","sourceNumber":"349694","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma criança de sete anos, previamente saudável, é levada ao pronto-socorro com\nqueixas de poliúria, polidipsia, perda de\npeso e vômitos. Ao exame físico, apresenta desidratação,\ntaquipneia e hálito cetônico. Os exames laboratoriais revelam glicemia de 450 mg/dL, sódio e\npotássio de 140mEq/L e 5,5 mEq/L, respectiva; pH arterial de 7,2, bicarbonato de 18mEq/L. Qual\ndeve ser a conduta inicial nesse caso?","options":{"A":"Iniciar hidratação venosa com solução salina isotônica e, após hidratação, reavaliar a\nnecessidade de insulina regular em infusão contínua.","B":"Iniciar hidratação venosa com solução salina isotônica e bicarbonato em infusão contínua.","C":"Iniciar hidratação venosa com solução glicosada hipotônica e tiamina em bolus.","D":"Iniciar hidratação venosa com solução salina isotônica e glicose em infusão contínua.","E":"Iniciar hidratação venosa com solução salina hipertônica e insulina NPH em bolus."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-349706","number":"349706","sourceNumber":"349706","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Diabetes Mellitus (DM) é uma das doenças crônicas não transmissíveis mais\nimportantes do mundo, sendo o conhecimento a seu\nrespeito fundamental para o médico e para\noutros profissionais da saúde. Em relação à fisiopatologia da DM tipo 2, assinale a alternativa\ncorreta.","options":{"A":"A DM tipo 2 tem componente genético pouco significativo, sendo uma doença exclusivamente\nrelacionada ao estilo de vida.","B":"As alterações metabólicas da DM tipo 2 geram inflamação sistêmica de alto grau, com\nfrequentes alterações em marcadores laboratoriais de inflamação, como ferritina.","C":"A resistência à ação da insulina por tecidos sensíveis a esta leva a uma redução no consumo da\nglicose sérica e a um aumento na produção hepática de glicose.","D":"A perda gradual de produção de insulina secundária leva à destruição das células beta do\npâncreas por processo autoimune característico da DM tipo 2.","E":"Como resultado da resistência insulínica, há aumento da presença de ácidos graxos livres\nséricos levando à redução nos níveis de HDL, LDL e VLDL."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-322149","number":"322149","sourceNumber":"322149","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um homem de 24 anos procura atendimento médico com queixa de falta de ar e boca\nseca. Sua glicemia capilar é aferida, 467mg/dL. Nega doenças prévias ou uso de medicações.\n\nDiante desse caso, assinale a alternativa correta.","options":{"A":"A presença de acidose respiratória é comum nesses casos.","B":"O uso de insulina de ação rápida pode levar ao aumento do potássio sérico.","C":"A restrição hídrica está indicada nesse caso.","D":"A dosagem da hemoglobina glicosilada, é essencial para determinar a conduta correta.","E":"Os títulos de anticorpos antidescarboxilase do ácido glutâmico (GADA) são importantes para o\ndiagnóstico de LADA (latente autoimmune diabetes of the adult)."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337529","number":"337529","sourceNumber":"337529","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. Trata-se de estado de cetoacidose diabética, sendo necessária\nhidratação vigorosa com solução salina hipertônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337530","number":"337530","sourceNumber":"337530","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. A terapêutica com insulina regular deve ser realizada\npreferencialmente por via endovenosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337531","number":"337531","sourceNumber":"337531","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. Na presença de leucocitose e acidose, deve-se iniciar o\ntratamento com antibióticos de largo espectro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337532","number":"337532","sourceNumber":"337532","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. Deve-se realizar reposição de potássio, entretanto não deve ser\nutilizada reposição de bicarbonato para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337534","number":"337534","sourceNumber":"337534","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 33 anos foi encontrado desacordado com hálito cetônico, sendo levado\ndireto para a emergência do hospital. Na sua história, consta que, há duas semanas, ele começou\na apresentar polidipsia e poliúria. Os exames da emergência demostram um PH de 7,05; HCO3 de\n11; K de 4,5 meq/l; sódio corrigido de 140 meq/l e seu HGT foi de 500mg/dl; além de presença de\nleucocitose com 26 mil leucóticos. Em relação ao caso clínico descrito e aos conhecimentos\ncorrelatos, julgue o item a seguir. O paciente apresenta uma osmolaridade efetiva plasmática, em\ntorno de 290 meq/l.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337590","number":"337590","sourceNumber":"337590","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. O alvo glicêmico desse paciente deve ser uma A1c\nabaixo de 6,5%, já que o controle intensivo da glicose diminui o risco de novo AVE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-305306","number":"305306","sourceNumber":"305306","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente, em idade escolar, apresenta queixa de dor abdominal intensa, náuseas,\nvômitos, anorexia e sonolência. Refere sentir muita sede e, ao exame físico, está desidratado.\n\nTambém foram percebidos hálito cetônico e hiperventilação (respiração de Kussmaul). Qual das\nseguintes opções é o resultado esperado na gasometria, de acordo com a principal suspeita\ndiagnóstica?","options":{"A":"Alcalose respiratória.","B":"Alcalose metabólica.","C":"Acidose metabólica com redução do ânion-gap.","D":"Acidose metabólica com elevação do ânion-gap.","E":"Acidose respiratória."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-298892","number":"298892","sourceNumber":"298892","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 4 anos de idade foi levada pela mãe ao pronto atendimento e relatou\nque a filha refere intensa dor abdominal e\nestá há sete dias sem evacuar. A filha começou a\ndemonstrar dificuldades para evacuar logo que iniciou a introdução alimentar e, desde então,\napresenta fezes em \"bolinhas\". Em relação à dieta, disse que a menina come frutas, porém em\npouca variedade, gosta muito de banana e de maçã, não gosta de verduras e ingere pouca\nquantidade de água. Ao exame físico, verificaram-se FC = 100 bpm, FR = 22 irpm, SatO2 = 98%\nem AA, bem como abdome globoso com ruídos hidroaéreos positivos, dor difusa à palpação e, em\nquadrante inferior esquerdo, palpa-se massa (sugestivo de fezes). Considerando esse caso clínico\ne com base nos conhecimentos médicos correlatos, julgue o item a seguir. Diabetes mellitus é uma\ncausa incomum de constipação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-298947","number":"298947","sourceNumber":"298947","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. É possível já estabelecer o\ndiagnóstico de diabetes mellitus nessa paciente, visto que apresenta glicose, ao acaso, maior ou\nigual a 200 mg/dL e possui sintomas inequivocos de hiperglicemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-298948","number":"298948","sourceNumber":"298948","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. As lesões de pele\napresentadas pela paciente são compatíveis com Acantose nigricans, a qual é um indicativo de\nresistência insulínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-298949","number":"298949","sourceNumber":"298949","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O fumo é um fator de risco\ntotalmente evitável de doença e morte cardiovasculares, e seu enfrentamento precisa ser feito.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-284287","number":"284287","sourceNumber":"284287","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no mundo.\nConforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. Suponha-se que uma paciente de 46 anos de\nidade, com glicemia capilar de 218, tenha procurado o pronto-socorro por cefaleia do tipo\nenxaqueca. Nesse caso, é correto afirmar que a paciente é portadora de diabetes mellitus do tipo 2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-284288","number":"284288","sourceNumber":"284288","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no\nmundo. Conforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. As anemias hemolíticas reduzem a dosagem\nde hemoglobina glicada sérica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-284289","number":"284289","sourceNumber":"284289","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no\nmundo. Conforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. No caso de preparo de duas insulinas na\nmesma seringa, é recomendada, primeiramente, a aspiração da insulina regular e, depois, a\naspiração da insulina NPH.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-284291","number":"284291","sourceNumber":"284291","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A organização Mundial de Saúde (OMS) estima que a hiperglicemia é o terceiro fator\nmais importante de mortalidade precoce no\nmundo. Conforme as diretrizes da Sociedade Brasileira\nde Diabetes de 2019 e 2020, julgue o item a seguir. Os microaneurismas são manifestações\ncomuns da retinopatia diabética.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-261248","number":"261248","sourceNumber":"261248","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 54 anos de idade, usuária de mirtazapina 30 mg por dia, vem\napresentando importante aumento de peso. Durante\na evolução do seu peso, tem sentido dor\nabdominal em hipocôndrio direito, mal-estar, náuseas e vômitos. Realizou exames que\nidentificaram transaminases hepáticas quatro vezes acima do limite da normalidade, além de uma\nglicemia de jejum = 116 mg/dL. Levantou-se a hipótese de esteato-hepatite não alcoólica.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente apresenta provavelmente diabetes mellitus tipo II.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-284343","number":"284343","sourceNumber":"284343","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"São complicações relacionadas à obesidade na gravidez, entre outras, o diabetes\ngestacional, a pré-eclâmpsia e a prevalência aumentada de natimortalidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262136","number":"262136","sourceNumber":"262136","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. A hipercalcemia deve ser confirmada com nova dosagem de cálcio, que deve\nser corrigida pelo valor da albumina sérica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262138","number":"262138","sourceNumber":"262138","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Em caso de PTH aumentado, a hipótese principal torna-se\nhiperparatireoidismo primário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262139","number":"262139","sourceNumber":"262139","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. A tomografia de região cervical é o padrão-ouro para localizar as\nparatireoides e deve ser solicitada para o diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262140","number":"262140","sourceNumber":"262140","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Em caso de PTH baixo, neoplasias devem fazer parte da investigação das\ncausas da hipercalcemia da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262141","number":"262141","sourceNumber":"262141","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Apesar de menos comuns, doenças granulomatosas devem ser investigadas\nna paciente, caso o PTH esteja baixo e seja descartada a presença de neoplasias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-284354","number":"284354","sourceNumber":"284354","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. O índice de massa corporal associado à circunferência abdominal fornece a avaliação\ncombinada para a estratificação do risco metabólico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-261307","number":"261307","sourceNumber":"261307","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dL; colesterol HDL = 32 mg/dL; colesterol LDL = 192,3 mg/dL; e creatinina sérica\n\n= 1,32 mg/dL. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92%\ncom níveis tensionais confirmados em duas\nconsultas com mais de quatro semanas entre elas.\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O\nuso de metformina é contraindicado em pacientes com depuração de creatinina inferior a 30\nmL/min.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262178","number":"262178","sourceNumber":"262178","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A principal hipótese diagnóstica é doença causada por adenoma hipofisário secretor\nde GH na maioria dos casos. Os demais casos são decorrentes de secreção hipotalâmica de\nhormônio liberador de hormônio do crescimento (GHRH) ou de secreção ectópica de GH ou de\nGHRH.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262179","number":"262179","sourceNumber":"262179","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Devem ser feitas dosagens de GH e IGF-1. Os valores de GH são mais estáveis do\nque os de IGF-1, não são pulsáteis e são mais confiáveis e fidedignos para avaliar a atividade da\ndoença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262180","number":"262180","sourceNumber":"262180","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A enfermidade pode fazer parte da neoplasia endócrina múltipla tipo 1 (NEM-1).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262181","number":"262181","sourceNumber":"262181","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. O tratamento de escolha deve ser o cirúrgico, sendo esse o padrão-ouro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262182","number":"262182","sourceNumber":"262182","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Esse paciente tem chance aumentada de ter pólipos colônicos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-262183","number":"262183","sourceNumber":"262183","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. O tratamento medicamentoso pode ser realizado com somatropina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-239285","number":"239285","sourceNumber":"239285","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considere uma paciente de 54 anos de idade, diabética (HbA1c = 8,2%), cardiopata\nisquêmica com infarto agudo do miocárdio\nprévio e insuficiência cardíaca com fração de ejeção\nreduzida. Encontra-se em tratamento para diabetes com metformina 850 mg três vezes ao dia e\nglibenclamida 5 mg pela manhã. No exame físico, chama a atenção a presença de manchas\nhiperpigmentadas/escurecidas em áreas de dobras. A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatados, bem como nas últimas diretrizes mundiais relacionadas ao\ntratamento da diabetes, publicadas em 2019, julgue o item a seguir. Nesse caso, é correto\nsuspender a glibenclamida e associar dapaglifozina (um agonista do GLP-1 ? receptor 1\n\nglucagon-like peptídeo) ao tratamento com metformina.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-239286","number":"239286","sourceNumber":"239286","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considere uma paciente de 54 anos de idade, diabética (HbA1c = 8,2%), cardiopata\nisquêmica com infarto agudo do miocárdio\nprévio e insuficiência cardíaca com fração de ejeção\nreduzida. Encontra-se em tratamento para diabetes com metformina 850 mg três vezes ao dia e\nglibenclamida 5 mg pela manhã. No exame físico, chama a atenção a presença de manchas\nhiperpigmentadas/escurecidas em áreas de dobras. A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatados, bem como nas últimas diretrizes mundiais relacionadas ao\ntratamento da diabetes, publicadas em 2019, julgue o item a seguir. Essa paciente tem acantose\nnigricans, que é comum em pacientes diabéticos e obesos. Essas lesões de pele nunca melhoram\ncom o tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-239287","number":"239287","sourceNumber":"239287","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considere uma paciente de 54 anos de idade, diabética (HbA1c = 8,2%), cardiopata\nisquêmica com infarto agudo do miocárdio\nprévio e insuficiência cardíaca com fração de ejeção\nreduzida. Encontra-se em tratamento para diabetes com metformina 850 mg três vezes ao dia e\nglibenclamida 5 mg pela manhã. No exame físico, chama a atenção a presença de manchas\nhiperpigmentadas/escurecidas em áreas de dobras. A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatados, bem como nas últimas diretrizes mundiais relacionadas ao\ntratamento da diabetes, publicadas em 2019, julgue o item a seguir. Para essa paciente, a\npioglitazona não seria recomendada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-255728","number":"255728","sourceNumber":"255728","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 12 anos de idade vai ao pediatra em razão de sua mãe querer fazer\numa avaliação anual com exames. Dessa vez, o\npediatra solicitou hormônio do crescimento sérico\n(GH), que veio uma vez e meio aumentado, acima dos valores de referência. O paciente faz\natividades físicas regulares e não apresenta alteração estrutural. Esse paciente tinha suspeita de\nsíndrome de West, mas esta foi descartada. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. Níveis aumentados de GH são normais em exercícios\nfísicos ou uma hora após o início de sono profundo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-255729","number":"255729","sourceNumber":"255729","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 12 anos de idade vai ao pediatra em razão de sua mãe querer fazer\numa avaliação anual com exames. Dessa vez, o\npediatra solicitou hormônio do crescimento sérico\n(GH), que veio uma vez e meio aumentado, acima dos valores de referência. O paciente faz\natividades físicas regulares e não apresenta alteração estrutural. Esse paciente tinha suspeita de\nsíndrome de West, mas esta foi descartada. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. Em geral, a secreção de GH é maior em mulheres do\nque em homens.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-239364","number":"239364","sourceNumber":"239364","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma paciente de 58 anos de idade, hipertensa, com história de mau controle,\nobesidade grau 1, dislipidêmica, tabagista\n40 anos/maços, com histórico de participação sem\nsucesso em programa de abandono ao tabagismo, é atendida em consulta de acolhimento em\nUnidade de Saúde da Família, após dois anos da última consulta agendada. Alega que procura\natendimento em razão da dor de intensidade grau quatro em hemitórax anterior esquerdo há dois\ndias, contínua, sem irradiações, realizando \"sinal do apontamento\" para demonstrar local exato da\ndor, sem fator gatilho ou fator de piora notados. Além disso, relata que vem apresentando tosse\nnão produtiva frequente há um mês, sem febre, dispneia, emagrecimento ou demais\ncomemorativos. Não vem fazendo uso das respectivas medicações, alegando que se esquece de\nadministrá-las. Leva boletim de atendimento em consulta realizada há duas semanas em unidade\nde pronto atendimento em razão da dor lombar, mostrando receita de corticoide intramuscular\nfornecida na alta, medicação da qual admite fazer uso com certa frequência, afirmando que esta\nsempre lhe é prescrita quando consulta na UPA. Mostra também exames realizados, há dois\nmeses, solicitados em consulta médica em clínica popular, com os seguintes resultados: Hb = 13,2\ng/dl, Ht = 37,1%, leucócitos = 7,2 mil, plaquetas = 148 mil, Cr = 1,1 mg/dl, Ur = 42 mg/dl,\ncolesterol\ntotal = 270 mg/dl, HDL = 38 mg/dl, LDL =192 mg/dl, triglicerídeos = 198 mg/dl e glicemia de jejum =\n123 mg/dl. Com relação a esse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. Há indicação formal de início do uso de estatina, independentemente de a\npaciente apresentar interesse recente por atividades físicas e desejo de adesão a medidas\nalimentares.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-196633","number":"196633","sourceNumber":"196633","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma menina de 10 anos de idade recebeu diagnóstico de pneumonia bacteriana\nadquirida na comunidade, em unidade básica\nde saúde. Foi então iniciado tratamento com\namoxicilina, na dose de 50 mg/kg/dia, mas, após três dias de tratamento, a paciente apresentou\npiora clínica de quadro. Evoluiu com piora da tosse, associada a taquipneia, persistência da febre e\ndor abdominal, principalmente em hipocôndrio e flanco à direita. Com relação a esse caso clínico e\ncom base nos conhecimentos médicos correlatos, julgue o item a seguir. Dor abdominal na infância\né um dos motivos mais frequentes das consultas com o pediatra. É fundamental realizar anamnese\ne exame físico completos, a fim de pesquisar possíveis diagnósticos diferenciais. Essa pode ser,\npor exemplo, a primeira manifestação de diabetes tipo 1 na infância e na adolescência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-179165","number":"179165","sourceNumber":"179165","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa que apresenta os parâmetros considerados para se estabelecer o\ndiagnóstico de síndrome metabólica segundo a Organização Mundial da Saúde (OMS) e o\n\nNCEP-ATP III (National Cholesterol Education Program's Adult Treatment Panel III).","options":{"A":"Obesidade abdominal por meio de circunferência abdominal, glicemia de jejum, ácido úrico e\nLDL colesterol.","B":"Obesidade abdominal por meio de circunferência abdominal, glicemia pós-prandial, LDL\ncolesterol e triglicerídeos.","C":"Obesidade abdominal por meio de circunferência abdominal, triglicerídeos, HDL colesterol,\npressão arterial e glicemia de jejum.","D":"Esteatose hepática por meio de ultrassom, hemoglobina glicada, HDL colesterol e hipertensão\narterial.","E":"Esteatose hepática por meio de ultrassom, glicemia de jejum, ácido úrico e LDL colesterol."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-179190","number":"179190","sourceNumber":"179190","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um médico residente da área de clínica médica deseja fazer campanha para controle\nde diabetes mellitus. Após determinar a\npopulação-alvo, dosou a glicemia casual (definida como\naquela realizada a qualquer hora do dia, sem se observar o intervalo desde a última refeição) em\ntodos os participantes com a finalidade de realizar triagem. Nesse caso hipotético deverão ser\ninvestigados os indivíduos que apresentarem valores de glicose plasmática, em mg/dL,\npreconizados para o diagnóstico de diabetes mellitus, acima de","options":{"A":"110.","B":"126.","C":"140.","D":"200.","E":"220."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177569","number":"177569","sourceNumber":"177569","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com Diabetes Mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de\nmedicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabetes\nmellitus e suas complicações, julgue o item a seguir. A baixa acuidade visual do paciente pode ter\norigem na retinopatia diabética, complicação que deve ter seu rastreamento iniciado um ano após o\ndiagnóstico da DM2.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177571","number":"177571","sourceNumber":"177571","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. A realização de índice tornozelo-braço é\nindicada para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177576","number":"177576","sourceNumber":"177576","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. O rastreamento da nefropatia diabética deve\nser realizado anualmente, por meio das dosagens séricas da ureia e da creatinina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177577","number":"177577","sourceNumber":"177577","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de\nmedicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. O rastreamento da neuropatia autonômica\nenvolve a aferição da frequência cardíaca de repouso, assim como da pressão arterial (em decúbito\ne ortostase).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177581","number":"177581","sourceNumber":"177581","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. No caso da disautonomia cardiovascular, o\nuso de mineralocorticoides pode ser vantajoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177583","number":"177583","sourceNumber":"177583","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"R.L.P. é um senhor de 65 anos de idade, com diabetes mellitus (DM) há mais de 20\nanos, controlada parcialmente com o uso de medicações orais. Houve indicação de início de\ninsulinoterapia há cerca de 3 anos, mas o paciente tem dificuldade de aderir a essa medida em\nrazão de sua baixa acuidade visual, que lhe impede de marcar corretamente a quantidade de\nunidades prescrita na seringa. Acerca do caso clínico apresentado e considerando o diabete\nmellitus e suas complicações, julgue o item a seguir. A forma eruptiva dos xantomas usualmente\nocorre em pacientes com DM descompensado, mas a patogênese primária relaciona-se com a\nhiperlipidemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177635","number":"177635","sourceNumber":"177635","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos Cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. A dosagem do\ncolesterol total e frações estará indicada em 2 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-134972","number":"134972","sourceNumber":"134972","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"No que se refere ao câncer de esôfago, cirrose e doença de Crohn, julgue o item\nsubsecutivo. Se a ressonância magnética de abdome revelar a presença de nódulo sólido\nhomogêneo de 3 centímetros de diâmetro na glândula suprarrenal esquerda, existe indicação de\nadrenalectomia, mesmo na ausência de produção hormonal associada.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-131826","number":"131826","sourceNumber":"131826","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considere, hipoteticamente, menina de seis anos de idade, com história de vômitos, dor\nabdominal e cansaço há um dia. Mãe relata perda de peso da criança no último mês, associada a\npoliúria e polidipsia. Ao exame físico, observa-se criança desidratada, respiração de Kussmaul e\napresenta glicemia capilar de 400 mg/dl. A esse respeito, assinale a alternativa que melhor define o\nquadro de cetoacidose diabética:","options":{"A":"Glicemia plasmática > 200 mg/dl e pH de sangue arterial < 7,3.","B":"Glicemia plasmática > 200 mg/dl, pH de sangue arterial < 7,2, cetonúria = 1+ e HCO3 < 20\nmEq/L.","C":"Glicemia plasmática > 200 mg/dl, pH de sangue arterial < 7,3, cetonúria = 2+ e HCO3 < 15\nmEq/L.","D":"Glicemia plasmática > 200 mg/dl e sinais clínicos de diabetes (poliúria, polidipsia e perda de\npeso).","E":"Glicemia plasmática > 200 mg/dl, teste de tolerância oral à glicose com glicemia = 200 mg/dl na\ncoleta após 120 minutos do teste e glicosúria."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-108176","number":"108176","sourceNumber":"108176","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Julgue o item a seguir, relativo à deficiência de crescimento do corpo. Diversos genes\nresponsáveis por codificar fatores de transcrição estão implicados na etiologia da deficiência\ncombinada dos hormônios hipofisários (pan-hipopituitarismo), sendo o gene PROP-1 o mais\nfrequentemente envolvido.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-27548","number":"27548","sourceNumber":"27548","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A neoplasia endócrina múltipla do tipo I (NEM I), caracteriza-se pela ocorrência\nsimultânea de:","options":{"A":"feocromocitoma, hiperplasia da paratireoide e adenomas hipofisários.","B":"tumor medular da tireoide, feocromocitoma e insulinoma.","C":"adenomas hipofisários, tumor medular da tireoide e feocromocitoma.","D":"insulinoma, adenomas hipofisários e neuromas mucosos.","E":"hiperplasia da paratireoide, tumor das ilhotas pancreáticas e adenomas hipofisários."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-13858","number":"13858","sourceNumber":"13858","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Com relação à hipercalcemia, julgue os itens a seguir. I- Pode ser causada por\nhipoparatireodismo. II- Associa-se ao desenvolvimento de diabete insípido nefrogênico. III- Em\npacientes com essa anormalidade, e possível observar encurtamento do intervalo QT no\neletrocardiograma. IV- O espasmo laríngeo e o sinal de Trousseau são manifestações clínicas\nassociadas a esse distúrbio. V- O uso de beta-2 agonistas por via inalatória é útil no tratamento\nagudo dessa alteração eletrolítica, até que a causa primária seja controlada. Estão certas apenas\nos itens:","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"III e IV.","E":"IV e V."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-13837","number":"13837","sourceNumber":"13837","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Julgue os itens subsequentes, relativos à fisiologia reprodutiva. I- O hipotálamo é uma\npequena estrutura neural situada na base do\nencéfalo, acima do quiasma óptico e abaixo do\nterceiro ventrículo. II- Apesar de inúmeras conexões neurológicas com a hipófise. O hipotálamo é\numa estrutura isolada no sistema nervoso central e suas principais funções reguladoras ocorrem\npor meio de ação retroativa sobre o próprio hipotálamo, em feedback de alça curta. III- Do ponto de\nvista estrutural, a adeno-hipófise é similar à hipófise posterior ambas são derivadas\nembriologicamente do ectoderma epidérmico. IV- Os principais hormônios secretados pela\n\nadeno-hipófise são: FSH, LH, TSH, ACTH, GH e prolactina. V- Os principais hormônios secretados\npela hipófise posterior são ocitocina e inibina.\nEstão certos apenas os itens:","options":{"A":"I e II.","B":"I e IV.","C":"II e III.","D":"III e V.","E":"IV e V."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-343404","number":"343404","sourceNumber":"343404","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"CPB, sexo feminino, 25 anos, foi levada ao pronto-socorro pelo pai com dor abdominal\nhá dois dias e hoje iniciou quadro de\nrebaixamento do nível de consciência, associado à respiração\nrápida e profunda. Ao exame físico: REG, desidratada (3+/4+), taquidispneica (ritmo de Kusmaul),\nGlasgow 14. Exames laboratoriais: hemograma com leucocitose, dextro: 460 mg/dL, pH sérico:\n7,18, HCO3: 8 mEq/L, Na: 142 mEq/L K: 3,2 mEq/L. Após iniciar hidratação endovenosa, o próximo\npasso será:","options":{"A":"Iniciar reposição endovenosa de potássio antes da insulinoterapia, por risco de arritmias.","B":"Corrigir importante acidose metabólica do paciente com infusão de bicarbonato de sódio.","C":"Iniciar insulinoterapia endovenosa com NPH.","D":"Prescrever solução salina hipotônica de NaCl 0,45%, 10 a 14 mL/kg/h."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-301295","number":"301295","sourceNumber":"301295","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. Trata-se de Cetoacidose diabética (CAD). São\nconsiderados diagnósticos diferenciais para CAD: a acidose láctica por erro inato do metabolismo,\nintoxicação por salicilato ou teofilina, coma hiperosmolar e acidose tubular renal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-301296","number":"301296","sourceNumber":"301296","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. Quanto à CAD, é correto afirmar que se trata de um\nconjunto de alterações clínico-laboratoriais decorrentes da insuficiente ação insulínica e da\nconcomitante diminuição dos hormônios contrarreguladores da insulina em resposta a alguma\nsituação de estresse. Laboratorialmente, caracteriza-se por hiperglicemia (glicemia superior a 200\nmg/dL) e acidose metabólica (pH inferior a 7,3 e/ou bicarbonato inferior a 15 mEq/L) com\ndiminuição do ânion gap.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-301297","number":"301297","sourceNumber":"301297","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. O edema cerebral é a complicação da CAD mais\ntemida em crianças e adolescentes. O edema cerebral ocorre em aproximadamente 1% dos casos\nde CAD e está associado à elevada morbidade e mortalidade. O edema cerebral, embora seja, em\ngeral, considerado uma complicação do tratamento da CAD, pode estar presente já na admissão do\npaciente ao serviço de urgência. A acidose hiperclorêmica por perda urinária de ânions cetoácidos\ne a administração por perda excessiva de fluídos ricos em cloreto, assim como a hipoglicemia e a\nhipercalemia, são complicações comuns associadas ao tratamento da CAD. A reposição de\nbicarbonato também pode causar hipernatremia e hipercalemia, sendo entendida como uma das\ncondições facilitadoras da ocorrência de edema cerebral em crianças e adolescentes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-301298","number":"301298","sourceNumber":"301298","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os pais de uma adolescente de 12 anos de idade referem que ela apresenta perda\ncontínua de peso nas últimas duas semanas\n(não sabem quantificar) e, na última semana, notaram\nnela aumento do apetite, aumento importante da ingestão hídrica, idas frequentes ao banheiro para\nurinar (inclusive com enurese noturna), hálito forte, com características de uma fruta passada,\ncansaço e fraqueza. Relatam odinofagia há quatro dias e febre reentrante de até 38 ºC.\nAntecedentes pessoais e familiares: nada digno de nota, saudável. Ao exame, encontra-se em\nregular estado geral, corada, com mucosa labial seca, hipoativa, com hálito cetótico, peso = 28 kg,\nPA = 96 mmHg x 60 mmHg (P50) FC = 130 bpm, FR = 60 ipm, temperatura auxiliar = 36,7 ºC e a\namígdala hiperemiada, com petéquias em palato e placas amareladas na amígdala direita. Na\nausculta respiratória apresenta incursões e excursões respiratórias profundas e rápidas. Apresenta\nabdome escavado, sem visceromegalias, mas relata incômodo à palpação. A respeito do caso\nclínico apresentado, julgue os itens de 52 a 55. As principais causas da CAD são infecções, pouca\naderência ao tratamento e estresse emocional. Em cerca de 25% a 40% das crianças e dos\nadolescentes diabéticos, a CAD é responsável pela primodescompensação diabética. Em\naproximadamente 25% dos casos de CAD, não é possível identificar um fator causal para a\ndescompensação. A CAD representa a descompensação aguda mais grave em crianças e\nadolescentes diabéticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-266502","number":"266502","sourceNumber":"266502","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Marta, de 69 anos de idade, acompanhava seu esposo em uma consulta médica de\nrotina. O casal aguardava o atendimento\nquando, de repente, Marta começou a passar mal. O\nesposo dela, então, pediu ajuda, aos gritos, afirmando \"Marta está tendo uma bilora, não fala nada\ncom nada!\" (sic). A médica Joana prontamente atendeu Marta e iniciou a avaliação dela. Na\navaliação clínica da paciente, constatou-se hemiparesia à esquerda, anisocoria, afasia, nível 14 na\nescala de Glasgow (AO4/RV 4/RM6), pressão arterial de 190 mmHg x 120 mmHg, frequência\ncardíaca de 52 bpm e glicemia capilar de 294 mg/dL. Considerando o caso clínico precedente,\njulgue o próximo item. Nesse caso, eventual presença dos sinais ou sintomas clássicos da diabetes\nmelito e(ou) descompensação metabólica aguda detectada com a medida de glicemia capilar\nbastam para o diagnóstico da diabetes melito, dispensando-se outros testes diagnósticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-230542","number":"230542","sourceNumber":"230542","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O análogo de insulina glulisina demonstra resultados semelhantes na redução dos\neventos hipoglicêmicos e na eficácia em comparação com lispro e asparte. São indicados a\npacientes que apresentam tendência a ter hipoglicemia nos períodos pós- prandiais tardios e\nnoturnos. Podemos ACEITAR a seu respeito que:","options":{"A":"A glulisina é outro análogo de insulina de ação lenta obtido pela troca de asparaginase por\nlisina\nna posição 3 da cadeia ? e de lisina por ácido glutâmico na posição 29 da mesma cadeia.","B":"A glulisina é outro análogo de insulina de ação ultrarrápida obtido pela troca de asparaginase\npor\nlisina na posição 3 da cadeia ? e de lisina por ácido glutâmico na posição 29 da mesma cadeia.","C":"A glulisina é outro análogo de insulina de ação ultrarrápida obtido pela troca de asparaginase\npor lisina na posição 3 da cadeia ? e de lisina\npor ácido glutâmico na posição 29 de outra cadeia.","D":"A glulisina não é outro análogo de insulina, sua ação é ultrarrápida obtido pela troca de\nasparaginase por lisina na posição 3 da\ncadeia ? e de lisina por ácido glutâmico na posição 29 da\nmesma cadeia."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-230544","number":"230544","sourceNumber":"230544","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para iniciar o tratamento do DM1 recém-diagnosticado é fundamental uma estrutura\nque proporcione um programa de educação, com equipe\ncomposta preferencialmente por\nenfermeiros, nutricionista e médicos. Somente sendo CORRETO o item:","options":{"A":"O diagnóstico de DM1 não causa um forte impacto sobre o paciente e seus familiares.","B":"É necessária uma boa orientação inicial para que entendam os objetivos do tratamento.","C":"Os esquemas propostos sem uma forma de monitorização dos resultados.","D":"Orientação não deve capacitá-los a administrar a insulina adequadamente, no início."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-230545","number":"230545","sourceNumber":"230545","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Ainda existe uma lacuna entre a evidência clínica e a prática diária de tratamento\nintensivo do diabetes, visto que, na maioria\ndos casos, a meta terapêutica é difícil de ser alcançada\ne mantida durante os anos de evolução da doença, pelas inúmeras barreiras que o diabetes impõe.\nSomente podemos ACEITAR que:","options":{"A":"Os efeitos benéficos e protetores do tratamento intensivo não foram nítidos nos estudos, apesar\ndo aumento dos valores de HbA1c ao longo dos\nanos de seguimento.","B":"Os efeitos benéficos e protetores do tratamento intensivo foram nítidos nos estudos, apesar do\naumento dos valores de HbA1c ao longo dos dias de seguimento.","C":"Os efeitos benéficos e protetores do tratamento intensivo foram nítidos nos estudos, apesar do\naumento dos valores de HbA1c ao longo dos anos de seguimento.","D":"Os efeitos benéficos e protetores do tratamento intensivo foram inexistentes nos estudos, apesar\ndo aumento dos valores de HbA1c ao longo dos\nanos de seguimento."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-230546","number":"230546","sourceNumber":"230546","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O análogo de insulina degludeca, de ação prolongada, está disponível no mercado\nbrasileiro para a prática clínica e, associado aos análogos de ação ultrarrápida, pode ser uma\nalternativa terapêutica no tratamento de indivíduos com diabetes. Somente NÃO podemos\nconcordar que:","options":{"A":"O análogo não é uma nova alternativa para o tratamento de pacientes, demonstrando benefícios\nprincipalmente naqueles casos que exigem doses maiores de insulina basal.","B":"Apresenta resultados semelhantes de controle glicêmico e redução de hipoglicemias.","C":"Esse análogo está aprovado para utilização em pacientes com mais de 1 ano de idade.","D":"Estudos que avaliaram o uso desse análogo na faixa etária pediátrica verificaram os mesmos\nefeitos alcançados na população adulta."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-230552","number":"230552","sourceNumber":"230552","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"É importante, de qualquer modo, dar suporte aos pacientes com DM1, orientando-os a\nrealizar o tratamento de forma adequada para reduzir o risco de complicações, agudas e crônicas,\ne para propiciar a melhora da qualidade de vida. Sendo ADEQUADO o item:","options":{"A":"Ocorrência e o medo de eventos hipoglicêmicos, a complexidade e o dia a dia do tratamento e,\nparticularmente, a necessidade de monitoramento e de ajustes raros as doses de insulina.","B":"Ocorrência e o medo de eventos hipoglicêmicos, a complexidade e o dia a dia do tratamento e,\nparticularmente, a necessidade de monitoramento e de ajustes frequentes das doses de insulina.","C":"Inexiste o medo de eventos hipoglicêmicos, no dia a dia do tratamento e, particularmente, a\nnecessidade de monitoramento e de ajustes frequentes das doses de insulina.","D":"Ocorrência e o medo de eventos hipoglicêmicos, a complexidade e o dia a dia do tratamento,\nsendo desnecessário o monitoramento e de ajustes\nfrequentes das doses de insulina."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-230557","number":"230557","sourceNumber":"230557","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Existem diferentes estratégias, esquemas e tipos de insulinas disponíveis, podemos\nAPENAS aceitar que:","options":{"A":"Apesar de não existirem recomendações de metas glicêmicas para o controle do DM, é\nimportante a necessidade de individualização dos objetivos glicêmicos.","B":"Apesar de existirem recomendações de metas glicêmicas para o controle do DM, é importante\nenfatizar a necessidade de não causar a individualização dos objetivos.","C":"Apesar de existirem recomendações de metas glicêmicas para o controle do DM, é importante\nenfatizar a necessidade de individualização\ndos objetivos glicêmicos, evitando-se tanto sequelas de\nhipoglicemias quanto alterações no sistema nervoso central decorrentes de hiperglicemias\nalternadas com hipoglicemias.","D":"Apesar de não existirem recomendações de metas glicêmicas para o controle do DM, é\nimportante enfatizar a necessidade de\nindividualização dos objetivos no sistema nervoso central."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-230559","number":"230559","sourceNumber":"230559","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O tratamento intensivo do DM1, com a obtenção de níveis de HbA1c < 7%, diminui o\nrisco de evolução para complicações crônicas micro e macrovasculares. Somente sendo\nconsiderado ERRADO que:","options":{"A":"O uso de análogos de ação ultrarrápida é inferior no controle metabólico e na diminuição dos\nepisódios hipoglicêmicos.","B":"A hipoglicemia grave é mais frequente com o tratamento intensivo.","C":"A hipoglicemia assintomática é uma das limitações do controle glicêmico ideal.","D":"A hipoglicemia grave pode afetar a capacidade cognitiva de crianças."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-206179","number":"206179","sourceNumber":"206179","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A escolha da outra opção de agente antidiabético deve basear-se em eficácia, idade,\nmecanismo de ação, risco de hipoglicemia, presença de comorbidades, expectativa de vida, ganho\nou perda de peso, efeitos adversos e potenciais de proteção cardiovascular. Sendo INCORRETO\nque:","options":{"A":"Também não há diferença na redução da HbA1c quando diferentes classes de medicamentos\nsão usadas como terceira opção para o tratamento\ndo diabetes tipo 2.","B":"Recomenda-se que qualquer droga antidiabética possa ser uma opção como terceiro agente\npara o controle glicêmico, desde que o\nmecanismo de ação não seja semelhante ao dos agentes já\nem uso.","C":"Tiazolidinedionas, sulfonilureias e glinidas foram associadas ao aumento leve de peso.","D":"Sulfonilureias e glinidas foram associadas a menor risco de hipoglicemia."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-203112","number":"203112","sourceNumber":"203112","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Na pediatria, o diagnóstico de cetoacidose diabética é feito com base nos seguintes\ncritérios laboratoriais:","options":{"A":"Hiperglicemia (glicemia > 200 mg/dl; acidose metabólica (pH venoso < 7,3 e (ou) bicarbonato <\n15 mEq/L); e presença de cetonemia (> 3 mg/dl).","B":"Hiperglicemia (glicemia > 200 mg/dl; acidose metabólica (pH arterial > 7,3 e bicarbonato > 15\nmEq/L); e presença de cetonemia (> 3 mg/dl).","C":"Hiperglicemia (glicemia > 200 mg/dl; acidose metabólica (pH venoso < 7,3 e (ou) bicarbonato >\n15 mEq/L); e ausência de cetonemia.","D":"Hiperglicemia (glicemia > 600 mg/dl; acidose metabólica (pH arterial > 7,3 e bicarbonato > 15\nmEq/L); e ausência de cetonemia.","E":"Hiperglicemia (glicemia > 600 mg/dl); acidose metabólica (pH arterial < 7,3 e (ou) bicarbonato >\n15 mEq/L); e presença de cetonemia (> 3\nmg/dl)."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-206138","number":"206138","sourceNumber":"206138","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A presença de hipoglicemia aumenta a morbimortalidade em diabéticos e não\ndiabéticos, afetando também hospitalizados. NÃO é adequado que","options":{"A":"a hipoglicemia afeta de 5% a 20% dos pacientes hospitalizados, principalmente os tratados com\nantidiabéticos ou insulina, mas também, pode ocorrer entre os não diabéticos com antecedente de\ncirurgia digestiva, câncer ou patologias graves.","B":"a presença de hipoglicemia não aumenta a morbimortalidade em diabéticos e não diabéticos\nindependentemente do nível de gravidade.","C":"além da influência no prognóstico, a hipoglicemia causa ansiedade e estresse entre os pacientes\ne seus familiares, bem como na equipe\nassistencial; em consequência, pode retardar o início do\ntratamento da hiperglicemia.","D":"na maioria dos casos, a hipoglicemia é causada pelos desajustes entre as doses de insulina e a\nquantidade de carboidrato oferecida aos pacientes, constituindo uma das complicações\niatrogênicas mais frequentes no hospital."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-206155","number":"206155","sourceNumber":"206155","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A glicemia plasmática em sangue periférico deve ser usada para confirmar uma\nhiperglicemia inesperada antes do tratamento, pois apresenta menor risco de ocorrência de erros\npré-analíticos, assim como maior acurácia. As principais desvantagens da dosagem de glicemia\nplasmática ou capilar são a influência da alimentação e do estresse agudo, o risco de\ncontaminação da amostra obtida em cateter com infusão de glicose e a limitação relativa ao\ndiagnóstico diferencial de DM e de hiperglicemia por estresse. Sendo INCORRETO que","options":{"A":"na recomendação atual, a hiperglicemia é definida como glicemia acima de 140 mg/dL (jejum) ou\n180 mg/dL (coleta aleatória).","B":"a hipoglicemia é definida como glicemia abaixo de 70 mg/dL, considerada grave se for inferior a\n40 mg/dL.","C":"os valores de corte devem ser padronizados em cada hospital.","D":"nos pacientes hiperglicêmicos sem DM prévio, níveis de A1C superiores a 6,5% permitem\nestabelecer o diagnóstico de DM. Sendo que\nperdas e transfusões sanguíneas, hemoglobinopatias,\ninsuficiência renal e uso prolongado de corticoides não reduzem a sensibilidade da A1C."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-206106","number":"206106","sourceNumber":"206106","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O DM agrava a evolução das doenças coexistentes que causam internação e aumenta\no risco de morte. sendo que entre os\ndiabéticos, deve-se identificar o tipo, o tratamento, o nível de\ncontrole e a frequência da hipoglicemia. Os diabéticos devem passar por avaliação contínua do\nrisco de queda e da ocorrência de úlceras. Dentre as opções a seguir, marque a INCORRETA:","options":{"A":"De 15% a 35% dos internados têm DM.","B":"50% dos diabéticos desconhece o diagnóstico.","C":"40% dos não diabéticos apresentam hiperglicemia.","D":"O DM e a hiperglicemia influenciam o prognóstico."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-177246","number":"177246","sourceNumber":"177246","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um homem com 61 anos de idade procura atendimento médico em ambulatório de\ndislipidemia para ouvir uma segunda opinião a respeito do tratamento que ele realizava para\ncontrolar os níveis elevados do próprio colesterol LDL. Ele afirma que, ao longo da vida ,\napresentou valores sempre altos de LDL-C, com valor máximo de 214 mg/dL, há dois anos. No\núltimo exame , realizado no presente mês, os resultados foram: colesterol total (CT) de 242 mg/dL,\nLDL-C de 178 mg/dL e colesterol HDL de 45 mg/dL. O paciente é portador de hipertensão arterial\nsistêmica , com controle adequado e uso de duas classes de medicamentos (I-ECA e bloqueador\nde canal de cálcio). Nega diabetes ou tabagismo. Além disso, o paciente questiona qual seria o\nbenefício do tratamento proposto por outra equipe médica, depois que ele obteve informações em\nrede sociais. Com base no referido caso clínico e considerando o tratamento da elevação do\ncolesterol LDL, assinale a anativa correta.","options":{"A":"Neste caso, a redução do colesterol LDL, conseguida com medicamentos ou mudança do estilo\nde vida do paciente, equivale aos desfechos\ncardiovasculares maiores, por se tratar de pacientente\nestratificado na categoria de baixo risco cardiovascular.","B":"O achado de espessamento da íntima-média de carótida, em 1,5 mm, indicaria o uso de\nestatinas potentes, como a rosuvastatina na\nprevenção de desfechos cardiovasculares maiores.","C":"Se o paciente já fizer uso da estatina, não há benefício em reduções de LDL para valores\ninfiores a 70 mg/DL , indepedentemente do risco cardiovascular.","D":"O valor do colestreol LDL não interfere na estratificação de risco e, portanto, não interfere na\nescolha da estatina.","E":"A meta de colestrol HDL não deve ser usada como critério de prevenção de desfechos."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-175098","number":"175098","sourceNumber":"175098","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Crises Hiperglicêmicas Agudas levam a diversas complicações devido à situação em si,\nbem como relacionadas ao tratamento instituído, tanto a CAD Ceto Acidose Diabética quanto a\nEHH Estado Hiperglicêmico Hiperosmolar são graves situações, que apenas não se relacionam\ncom o seguinte item:","options":{"A":"São as complicações mais comuns da CAD e do EHH são hipoglicemia secundária ao uso\ninapropriado de insulina.","B":"A hipopotassemia devida à administração de doses inadequadas de insulina e/ou de bicarbonato\nde sódio.","C":"A hiperglicemia secundária à interrupção de infusão de insulina sem cobertura correta de\ninsulina subcutânea.","D":"O edema cerebral é uma complicação bastante comum no adulto, mas não evolui com herniação\nde tronco cerebral."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183869","number":"183869","sourceNumber":"183869","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Acerca de pacientes diabéticos, julgue o próximo item. Esses pacientes são submetidos\ncom maior frequência a intervenções\ncirúrgicas do que pacientes não diabéticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-175149","number":"175149","sourceNumber":"175149","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A presença de Capsulite Adesiva (CA) associa-se à idade e à duração da doença no\nDiabético, principalmente no DM1, o que explica a maioria das associações a outras complicações\ncrônicas do diabetes. Não há, no entanto, clara relação com o grau de controle glicêmico. Das\nalternativas a seguir, é inadequada a seguinte associação:","options":{"A":"Pacientes diabéticos com CA têm níveis de colesterol e triglicerídeos mais elevados, e alguns\nestudos mostram associação com o infarto agudo do miocárdio.","B":"A alteração patológica básica é um espessamento da cápsula articular, que adere à cabeça do\número, resultando em redução acentuada do volume da articulação glenoumeral.","C":"Ocorre perda da amplitude de movimento da articulação, levando à disfunção, à dificuldade de\nrotação externa e à abdução do ombro acometido.","D":"Pessoas com diabetes têm quadros, em geral, mais dolorosos, com maior duração e pior\nresposta ao tratamento."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-175158","number":"175158","sourceNumber":"175158","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Algumas pesquisas demonstram índices aumentados de cáries em diabéticos,\nentretanto outras encontraram incidências similares\nou até menores nesses pacientes quando\ncomparados a controles não diabéticos. Determine qual conceito se mostra inadequado:","options":{"A":"Em indivíduos com níveis de glicose sanguínea mal controlados, tanto a saliva como o fluido\ngengival não apresentam alterações das quantidades de açúcares.","B":"Em indivíduos com níveis de glicose sanguínea mal controlados ou não controlados, pode\nocorrer alteração da microbiota do biofilme\ndental, influenciando o desenvolvimento de cáries.","C":"Em indivíduos com níveis de glicose sanguínea mal controlados ou não controlados, é possível\nque as doenças periodontais fossem\ninfluenciadas.","D":"Por outro lado, a ingestão limitada de carboidratos, comum nesse grupo de pacientes,\nproporciona uma dieta menos cariogênica, o que\ndiminuiria o risco de surgimento dessas lesões."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-175160","number":"175160","sourceNumber":"175160","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Quando analisamos a complexa fisiopatologia do DM tipo 1, determinamos que a\nmesma envolve fatores genéticos e ambientais. No atual conhecimento, apenas uma das\nalternativas se mostra completamente adequada, assinale-a:","options":{"A":"É uma condição raramente poligênica.","B":"Na minoria dos casos, os principais genes envolvidos estão no sistema do antígeno leucocitário\nhumano (HLA) classe II.","C":"Entre os fatores ambientais potenciais para o desencadeamento da autoimunidade em\nindivíduos geneticamente predispostos estão certas infecções virais.","D":"Entre os fatores ambientais potenciais para o desencadeamento da autoimunidade em\nindivíduos geneticamente resistentes estão fatores\nnutricionais (p. ex., introdução precoce de leite\nbovino), deficiência de vitamina D e outros."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-175171","number":"175171","sourceNumber":"175171","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Espôndilo-Hiperostose Difusa Idiopática (EHDI), também conhecida como\nhiperostose ancilosante ou doença de Forestier,\ncaracteriza-se por uma limitação progressiva da\ncoluna vertebral, com calcificação dos ligamentos intervertebrais, formando pontes ósseas entre as\nvértebras (sindesmófitos), que, diferentemente da osteo artrite primária, não provocam\ndegeneração significativa do disco intervertebral. Pode ocorrer também ossificação de ligamentos e\ntendões em outros locais, como crânio, pelve, calcanhares e cotovelos. Dados epidemiológicos a\ncorrelacionam com descontrole metabólico, assinale o item abaixo se mostra inadequado:","options":{"A":"O acometimento é sistêmico, é explicado apenas por reação a fatores mecânicos locais.","B":"Sua prevalência é três vezes maior em pacientes com DM.","C":"Quando se analisa a população de pacientes com hiperostose difusa, 12 a 80% têm DM ou\nintolerância à glicose.","D":"Postula-se que concentrações séricas de insulina e de fator de crescimento semelhante à\ninsulina (IGF-1) mantidas prolongadamente elevadas nos pacientes diabéticos estimulem a\nneoformação óssea."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-175175","number":"175175","sourceNumber":"175175","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Ao avaliar um caso na Ortopedia nessa manhã, um colega solicitou sua opinião sobre a\npossibilidade de Infarto Muscular Diabético, fundamentado em dados epidemiológicos você,\nadequadamente, respondeu as dúvidas, exceto por um dos itens abaixo que está INCORRETO:","options":{"A":"Trata-se de uma condição rara que é geralmente observada em pacientes com Diabetes Mellitus\ntipo 1.","B":"Trata-se de uma condição em pacientes com Diabetes Mellitus principalmente naqueles com\ntempo longo de doença e mal controlados.","C":"Apresenta-se como massa endurecida, dolorosa, não traumática, especialmente na coxa (mais\nde 80% dos casos).","D":"Há sempre um mal prognóstico, evoluindo frequentemente com Rabdomiolise."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-183946","number":"183946","sourceNumber":"183946","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebral (AVC) e de infarto agudo do miocardio (IAM), julgue o\nitem a seguir. A obesidade e o sobrepeso constituem condições de risco para várias enfermidades\ncardiovasculares, como hipertensão, dislipdemias e diabetes tipo 2. No Brasil, a prevalência de\nsobrepeso, que era predominante entre mulheres, sofreu inversão, sendo o sobrepeso mais\nfrequente atualmente entre os homens.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-154516","number":"154516","sourceNumber":"154516","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a única afirmação INCORRETA sobre a cetoacidose diabética:","options":{"A":"Pode se manifestar por náuseas, vômitos e intensa dor abdominal, simulando abdome agudo\ninflamatório.","B":"Pode ser precipitada pelo uso de corticoides e agentes simpatomiméticos.","C":"Pode apresentar leucocitose com desvio à esquerda, mesmo na ausência de processo\ninfeccioso subjacente.","D":"É uma das causas de acidose metabólica com ânion-gap normal.","E":"O tratamento deve incluir reposição volêmica e insulinoterapia, com concomitante vigilância e\ntratamento dos níveis séricos de potássio."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-158036","number":"158036","sourceNumber":"158036","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Determinado paciente de 55 anos de idade começou recentemente a consultar-se em\numa clínica por insistência da esposa. Ele\nestá na terceira consulta, após repetir os exames\nlaboratoriais e confirmar o diagnóstico DM2. O paciente é assintomático e com sobrepeso, iniciou\numa dieta adequada há pouco tempo e parou de fumar há cinco anos quando tinha uma carga\ntabágica de 80 anos/maço. Também por insistência da esposa está tentando, embora com\ndificuldade, realizar caminhadas. Acerca do caso clínico apresentado, assinale a alternativa\nCORRETA.","options":{"A":"A fundoscopia deve ser realizada cinco anos após o diagnóstico do DM2 e, então, anualmente.","B":"A pesquisa de albuminúria em amostra isolada de urina é dispensável, se a função renal estiver\nnormal.","C":"A realização do índice tornozelo-braço é indicada.","D":"A radiografia de tórax deve ser solicitada para rastreio da neoplasia de pulmão, em razão da\ncarga tabágica.","E":"O teste do monofilamento nessa consulta, somente indicará sensibilidade protetora alterada\nquando duas ou mais das áreas testadas estiverem\ninsensíveis, quando utilizada a recomendação\nde Boulton et al. que inclui quatro áreas de teste."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-159506","number":"159506","sourceNumber":"159506","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A respeito da Cetoacidose Diabética (CAD), complicação aguda do diabetes melito,\njulgue o item subsecutivo. Os objetos\nbásicos do tratamento da CAD incluem reposição das perdas\nde fluidos, correção lenta da hiperglicemia e da acidose metabólica bem como correção dos\ndistúrbios eletrolíticos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-159511","number":"159511","sourceNumber":"159511","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A respeito da Cetoacidose Diabética (CAD), complicação aguda do diabetes melito,\njulgue o item subsecutivo. Pneumonia, infecção do trato urinário, abuso de álcool, infarto do\nmiocárdio e uso de corticoides são exemplos de fatores precipitantes de CAD.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-168472","number":"168472","sourceNumber":"168472","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma mulher com 50 anos de idade é encaminhada ao ambulatório de Nefrologia pela\nEquipe de Saúde da Família apresentando quadro de síndrome nefrótica. A paciente relata que, há\n3 meses, iniciou-se edema nos tornozelos. O edema ascendeu progressivamente, estando,\natualmente, na altura dos joelhos. Refere ganho de 10 kg nesse período, além de astenia. Nega\nhematúria, febre, lesões cutâneas ou queixas respiratórias Relata ser diabética há 10 anos,\nfazendo uso irregular de metformina (850 mg, 1 a 2 vezes/dia) e glibenclamida (5 mg, 1 a 2\nvezes/dia) sem acompanhamento médico há, pelo menos, 5 anos. O exame físico revela palidez\ncutâneo-mucosa, hipertensão arterial (pressão arterial = 180 x 100 mmHg) e importante edema de\nmembros inferiores (++++/4+). Os resultados dos exames solicitados pelo médico da Equipe de\nSaúde da Família demonstram: hemoglobina = 10 g/dL (valor de referência: 12 a 14 g/dL),\nhematócrito = 31% (valor de referência: 36 a 42%), VCM = 95 fL (valor de referência 80 a 100 fL),\nHCM = 31 pg (valor de referência: 27 a 32 pg), RDW = 13,4% (valor de referência: 11,5 a 15%);\nsérie branca e plaquetas normais; creatinina = 4,8 mg/dL (valor de referência 0,6 a 1,2 mg/dL),\nureia = 190 mg/dL (valor de referência: 15 a 38 mg/dL); glicemia de jejum = 230 mg/dL (valor de\nreferência: < 126 mg/dL), hemoglobina glicada = 9,0% (valor de referência: < 6,5%); sódio = 143\nmEq/L (valor de referência: 136 a 145 mEq/L), potássio = 5,5 mEq/L (valor de referência: 3,5 a 5,1\nmEq/L); colesterol total = 305 mg/dL (valor de referência: < 200 mg/dL), HDL = 30 mg/dL (valor de\nreferência: > 45 mg/dL); triglicerídeos = 322 mg/dL (valor de referência: < 150 mg/dL); albumina\nsérica = 2 g/dL (valor de referência: 3,5 a 4,5 g/dL); urina EAS = proteína +++ (valor de\nreferência:\nausente) e glicose ++ (valor de referência: ausente); proteinúria de 24 h = 5 g (valor de\nreferência: <\n0,5 g). Após a avaliação inicial, é feita uma ultrassonografia, que mostra rins de tamanho normal e,\nentão, é realizada biópsia renal, cujo resultado indica esclerose nodular mesangial. O presente\nquadro clínico indica que o prognóstico é de","options":{"A":"estabilização do comprometimento parenquimatoso e da função renal, desde que seja obtido o\ncontrole da glicemia.","B":"estabilização do comprometimento parenquimatoso e da função renal, desde que seja obtido o\n\ncontrole da pressão arterial.","C":"evolução para insuficiência renal crônica terminal por alteração da função renal, presença de\nhipertensão arterial e proteinúria nefrótica.","D":"evolução para insuficiência renal crônica terminal por alteração da função renal, persistência da\nhiperglicemia e alterações do metabolismo de lipídios."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-168465","number":"168465","sourceNumber":"168465","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um adolescente com 15 anos de idade é encaminhado à Unidade de Pronto\nAtendimento após ter apresentado vômitos e\nmal-estar em uma festa em que havia bebidas\nalcoólicas disponíveis. Em consulta, o paciente nega ter tomado tais bebidas. Ele é previamente\nhígido e também nega uso de medicamentos ou drogas ilícitas. Segundo relato dos familiares que o\nacompanham, o paciente faz dieta para perder peso, sem acompanhamento médico, e fica muitas\nhoras sem se alimentar. À admissão na unidade, ele apresenta hálito cetônico e está sonolento,\norientado, desidratado, acianótico, hemodinamicamente estável, com frequência respiratória = 36\nirpm, murmúrio vesicular fisiológico, abdome difusamente doloroso à palpação profunda e com os\nruídos hidroaéreos diminuídos, saturação arterial de oxigênio em ar ambiente = 95%. Os exames\ncomplementares iniciais realizados na unidade revelaram: glicemia = 380 mg/dL (valor de\nreferência: 99 mg/dL); gasometria arterial com pH = 7,24 (valor de referência: 7,35 a 7,45); PaO2 =\n100 mmHg (valor de referência: 83 a 108 mmHg); PaCO2 = 40 mmHg (valor de referência: 35 a 45\nmmHg); HCO3- = 14 mmol/L (valor de referência: 22 a 29 mmol/L); BE = -4 mmol/L (valor de\nreferência: -2,0 a +2,0 mmol/L); SaO2 = 98% (valor de referência: 95 a 99%); pesquisa de\ncetonemia positiva (valor de referência: negativa); Na+ = 130 mE/L (valor de referência 135 a 145\nmEq/L); K+ = 2,9 mEq/L (valor de referência 3,5 a 5,5 mEq/L); Cl- = 95 mEq/L (valor de referência\n96 a 109 mEq/L); amilase sérica = 120 U/L (valor de referência < 90 U/L). Diante do quadro clínico\ndescrito, quais são o diagnóstico mais provável e o tratamento inicial adequado para esse\npaciente?","options":{"A":"Cetoacidose diabética; hidratação com solução fisiológica e cloreto de potássio por via\nintravenosa.","B":"Cetoacidose diabética; administração imediata de insulina por via endovenosa.","C":"Cetoacidose secundária a pancreatite aguda; hidratação com solução fisiológica e\nantibioticoterapia por via intravenosa.","D":"Cetoacidose alcoólica; hidratação com solução fisiológica e tiamina por via intravenosa."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-168473","number":"168473","sourceNumber":"168473","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um homem com 43 anos de idade, sem histórico de tabagismo, fez dosagem da sua\nglicemia de jejum em exame de rotina no serviço de medicina do trabalho, tendo sido encontrado\ncomo resultado o valor de 120 mg/dL (valor de referência: < 110 mg/dL). Devido ao quadro, foi\nencaminhado a uma Unidade Básica de Saúde (UBS) para avaliação médica. O médico que o\natendeu, não tendo detectado história familiar de diabetes melito, nem encontrado alterações em\nseu exame clínico, pediu novo exame para dosagem da glicemia em jejum, que apresentou o\nresultado de 120 mg/dL. Solicitou, então, dosagem de glicemia 2 horas pós-carga (pós-prandial) e\ndosagem de hemoglobina glicada, que apresentaram, respectivamente, os seguintes resultados:\n160 mg/dL (valor de referência: < 140 mg/dL) e 6,1% (valor de referência: < 5,7%). O paciente foi\norientado sobre alimentação saudável e mudanças de hábitos de vida. Nessa situação e de acordo\ncom o estabelecido pelo Ministério da Saúde, quais devem ser o intervalo de tempo recomendado\npara reavaliação do paciente e a conduta médica adequada no retorno?","options":{"A":"A cada 3 meses; exame clínico na UBS.","B":"A cada mês; dosagem da glicemia em jejum.","C":"A cada ano; dosagem da glicemia em jejum.","D":"A cada 6 meses; dosagem da hemoglobina glicada."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-168495","number":"168495","sourceNumber":"168495","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um homem com 18 anos de idade procura a Unidade Básica de Saúde com queixas de\nindisposição, poliúria, polidipsia e perda ponderal de 5 kg nos últimos 4 meses. Realizou teste de\nglicemia de jejum no dia anterior, cujo resultado foi de 382 mg/dL. O paciente relata que não há\nhistória de diabetes melito na família. Ao exame físico, constata-se índice de massa corporal = 20,9\nkg/m², circunferência abdominal 90 cm, pressão arterial = 123 x 82 mmHg; não se observa\nacantose nigricans. O resultado do exame clínico dos aparelhos circulatório e respiratório do\npaciente é normal. Diante dese quadro, o médico introduziu insulinas NPH e regular de imediato e\nencaminhou o paciente ao endocrinologista para seguimento. Nessa situação, a orientação médica\nadequada a esse paciente e seus familiares é","options":{"A":"a introdução de dieta hipocalórica, para perda de 5 a 10% do peso e redução mais rápida da\nglicemia.","B":"a suspensão da dieta e da insulina em casos de síndromes febris ou diarreia, para diminuir\nriscos de hipoglicemia.","C":"a suspensão da insulina NPH quando a glicemia de jejum for menos que 100 mg/dL, devido ao\nrisco de hipoglicemia.","D":"o adiamento do início de atividade física, pois existe o risco do paciente desenvolver\ncetoacidose\nglicêmica nesse momento."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-111329","number":"111329","sourceNumber":"111329","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação à insuficiência adrenal, é CORRETO afirmar:","options":{"A":"O diagnóstico de crise adrenal é sempre clínico,\n\ndevendo o tratamento ser iniciado rapidamente sempre que houver a suspeita da doença.","B":"A hipoglicemia não é um achado frequente.","C":"A dosagem de cortisol basal sempre define o\ndiagnóstico.","D":"Hiperpigmentação cutânea, astenia, perda de peso e hipotensão sugerem o quadro de\ninsuficiência adrenal secundária.","E":"A dosagem de ACTH é fundamental para definir o melhor modo de tratamento."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-80703","number":"80703","sourceNumber":"80703","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa que apresenta uma manifestação da insuficiência adrenal aguda.","options":{"A":"Taquicardia.","B":"Hipotermia.","C":"Hipertensão.","D":"Hipopotassemia.","E":"Hipernatremia."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-97790","number":"97790","sourceNumber":"97790","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma mulher com 35 anos de idade procura atendimento na Unidade Básica de Saúde\npara tratamento de obesidade. Manifesta desejo\nde usar medicações para diminuir a sensação de\nfome, pois refere que uma vizinha está tendo bons resultados com o uso de medicamentos há\nvários meses. A paciente é casada, tem três filhos - o mais novo com dois anos - e atualmente não\nestá trabalhando. Relata que ganhou muito peso durante a última gestação e que não conseguiu\nretornar ao peso anterior. Nega hipertensão ou diabetes. Não consegue fazer atividade física\nregular, pois tem dores na coluna e nos joelhos e diz que tem dificuldade em seguir dietas. O\nexame físico revela: peso = 78 kg; altura = 1,62 m; Índice de massa corporal - IMC = 29,7 kg/m²;\npressão arterial = 130 x 80 mmHg; circunferência abdominal = 90 cm. O restante do exame físico\nnão apresenta alterações significativas. Com base nessas informações, é correto afirmar que:","options":{"A":"existe indicação para tratamento farmacológico e a droga de escolha é a sibutramina na dose\nde 15 mg ao dia.","B":"os valores de circunferência abdominal e IMC colocam a paciente em situação de aumento de\nrisco cardiovascular.","C":"pelo cálculo do IMC, a paciente é classificada como de peso adequado, não necessitando\nintervenção medicamentosa.","D":"existe indicação para uso de inibidor da enzima de conversão, pelo risco de progressão para\nhipertensão arterial sistêmica."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-97818","number":"97818","sourceNumber":"97818","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente com 56 anos de idade, com antecedentes de obesidade desde a\nadolescência e hipertensão arterial\nsistêmica há cerca de 15 anos, em uso de enalapril ? 10 mg\nduas vezes ao dia, procurou ambulatório de clínica médica com queixas de poliúria e polidipsia\niniciadas há cerca de três meses. Ele refere que perdeu cerca de 9 kg nesse período, sem\nalterações na dieta habitual. Nega também doenças cardíacas, renais ou hepáticas. O paciente é\nsedentário e trouxe exame da semana anterior que mostra glicemia de jejum de 346 mg/dl (valor de\nreferência = 75-99 mg/dl) e uma outra glicemia de jejum, do dia anterior à consulta, de 334 mg/dl. A\nglicemia capilar no momento da consulta foi de 441 mg/dl. Ao exame físico, paciente encontra-se\nem estado geral regular, eupneico, desidratado (+/4+) e corado. Observa-se acantose nigricans\ncervical, Índice de Massa Corporal (IMC) = 28,7 kg/m², circunferência abdominal = 105 cm, pressão\narterial 130 x 70 mmHg sentado e de pé. Auscultas cardíaca e pulmonar normais. Além da\norientação dietética e da prática de atividade física, a conduta a ser adotada, neste momento, com\nposterior reavaliação, deve ser:","options":{"A":"Tratamento sem medicamentos por enquanto.","B":"Metformina ? 500 mg 2 vezes ao dia.","C":"Glibenclamida ? 5 mg 2 vezes ao dia.","D":"Insulina NPH ? 10 U ao deitar."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-97774","number":"97774","sourceNumber":"97774","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um homem com 34 anos de idade, sem antecedentes patológicos prévios, procurou\nontem uma unidade básica de saúde porque vem\nevoluindo nos últimos quatro meses com queixas\nde poliúria, polidipsia e perda ponderal de cerca de 7 kg nesse período. Há dois meses realizou\nexames complementares que evidenciaram glicemia de jejum 348 mg/dl (valor de referência =\n\n75-99 mg/dl). Nega história de diabetes na família. Desde então, faz uso de doses crescentes de\nmetformina e glibenclamida, atualmente com 1.700 mg/dia e 10 mg/dia, respectivamente. As\nauscultas cardíaca e pulmonar são normais. Refere persistência dos sintomas e os exames\ncomplementares colhidos hoje revelaram: glicemia de jejum = 296 mg/dl; glicemia 2h após o café\nda manhã = 412 mg/dl; hemoglobina glicada = 10,1% (valor de referência = 3,8%-6,4%). Ao exame\nfísico, paciente mostra-se desidratado, corado; pressão arterial = 110 x 75 mmHg; circunferência\nabdominal = 92 cm; Índice de Massa Corporal (IMC) = 23,3 kg/m²; peso = 60 kg. Além de\nreferenciar para o especialista, a conduta adequada para esse paciente é:","options":{"A":"Aumentar as doses de glibenclamida e de metformina, adicionar insulina NPH antes de dormir.","B":"Manter as doses de glibenclamida e metformina, adicionar insulina NPH antes do café da manhã\ne antes do jantar.","C":"Suspender glibenclamida e metformina, adicionar insulina NPH antes do café da manhã e antes\nde dormir, bem como insulina regular antes das\nrefeições.","D":"Suspender glibenclamida, manter metformina, adicionar insulina NPH antes do café da manhã e\nantes do jantar, bem como insulina regular antes do café da manhã."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-75519","number":"75519","sourceNumber":"75519","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Criança com 9 anos de idade, previamente hígida, desenvolveu quadro de astenia há\ndois dias. Há seis horas passou a apresentar alguns episódios de vômito, dor abdominal, poliúria e\npolidipsia. Foi levada pela mãe ao pronto-socorro, onde chegou com quadro de desidratação e\nconfusão mental. O plantonista solicitou gasometria arterial, que apresentou o seguinte resultado:\npH = 7,2; pO2 = 75 mmHg; pCO2 = 30 mmHg; HCO3-= 12 mEq/L e Excesso de base (BE) = -18\nmEq/L.\n\nCom base no quadro clínico e exames laboratoriais, o diagnóstico e a conduta imediata são,\nrespectivamente:","options":{"A":"cetoacidose diabética; corrigir desidratação pelo\ncálculo da depleção do espaço extracelular.","B":"intoxicação exógena aguda; administrar carvão ativado e tomar medidas para estabilização do\npaciente.","C":"obstrução intestinal; corrigir a desidratação, além de solicitar US abdominal para confirmar o\ndiagnóstico.","D":"pancreatite aguda; encaminhar para Unidade de\nTerapia Intensiva para monitorização e suporte.","E":"gastroenterocolite aguda; corrigir desidratação de\nacordo com o seu grau."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-137541","number":"137541","sourceNumber":"137541","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma mulher de 64 anos de idade, obesa, diabética do tipo II há 10 anos, faz uso de\nmetformina em dose alta (2 g/dia), sem obter controle glicêmico adequado. Em consulta\nambulatorial de controle, realizada há dez dias, apresentava: peso = 70 kg; glicemia de jejum =\n197 mg/dL (valor de referência: 99 mg/dL); hemoglobina glicada = 7,9% (valor de referência: 4 a\n6,4% Hb);\n\nmicroalbuminúria. Naquela ocasião, foi negociada com a paciente a suspensão da metformina e o\ninício de insulina NPH-14 UI antes do café da manhã e 7 UI antes do jantar. Retornando à consulta\nhoje, a paciente traz controles de glicemias capilares > 200 mg/dL em cada três de quatro\ndosagens diárias, realizadas durante uma semana. Qual a conduta mais adequada em relação às\ndoses de insulina?","options":{"A":"Trocar a insulina NPH por insulina lispro antes do café da manhã.","B":"Trocar a insulina NPH por insulina glargina antes do café da manhã.","C":"Acrescentar insulina regular antes das refeições e meia\ndose às 22h.","D":"Aumentar a dose da insulina NPH da manhã e acrescentar\ndose extra às 22h.","E":"Aumentar as doses da insulina NPH antes do café da manhã\ne antes do jantar."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-137607","number":"137607","sourceNumber":"137607","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma criança de 9 anos de idade é levada ao serviço médico de urgência com quadro\nde confusão mental e desidratação. Os pais\nrelatam perda de 2 kg nos últimos 15 dias, apesar do\naumento da ingestão alimentar e sede constante. Ao exame físico: paciente desidratado +++/4,\ncom hálito cetônico. Exames laboratoriais: glicemia = 560 mg/dL (valor de referência < 100 mg /dL),\ngasometria: pH = 7,2 e bicarbonato = 12 mEq/L, sódio = 140 mEq/L, potássio = 5,7 mEq/L; exame\nde urina: glicose = ++, proteínas = ausentes, corpos cetônicos = ++, leucócitos = 2 000/mL e\neritrócitos = 3 000/mL. Qual a conduta mais adequada no caso?","options":{"A":"Sistema de infusão contínua de insulina e hidratação parenteral com potássio e bicarbonato.","B":"Insulina de ação prolongada glargina) e hidratação por via oral com soro e bicarbonato de sódio.","C":"Insulina de ação rápida (regular) por via intravenosa e hidratação parenteral com soro\nfisiológico, sem bicarbonato.","D":"Insulina de ação intermediária (NPH) por via subcutânea e hidratação parenteral com soro\nfisiológico, sem potássio.","E":"Insulina de ação prolongada (NPH) e insulina de ação rápida (basal-bolo) e hidratação por via\noral com soro glicosado, sem potássio."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-138590","number":"138590","sourceNumber":"138590","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, com 19 anos de idade, procura o pronto-socorro de um hospital secundário com\nqueixa de dor abdominal e vômitos há dois dias. Há cerca de quinze dias, apresenta tosse e coriza\namarelada e, há dez dias, poliúria e polidipsia. Comenta ter emagrecido 12 kg (18% do peso) nas\núltimas duas semanas. Informa não ter tido febre. Não relata antecedentes mórbidos pessoais ou\nfamiliares relevantes. Ao exame clínico, aparece vigil, consciente, orientada. Pontuação na escala\nde coma de Glasgow = 15. Corada, desidratada 2+/4+, taquipneica. Pressão arterial = 106 x 62\nmmHg, pulso = 104 bpm, frequência respiratória = 28 irpm. Abdome doloroso à palpação profunda\nde epigástrio, sem dor à descompressão brusca. Semiologia cardíaca, pulmonar, e de membros,\nnormais. Saturação de oxigênio em ar ambiente: 99 %. Glicemia capilar à entrada = 364 mg/dL.\nForam solicitadas dosagens séricas de eletrólitos, exame sumário de urina e gasometria venosa.\n\nAlém de se considerar o início de antibioticoterapia para o quadro respiratório alto, a conduta\nterapêutica imediata adequada é","options":{"A":"aguardar os exames, antes de outras etapas do tratamento.","B":"iniciar insulinoterapia, em bolus endovenoso, a ser\nmantida por infusão contínua.","C":"aguardar resultado da dosagem de eletrólitos (K+) e iniciar expansão com soro fisiológico","D":"preparar expansão com soro fisiológico e reposição de potássio","E":"introduzir expansão com soro fisiológico, reposição de potássio e insulinoterapia."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-138605","number":"138605","sourceNumber":"138605","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, com 57 anos de idade, sem acompanhamento médico regular, é atendida em\nambulatório de clínica médica de hospital secundário por queixa de edema de membros inferiores e\nface e de urina espumosa há três meses. A paciente não refere doenças anteriores e desconhece\nseus antecedentes familiares. Ao exame clínico encontra-se orientada, normocorada, hidratada,\nafebril, com edema de face (++/4). Pressão arterial (posição deitada) = 176 x 102 mmHg com pulso\n\n= 76 bpm; pressão arterial (posição supina) = 154 x 78 mmHg com pulso = 72 bpm. Frequência\nrespiratória = 18 irpm. Exame cardíaco\nnormal. Ausculta pulmonar: murmúrio vesicular diminuído\nnas bases pulmonares, sem ruídos adventícios. Abdome com sinais de ascite moderada, membros\ninferiores com edema compressível (++/4). Fundoscopia: prejudicada por opacificação do cristalino.\nExames complementares: Glicemia de jejum = 283 mg/dL, Creatinina = 1,8 mg/ dL, Ureia = 60\nmg/dL. Colesterol total = 312 mg/dL, LDL = 230 mg/dL, HDL = 40 mg/dL, VLDL = 42 mg/dL,\ntriglicérides = 210 mg/dL. Albumina sérica = 1,8 g/dL. Exame sumário de urina: proteinúria (++++/4),\nglicosúria (++/4), sem outras alterações. Proteína na urina de 24h= 5,5g. Dosagem de eletrólitos e\nhemograma normais. Qual a principal etiologia para o quadro apresentado por essa paciente?","options":{"A":"Hipertensão arterial sistêmica.","B":"Diabetes mellitus.","C":"Dislipidemia.","D":"Glomerulopatia por lesões mínimas.","E":"Lupus eritematoso sistêmico."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-138661","number":"138661","sourceNumber":"138661","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma criança de sexo feminino, com quatro anos de idade, é atendida no Pronto\nAtendimento com queixa de poliúria,\npolidipsia e emagrecimento nos últimos dois meses. Apesar de\nter havido um atendimento anterior por esta queixa, não houve uma definição diagnóstica. A mãe\ndecidiu retornar ao serviço porque nos últimos dois dias, a criança começou a apresentar\nsonolência, acompanhada de febre (dois picos de 38,6 °C), vômitos, fadiga, sinais de desidratação\ne taquipneia. Imediatamente, você decidiu encaminhar a paciente para um Serviço de Emergência,\ndevido à hipótese diagnóstica de cetoacidose diabética. A decisão de encaminhamento imediato foi\ndeterminada","options":{"A":"pela preocupação com a hipotensão, achado bastante comum nas crianças que desenvolvem\ncetoacidose diabética.","B":"para reposição volêmica e controle da glicemia. A\n\nhipotensão, na criança em cetoacidose diabética, é evento raro e tardio.","C":"pela alta mortalidade, característica da doença, cuja principal causa de morte está relacionada à\nhipotensão.","D":"pela hipertermia da criança, que requer imediata investigação diagnóstica.","E":"porque, em crianças lactentes e pré-escolares, além de adolescentes grávidas, a cetoacidose\nocorre com níveis de glicemia sempre muito\nelevados."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-368151","number":"368151","sourceNumber":"368151","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação à indicação de rastreamento de câncer de pâncreas para um paciente de\n60 anos de idade, obeso e com diagnóstico de\nDiabetes mellitus há um ano, assinale a alternativa\ncorreta.","options":{"A":"Há indicação formal de rastreamento, devido ao quadro de diabetes de início recente em\npaciente maior que 50 anos de idade.","B":"Não há indicação de rastreamento, pois só há fatores de baixo risco para câncer de pâncreas.","C":"Não há indicação de rastreamento, pois não há relação com o Diabetes mellitus, da forma\napresentada pelo paciente, com o câncer de pâncreas.","D":"Apesar de o Diabetes mellitus de início recente em pacientes com mais de 50 anos ser fator de\nalto risco para câncer de pâncreas, ainda não está bem estabelecida a indicação de rastreamento\nnesse grupo."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-368183","number":"368183","sourceNumber":"368183","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre a metformina, assinale a alternativa correta.","options":{"A":"Acidose lática é um efeito colateral comum da medicação.","B":"Metabólitos ativos são excretados por via renal, e, por isso, ela não deve ser administrada\nquando a TFG é < 50 mL/min/1,73 m².","C":"Reduz o débito de glicose produzido pelo fígado e melhora o perfil lipídico.","D":"Seu uso prolongado pode causar anemia megaloblástica devido à deficiência de ácido fólico."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-351616","number":"351616","sourceNumber":"351616","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre os efeitos extraglicêmicos dos fármacos utilizados no tratamento do Diabetes\nMellitus 2, assinale a alternativa CORRETA:","options":{"A":"A pioglitazona pode aumentar o risco de fraturas ósseas.","B":"Os inibidores SGLT-2 reduzem os níveis de LDL-c.","C":"Os agonistas do GLP-1 reduzem a frequência cardíaca.","D":"A linagliptina diminui temporariamente a TFG devido ao seu efeito de vasoconstrição à arteríola\naferente renal."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-335064","number":"335064","sourceNumber":"335064","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre os fatores de risco para doença cardiovascular, numere a coluna II de acordo\ncom a coluna I. COLUNA I 1. Resistência a\ninsulina 2. Obesidade 3. Dislipidemia 4. Hipertensão\narterial sistêmica. COLUNA II ( ) Há um aumento da atividade da enzima aromatase, com maior\nsíntese de estrogênio e consequente redução da testosterona no homem. ( ) Permanece como um\ndos mais importantes fatores de risco para mortalidade cardiovascular, ocorrendo essa associação\nindependentemente de outros fatores de risco. ( ) Está relacionada ao excesso de hormônio\nandrógeno em mulheres. ( ) É um fator de risco cardiovascular modificável muito relevante.\n\nAssinale sequência correta.","options":{"A":"3 1 2 4","B":"4 2 3 1","C":"2 4 1 3","D":"4 1 3 2"},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-346835","number":"346835","sourceNumber":"346835","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 56 anos queixa-se de emagrecimento apesar de estar se alimentando muito\nbem. Relata polaciúria com micções de grande volume, porém nega disúria, algúria ou alteração do\njato urinário. É obeso (IMC: 38,9kg/m² ), tabagista, portador de HAS e insuficiência cardíaca\nisquêmica, em uso de enalapril 20mg ao dia, AAS 100mg ao dia e atorvastatina 40mg ao dia. O\nexame físico não apresenta anormalidades. Exames de laboratório: glicemia de jejum 276mg/dL;\nHgA1C 10,7%; creatinina 1,2mg/dL. Assinale a alternativa que apresenta a prescrição inicial MAIS\nadequada nesse caso.","options":{"A":"Metformina.","B":"Empagliflozina.","C":"Insulina NPH e metformina.","D":"Insulina regular pré-prandial."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334718","number":"334718","sourceNumber":"334718","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem de 32 anos deu entrada no pronto socorro com poliúria, confusão mental e\nperda ponderal. Ao exame físico apresentava-se\ntorporoso, hipocorado, com níveis pressóricos de\n112/55 mmHg, frequência cardíaca de 93 bpm, temperatura axilar de 36,8°C, ausculta cardíaca e\nrespiratória sem alterações, sem dor ou visceromegalias à palpação abdominal, sem déficit\nneurológico focal. Os exames laboratoriais evidenciaram hemácias: 4,8 milhões/mm³, hemoglobina:\n16,9 g/dL, hematócrito: 55%, leucócitos: 8920/mm³, plaquetas: 288.000/mm³, glicose: 822 mg/dL,\nsódio: 158 mmol/L, potássio: 3,8 mmol/L, magnésio: 2,1 mg/dL, uréia: 56 mg/dL, creatinina: 1,0\nmg/dL; gasometria de sangue venoso: pH: 7,09, pCO?: 47 mmHg, pO?: 36 mmHg, bicarbonato: 18\nmeq/L; exame de urina: pH: 5,2, densidade: 1,045, glicose: ++++, proteínas: +, cetonas: ++++,\nbilirrubina: negativo, urobilinogênio: negativo, leucócitos: +, nitrito: negativo. Neste momento\ndevem\nser prescritos para este paciente.","options":{"A":"Cloreto de sódio a 0,9% e cloreto de potássio a 10%.","B":"Cloreto de sódio a 0,45%, cloreto de potássio a 10%, insulina regular.","C":"Cloreto de sódio a 0,9%, cloreto de potássio a 10%, insulina regular, bicarbonato de sódio a\n8,4%.","D":"Cloreto de sódio a 0,45%, cloreto de potássio a 10%, insulina regular, bicarbonato de sódio a\n5%."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-335073","number":"335073","sourceNumber":"335073","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considere um paciente portador de Diabetes mellitus tipo 2 há três anos, em uso de um\ncomprimido de metformina XR, 500 mg, duas vezes por dia (1.000 mg por dia), em\nmonoterapia.Apresenta um mapa da glicemia capilar com glicemia de jejum < 110 mg/dL e\n\npós-prandial > 190 mg/dL. Com base nas características dos fármacos listados, a melhor opção\nterapêutica para corrigir a hiperglicemia pós-prandial desse paciente é","options":{"A":"associar pioglitazona.","B":"associar um inibidor de DPP-4.","C":"associar insulina análoga.","D":"aumentar a metformina XR para 1.000 mg a cada 12 horas."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337628","number":"337628","sourceNumber":"337628","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Durante o ajuste das doses de insulina pode ser comum a ocorrência do efeito\nSomogyi. Nesse contexto, a medida clínica mais\nrecomendada para DIMINUIR a sua ocorrência\nserá:","options":{"A":"A dose de NPH deve ser diminuída pela manhã.","B":"A dose de NPH deve ser aumentada pela manhã.","C":"A dose de NPH deve ser diminuída à noite.","D":"A dose de NPH deve ser aumentada à noite."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-335105","number":"335105","sourceNumber":"335105","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente do sexo feminino, sete anos de idade, com queixa de dor abdominal e\nvômitos. Relata que vem apresentando\npolidipsia, polifagia e aumento da diurese há duas\nsemanas. Está desidratada, com hálito cetônico e apresenta hiperpneia. Glicemia capilar 350 mg/dl.\nAcerca do tratamento inicial dessa paciente, assinale a alternativa correta.","options":{"A":"Deve ser prescrita hidratação venosa, com soro glicosado 5%.","B":"Deve ser prescrita insulina regular venosa para redução da glicemia até valores abaixo de 100 ?\n\n80 mg/dL.","C":"Deve ser feito monitoramento de íons e restauração do equilíbrio hidroeletrolítico em 24 ? 36\nhoras.","D":"Deve ser prescrita, imediatamente, correção de bicarbonato para correção da acidose."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-313280","number":"313280","sourceNumber":"313280","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Com relação ao tratamento medicamentoso da Diabetes tipo 2 com Metformina, temos\ncomo possível efeito colateral:","options":{"A":"Aumento do peso.","B":"Infecção urinária.","C":"Deficiência de vitamina B12.","D":"Hipotensão e confusão mental.","E":"Aumento transitório da creatinina."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-314032","number":"314032","sourceNumber":"314032","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O Diabetes Mellitus (DM) do tipo 2 é um distúrbio progressivo definido por déficits na\nsecreção e ação da insulina, que causam metabolismo anormal da glicose e transtornos\nmetabólicos relacionados. Em relação ao diagnóstico do DM do tipo 2 em adulto, assinalar a\nalternativa CORRETA:","options":{"A":"Uma glicemia de jejum acima de 126mg/dL confirma o diagnóstico, na ausência de sintomas\ninequívocos de hiperglicemia.","B":"Uma hemoglobina glicosilada maior ou igual a 6,5% confirma o diagnóstico, na ausência de\nsintomas inequívocos de hiperglicemia.","C":"Uma glicemia maior que 140mg/dL, 2 horas após sobrecarga com 75g de glicose, confirma o\ndiagnóstico, na ausência de sintomas inequívocos de hiperglicemia.","D":"A confirmação do diagnóstico de DM é suficiente com um exame alterado, na ausência de\nsintomas inequívocos de hiperglicemia.","E":"Pacientes com sintomas clássicos de hiperglicemia devem ser submetidos à dosagem de\nglicemia ao acaso e independente do jejum; se glicemia aleatória ? 200mg/dL, confirma o\ndiagnóstico."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-313300","number":"313300","sourceNumber":"313300","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente, de 37 anos, portador de diabetes tipo 2, após a troca do hipoglicemiante\noral, tem apresentado retenção hídrica, anemia\nleve, ganho ponderal de peso e sinais de\ninsuficiência cardíaca. Pela sintomatologia, o hipoglicemiante em uso é:","options":{"A":"Metformina.","B":"Glimepirida.","C":"Pioglitazona.","D":"Acarbose.","E":"Clorpropamida."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-305031","number":"305031","sourceNumber":"305031","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Considere que um paciente de sete anos de idade, sexo feminino, com queixa de dor\nabdominal e vômitos, relata que vem apresentando polidipsia, polifagia e aumento da diurese há\nduas semanas. Está desidratada, com hálito cetônico e quadro de hiperpneia. Glicemia capilar =\n350 mg/dL. Nese caso, qual é o tratamento inicial dessa paciente?","options":{"A":"Deve ser prescrito hidratação venosa, com soro glicosado a 5%.","B":"Deve ser prescrito insulina regular venosa para redução da glicemia até valores abaixo de 100 ?\n\n80 mg/dL.","C":"Deve ser feito monitoramento de íons e restauração do equilíbrio hidroeletrolítico em 24 ? 36\nhoras.","D":"Deve ser prescrito, imediatamente, bicarbonato para correção da acidose."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-314083","number":"314083","sourceNumber":"314083","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação a diabetes tipo 1 e a diabetes tipo MODY, assinalar a alternativa\nCORRETA:","options":{"A":"Acantose nigricans é patognomônico de diabetes tipo 1.","B":"Cetoacidose é mais comum do tipo MODY.","C":"Hiperglicemia costuma ser mais intensa no tipo MODY.","D":"Autoanticorpos são mais frequentemente positivos no tipo 1.","E":"O tipo MODY costuma ter início mais abrupto e de evolução mais grave e acelerada."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-287333","number":"287333","sourceNumber":"287333","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"No plantão de pronto-socorro, dá entrada um paciente masculino, 16 anos, previamente\nhígido, com história de 36 horas com\nvômitos, polidipsia e poliúria. Ao exame físico, a pressão\narterial de 90 x 60 mmHg; frequência cardíaca de 120 bpm; frequência respiratória de 32 irpm. A\nglicemia capilar mostrou valor superior a 500 e a oximetria de pulso indicava 92% de saturação\narterial de oxigênio em ar ambiente. Qual a primeira conduta a ser adotada no caso?","options":{"A":"Insulina regular IV em bolus.","B":"Insulina regular em infusão contínua.","C":"Intubação endotraqueal.","D":"Reposição volêmica vigorosa com solução fisiológica."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-283893","number":"283893","sourceNumber":"283893","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação ao uso de estatinas, assinale a alternativa INCORRETA.","options":{"A":"Indicado para pacientes com doença clínica aterosclerótica.","B":"Indicado para indivíduos assintomáticos com LDL-colesterol ? 190 mg/dL.","C":"Indicado para indivíduos assintomáticos com risco calculado de mortalidade por doença\ncardiovascular ? 3% em 10 anos.","D":"Indicado para pacientes diabéticos entre 40-75 anos.","E":"Indicado como profilaxia secundária da cardiopatia isquêmica."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-227073","number":"227073","sourceNumber":"227073","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher de 65 anos vai ao consultório de clínica médica para acompanhamento clínico.\nEstá assintomática. É portadora de Diabetes\nMellitus tipo 2, obesidade, insuficiência cardíaca com\nfração de ejeção reduzida, osteoporose e doença renal crônica. Teve um infarto do miocárdio 2\nanos antes. Faz uso regular de metformina 850 mg de 12/12h, sinvastatina 40 mg 24/24h,\ncarvedilol 12,5 mg 12/12h, AAS 100 mg 24/24h. O exame físico não apresenta anormalidades.\n\nExames de laboratório: glicemia de jejum = 198 mg/dl, glico-hemoglobina = 8,7%, creatinina = 1,9\nmg/dl (clearance de creatinina = 27 ml/min/1,73 m²). Considerando o caso descrito, assinale a\nalternativa que apresenta a conduta CORRETA a ser adotada:","options":{"A":"Manter a metformina e associar a empagliflozina.","B":"Manter a metformina e associar a gliclazida.","C":"Suspender a metformina e prescrever a insulina NPH.","D":"Suspender a metformina e prescrever a pioglitazona."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-234404","number":"234404","sourceNumber":"234404","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um homem de 63 anos vai ao consultório de Clínica Médica para acompanhamento\nclínico. É portador de cirrose hepática\nalcoólica e insuficiência cardíaca alcoólica, com fração de\nejeção do ventrículo esquerdo reduzida. É ex-etilista há 6 meses. Apresenta infecções urinárias de\nrepetição, com 5 episódios no último ano. Faz uso regular de furosemida, enalapril e\nespironolactona. Ao exame físico, apresenta-se alerta e orientado; as mucosas são coradas,\nhidratadas e ictéricas. Apresenta eritema palmar, aranhas vasculares e ginecomastia. O exame\ncardiovascular revela aumento da pressão venosa central e presença da terceira bulha. Sem\nalterações no restante do exame. Exames de laboratório: hemoglobina 11,2g/dL; leucócitos\n4.630/mm³; plaquetas 97.000/mm³; creatinina 0,9mg/dL; albumina 2,6g/dL; bilirrubina total\n3,5mg/dL; bilirrubina direta 2,3mg/dL; RNI 2,1; glicemia de jejum 142mg/dL; glico-hemoglobina\n7,7%. Assinale a alternativa que apresenta o medicamento MAIS ADEQUADO dentre os\napresentados para o tratamento inicial do diabetes mellitus nesse paciente.","options":{"A":"Empagliflozina.","B":"Glimepirida.","C":"Metformina.","D":"Pioglitazona."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-246718","number":"246718","sourceNumber":"246718","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em pacientes que já sofreram um infarto do miocárdio previamente, o nível de LDL que\ndevemos perseguir, segundo as mais recentes\ndiretrizes de prevenção secundária, para reduzirmos\na chance de novo evento adverso em coronárias, é:","options":{"A":"LDL menor que 30 mg/dl","B":"LDL menor que 50 mg/dl","C":"LDL menor que 70 mg/dl","D":"LDL menor que 90 mg/dl","E":"LDL menor que 100 mg/dl"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-246349","number":"246349","sourceNumber":"246349","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Joana, 18 anos, sem comorbidades conhecidas, deu entrada no pronto socorro\nsonolenta, levada por familiares, que\nrelataram que a paciente iniciou nos últimos 3 dias quadro de\ndor abdominal, disúria e hematúria. À admissão a paciente apresenta-se prostrada, desidratada,\nsonolenta, pressão arterial = 100/60mmHg, frequência cardíaca = 125bpm, frequência respiratória =\n35irpm, temperatura axilar = 38.3°C. Exames laboratoriais de admissão: hemoglobina = 15.2g/dL,\nhematócrito = 45%, leucócitos = 17.500/mm3, plaquetas = 150.000/mm3, glicemia = 300mg/dL,\ngasometria arterial: (pH = 6.9, bicarbornato = 14, pCo2 = 30, pO2 = 95, BE = -5), potássio =\n3.8meq/L, sódio = 160meq/L, exame de urina simples com leucocitúria, piúria e corpos cetônicos,\nsem cilindros. Diante do caso, qual é o diagnóstico e a conduta mais apropriada?","options":{"A":"Cetoacidose diabética. Deve-se iniciar hidratação venosa com solução isotônica, reposição de\npotássio endovenosa, antibioticoterapia e insulina regular endovenosa.","B":"Cetoacidose diabética. Deve-se iniciar hidratação venosa com solução hipotônica, reposição de\npotássio endovenosa, antibioticoterapia, e insulina regular endovenosa.","C":"Estado hiperglicêmico hiperosmolar. Deve-se iniciar hidratação venosa com solução isotônica,\nantibioticoterapia, reposição de potássio endovenosa e insulina NPH endovenosa.","D":"Estado hiperglicêmico hiperosmolar. Deve-se iniciar hidratação venosa com solução isotônica,\nantibioticoterapia, reposição de potássio endovenosa e insulina regular endovenosa."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-246720","number":"246720","sourceNumber":"246720","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Pacientes portadores de ineficiência cardíaca (IC) costumam ter outras comorbidades\nassociadas, como hipertensão e diabetes. Essas patologias costumam aumentar o risco de morte\nnesses pacientes. Entretanto, os antidiabéticos, em sua maioria, não reduzem mortalidade\ncardiovascular. Neste contexto, dentre as medicações para DM 2, quais delas reduzem a\nmortalidade cardiovascular?","options":{"A":"Metformina e Insulina","B":"Glitazonas e Inibidores DPP4","C":"Metformina e Inibidores SGLT2","D":"Inibidores SGLT2 e Agonistas GLP1","E":"Nenhuma das anteriores"},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-243035","number":"243035","sourceNumber":"243035","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente de 23 anos, há 8 anos com diagnóstico de diabetes mellitus tipo I,\ndesenvolve microalbuminúria (confirmada em 2 exames). Sua pressão arterial é 124/74mmHg e\nseu clearance de creatinina estimado é 95ml/min. Qual é a conduta apropriada diante de tal\nevolução?","options":{"A":"indicar dieta hipoproteica (0,6g/Kg/dia).","B":"indicar bloqueador de canal de cálcio.","C":"repetir dosagem de microalbuminúria em 1 ano.","D":"indicar inibidor de enzima conversora de angiotensina (IECA).","E":"indicar beta-bloqueador."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-227311","number":"227311","sourceNumber":"227311","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O diabetes mellitus (DM) é uma síndrome metabólica caracterizada pela presença de\nhiperglicemia, com várias etiologias possíveis. Na diabete é correto afirmar:","options":{"A":"A presença de DM na infância ou na adolescência sempre está associada ao DM tipo 1.","B":"No DM tipo 1 o quadro clínico é bastante sugestivo, com aumento do apetite para doce, pouca\nsede, aumento da diurese e do ganho de peso.","C":"O MODY é definido como um diabetes familiar com idade de diagnóstico precoce (infância,\nadolescência ou adultos jovens) e modo de transmissão autossômico-dominante.","D":"A fase de \"\"lua-de-mel\"\" na DM tipo 1 ocorre durante a adolescência, quando devido à alteração\nhormonal, há um estímulo nas células beta, que passam a secretar alguma quantidade de insulina,\nhavendo redução na necessidade da dose diária de insulina."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-243068","number":"243068","sourceNumber":"243068","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente do sexo feminino, 67 anos, portadora de angina aos grandes esforços há 2\nanos. Apresenta hipertensão arterial (diagnosticada há 15 anos) e diabetes melito tipo 2 (há 10\nanos). Ao exame físico, apresenta pressão arterial (PA) = 150 x 90 mmHg; frequência cardíaca\n(FC) = 78 bpm. Dentre os exames laboratoriais, apresenta LDL colesterol de 100 mg/dL. Relata\nestar em uso de metformina XR 1.500 mg/dia e clortalidona12,5 mg/dia. Qual a melhor associação\nmedicamentosa na continuidade do tratamento desta paciente?","options":{"A":"ácido acetilsalicílico (AAS), ivabradina, estatina potente em dose alta e inibidor da enzima\nconversora da angiotensina.","B":"ácido acetilsalicílico (AAS), betabloqueador, estatina potente em dose alta e inibidor da enzima\nconversora da angiotensina.","C":"ácido acetilsalicílico (AAS), trimetazidina, estatina em dose baixa e bloqueador do receptor AT1\nda angiotensina II.","D":"clopidogrel, antagonista dos canais de cálcio, estatina potente em dose moderada e bloqueador\ndo receptor AT1 da angiotensina II.","E":"ticagrelor, ivabradina, estatina potente em dose alta e inibidor da enzima conversora da\nangiotensina."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-199525","number":"199525","sourceNumber":"199525","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Sobre a etiologia e fisiopatologia do Diabetes Mellitus, assinale a alternativa CORRETA:","options":{"A":"O diabetes autoimune acomete apenas crianças e\nadolescentes.","B":"A hipertrigliceridemia por deficiência de insulina\npode ocorrer no diabetes tipo 2, porém não no\ntipo 1.","C":"A acromegalia, a síndrome de Cushing e o\nhipotireoidismo são causas endócrinas de Diabetes Mellitus.","D":"O Diabetes Mellitus tipo 2 apresenta aumento da\nprodução hepática de glicose."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-199553","number":"199553","sourceNumber":"199553","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"São fatores relacionados à hiperuricemia:","options":{"A":"Uso de diuréticos tiazídicos, doenças cardiovasculares, tabagismo.","B":"Obesidade, hipertensão arterial, dieta rica em frutos do mar.","C":"Doença renal crônica, diabetes, uso de probenecida.","D":"Abuso de álcool, sedentarismo, consumo de açúcares."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-199541","number":"199541","sourceNumber":"199541","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa correspondente à principal causa de hipoglicemia refratária em\npaciente diabético tipo 2.","options":{"A":"Uso de dose excessiva de medicação.","B":"Agudização de doença renal.","C":"Insuficiêcia adrenal.","D":"Dieta restritiva."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-212896","number":"212896","sourceNumber":"212896","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Diabetes Mellitus (DM) é uma das mais importantes enfermidades que acometem nossa\npopulação atualmente. Acerca dela, pode-se afirmar que:","options":{"A":"O DM tipo 2 caracteriza-se por perda progressiva de secreção insulínica combinada com\nresistência a insulina.","B":"Para firmarmos o diagnóstico do DM tipo 1A devemos necessariamente excluir a presença de\num ou mais autoanticorpos.","C":"O Diabetes Mellitus tipo 2 (DM2) corresponde a 60% de todos os casos de DM.","D":"A glicemia em jejum deve ser coletada em sangue periférico após jejum calórico de no mínimo\n12 horas.","E":"Em idosos frágeis, o alvo de HbA1c deve ser de < 6,5%."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-220306","number":"220306","sourceNumber":"220306","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A cetoacidose diabética é um evento que pode ocorrer em um paciente portador de\ndiabetes mellitus tipo 1 e é considerada a principal causa de hospitalização e morbimortalidade.\nSão características da cetoacidose diabética, EXCETO:","options":{"A":"Glicemia plasmática superior a 200 mg/dl.","B":"Acidose metabólica (pH menor 7,3 e/ou bicarbonato sérico menor 15 mmol/l) com diminuição do\nânion-gap.","C":"Cetonemia (cetonas superiores a 3 mg/dl).","D":"Presença de cetonúria."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-202768","number":"202768","sourceNumber":"202768","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Homem, 70 anos, vem ao consultório para um retorno de check-up. É diabético,\nassintomático do ponto de vista\ncardiovascular, e não possui alterações ao exame físico. Traz entre\nos exames solicitados na primeira consulta, os seguintes: HDL 45 mg/ dL; LDL 108 mg/ dL;\ntriglicerídeos 330 mg/ dL; colesterol total 209 mg/ dL; hemoglobina glicada 6,6%; glicemia de jejum\n120 mg/ dL. Com relação ao tratamento da dislipidemia, é CORRETO afirmar:","options":{"A":"Faz-se necessária a adição de estatina para o controle da dislipidemia neste momento, além de\nmodificação no estilo de vida.","B":"A associação de genfibrozila e sinvastatina está indicada em razão dos níveis altos de\ntriglicerídeos e LDL.","C":"O tratamento da dislipidemia em idosos deve ter metas menos estritas, uma vez que essa\npopulação tem menor benefício no controle lipídico para a prevenção de doença cardiovascular.\nAssim, pode-se orientar apenas modificações do estilo de vida, além de ajustar o esquema\nhipoglicemiante.","D":"O tratamento desse paciente deve incluir estatina e niacina, visando à melhora dos níveis de\nLDL e HDL.","E":"A ezetimiba pode ser empregada nesse paciente em vez da estatina, visto que este grupo de\nfármacos provoca mais efeitos adversos nessa faixa etária."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-212948","number":"212948","sourceNumber":"212948","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Com relação ao diabetes mellitus na criança, é correto afirmar, exceto:","options":{"A":"Na presença de sintomas clínicos de diabetes, a dosagem de glicemia mostrando valor maior ou\nigual a 200 mg/dl confirma o diagnóstico.","B":"Na presença de sintomas clínicos de diabetes, e glicemia ao acaso com resultado maior ou igual\na 200 mg/dl, o paciente deverá ser\norientado a retornar após 24 horas, em jejum, para que seja\nrealizada nova dosagem confirmatória de nível glicêmico.","C":"Para o diagnóstico de diabetes mellitus em crianças, a dosagem de glicemia em jejum com\nresultado maior ou igual a 126 mg/dl deverá ser repetida.","D":"O pilar mais importante do tratamento do diabetes mellitus tipo 2 é a mudança de hábitos de\nvida, levando à normalização do IMC e redução da resistência insulínica.","E":"A metformina, agente farmacológico das biguanidas, é utilizado como primeira opção terapêutica\nem crianças e adolescentes com diabetes mellitus\ntipo 2."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-199611","number":"199611","sourceNumber":"199611","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Entre crianças e adolescentes diabéticos, a cetoacidose diabética é a descompensação\naguda mais grave e pode ser responsabilizada por\n50% das mortes em diabéticos com idade\ninferior a 24 anos. Na cetoacidose diabética é CORRETO afirmar:","options":{"A":"Na cetoacidose diabética sempre é possível identificar um fator causal para a descompensação.\n\nEntender a causa é fundamental para o tratamento.","B":"Nos casos mais graves de cetoacidose diabética, a elevação da amilase sérica indica,\nnecessariamente, a ocorrência de pancreatite.","C":"Laboratorialmente, a cetoacidose diabética caracteriza-se por hiperglicemia (glicemia superior a\n500 mg/dL) e acidose metabólica (pH <6,5 e/ou\nbicarbonato inferior a 5 mEq/L).","D":"Na cetoacidose diabética a dor abdominal pode ser intensa a ponto de simular apendicite,\npancreatite ou abdome agudo cirúrgico. Mas, na\nmaioria dos casos, a dor abdominal desaparece\ncom a hidratação, correção dos distúrbios eletrolíticos e insulinoterapia."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-196817","number":"196817","sourceNumber":"196817","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um jovem de 23 anos, com IMC = 34, relata que está com poliúria e polidipsia há cerca\nde três semanas. Nos últimos dias vem\napresentando dor abdominal, vômitos e sonolência. Na\navaliação médica inicial está com glicemia capilar de 955 mg/dl, K = 6,0 mEq/L e gasometria arterial\ncom pH = 7,11. EAS com glicosúria e cetonúria. Não há sinais clínicos de infecção. Demais exames\nlaboratoriais sem alterações significativas. Assinale a conduta inicial.","options":{"A":"Soro fisiológico 0,9% + poliestirenossulfonato de Ca + insulina.","B":"Soro fisiológico 0,9% + insulina.","C":"Soro fisiológico 0,9% + insulina + poliestirenossulfonato de Ca + bicarbonato de Na.","D":"Soro fisiológico 0,9% + bicarbonato de Na + insulina."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-215157","number":"215157","sourceNumber":"215157","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para o diagnóstico laboratorial de cetoacidose diabética (CAD) é preciso:","options":{"A":"Glicemia > 300 mg/dl.","B":"pH < 7,3 com bicarbonato < 15 mEq/L e ânion gap normal.","C":"pH < 7,3 e/ou bicarbonato <15 mEq/L e ânion gap elevado.","D":"Resultado negativo na reação urinária com nitroprussiato de sódio.","E":"Cetonas séricas superior a 6 mg/dl ou fortemente positivas em diluição do soro superior a 1:8."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-172817","number":"172817","sourceNumber":"172817","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher de 21 anos admitida no pronto-socorro com quadro de rebaixamento do nível de\nconsciência, desidratação e perda ponderal. Ao exame físico apresenta-se em Glasgow 14, com\nsinais clínicos de desidratação, pressão arterial de 90 x 55 mmHg, sem outras alterações\nsignificativas. Exames laboratoriais: hemoglobina = 12,8 g/dl; hematócrito = 54%; leucócitos =\n7.265/mm³; glicemia = 655 mg/dl; pesquisa de cetonemia positiva, pH de sangue venoso = 7,30;\nHCO3 = 14 mmol/L; sódio sérico = 149 mEq/L; potássio sérico = 3,5 mEq/L. Assinale a alternativa\nque corresponde à sequência CORRETA das ações que devem ser tomadas.","options":{"A":"Hidratação com solução salina isotônica, reposição de potássio e insulinização, ambos por via\nendovenosa.","B":"Hidratação com solução salina isotônica, insulinização e reposição de potássio, ambos por via\nendovenosa.","C":"Hidratação com solução salina hipotônica, reposição de potássio e insulinização, ambos por via\nendovenosa.","D":"Hidratação com solução salina hipotônica, insulinização e reposição de potássio, ambos por via\nendovenosa."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-174375","number":"174375","sourceNumber":"174375","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"No manejo medicamentoso dos pacientes de alto risco cardiovascular, segundo a\nDiretriz de Dislipidemia da Sociedade Brasileira de Cardiologia de 2017, as metas de LDL-c a\nserem atingidas e a estatina/dose diária a ser utilizada são, respectivamente:","options":{"A":"LDL-c < 70 mg/ dL, utilizar Sinvastatina/40 mg por dia.","B":"LDL-c < 50 mg/ dL, utilizar Rosuvastatina/40 mg por dia.","C":"LDL-c < 50 mg/ dL, utilizar Rosuvastatina/20 mg por dia.","D":"LDL-c < 70 mg/ dL, utilizar Rosuvastatina/20 mg por dia.","E":"LDL-c < 70 mg/ dL, utilizar Sinvastatina 20 mg + Ezetimiba 10 mg/dia."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-187483","number":"187483","sourceNumber":"187483","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A primeira defesa do nosso corpo contra a hipoglicemia ocorre por alteração no nível de\nqual das substâncias abaixo?","options":{"A":"Epinefrina.","B":"Glucagon.","C":"Cortisol.","D":"Insulina.","E":"IGF-1."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-155354","number":"155354","sourceNumber":"155354","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a opção que indica uma condição que não favorece a ocorrência de\ncetoacidose diabética:","options":{"A":"Pancreatite.","B":"Hemocromatose.","C":"Acromegalia.","D":"Hipotireoidismo.","E":"Uso de corticosteroides."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-148571","number":"148571","sourceNumber":"148571","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A diabetes mellitus não é uma única doença, mas um grupo heterogêneo de distúrbios\nmetabólicos que apresenta em comum a hiperglicemia, resultante de defeitos na ação da insulina,\nna secreção de insulina ou em ambas. Observe as afirmativas abaixo e marque a sentença\nCORRETA a respeito de diabetes mellitus nas crianças e adolescentes:","options":{"A":"A diabetes mellitus tipo 1 é caracterizada pela destruição reversível e autoimune das células ß\ndas ilhotas pancreáticas. Ocorre geralmente\nantes dos cinco anos e a melhora geralmente ocorre\napós os 21 anos.","B":"A diabetes mellitus tipo 2 é considerada uma doença poligênica, que ocorre apenas em adultos,\nagravada por fatores ambientais, tais como baixa atividade física ou uma dieta rica em lipídios.","C":"A diabetes mellitus tipo 1 é caracterizada por níveis baixos ou ausentes de insulina\nendogenamente produzida e dependência de insulina\nexógena para prevenir desenvolvimento da\ncetoacidose, uma complicação crônica que causa resistência insulínica.","D":"A diabetes mellitus tipo 1 é uma doença que sempre se inicia na primeira década de vida. O\ninício acima desta idade só é encontrado em outros tipos de diabete.","E":"Nas diabetes secundárias à fibrose cística e à síndrome de Cushing, não há associação com\nautoimunidade ou anticorpo anticélulas das ilhotas pancreáticas."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-77600","number":"77600","sourceNumber":"77600","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"São indicações para solicitar densitometria óssea, EXCETO:","options":{"A":"Mulher na pós-menopausa.","B":"Fratura patológica prévia.","C":"Corticoterapia prolongada.","D":"Litíase Renal.","E":"Homens com mais de 50 anos."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-77496","number":"77496","sourceNumber":"77496","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A paciente R.S.B., 57 anos, em pós-menopausa há 8 anos, assintomática, apresentou\no seguinte resultado de densitometria mineral\nóssea: T-escore de coluna lombar de L1-L4 = -1,3\nDP; T-score de fêmur total = -0,9 DP; T-score de colo do fêmur = -1,2 DP. Propedêutica\ncomplementar revelou: calcemia = 10,5 mg/dl (valor de referência: 8,6-10,2 mg/dl); fosfatemia = 2,9\nmg/dl (valor de referência: 2,5-4,5 mg/dl); fosfatase alcalina óssea específica sérica = 49,4 U/L\n(valor de referência: 14,2-42,7 U/L); paratormônio sérico = 85 pg/ml (valor de referência: 4-52\npg/dl); creatinina = 0,8 mg/dl; ureia = 24 mg/dl; ultrassonografia cervical sem evidência de imagem\nsuspeita; cintilografia de paratireoides com 99mTC-sestamibi evidenciando captação prolongada do\nradioisótopo em topografia do polo inferior do lobo direito da tireoide. Em relação ao quadro\nclínico\napresentado, assinale a alternativa INCORRETA:","options":{"A":"Osteíte fibrosa cística e síndrome neuropsiquiátrica podem ocorrer nas formas mais graves\ndesta doença.","B":"Estes achados podem estar presentes nas síndromes de neoplasias endócrinas múltiplas tipo 1\ne tipo 2.","C":"Raramente este quadro pode ser ocasionado por um carcinoma.","D":"Neste caso o tratamento de escolha é paratireoidectomia.","E":"Nos casos familiares, geralmente mais de uma glândula paratireoide encontra-se hiperplasiada."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-77369","number":"77369","sourceNumber":"77369","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente, 19 anos, sexo masculino, internado no HECI após alguns atendimentos em\nrede básica e em pronto atendimento, há\ncerca de 1 mês com história de fraqueza e discreto\nedema de membros inferiores, além de manchas hipercrômicas mais notadamente em face e\npernas. Refere ter sido também diagnosticado diabético em uma dessas consultas de pronto\natendimento, onde, além disso, era identificada presença de hipocalemia. Nesses atendimentos era\nmedicado com insulina e potássio e liberado para casa. Na admissão ao HECI, além das alterações\njá descritas, apresentava ainda hipertensão arterial (170 x 100). Exames laboratoriais iniciais\nmostravam hipocalemia grave (1,8), além de acentuada alcalose metabólica (bicarbonato de 50).\n\nNeste caso, qual a melhor hipótese diagnóstica?","options":{"A":"Insuficiência suprarrenal (doença de Addison).","B":"Paralisia hipocalêmica periódica.","C":"Uso inadequado de insulina nesses atendimentos anteriores de pronto-socorro.","D":"Acidose tubular renal.","E":"Síndrome de Cushing com produção ectópica de ACTH."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-27391","number":"27391","sourceNumber":"27391","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em relação ao hipoparatiroidismo primário, como encontra-se o cálcio e fósforo\nplasmático, respectivamente:","options":{"A":"baixo; alto","B":"baixo; baixo","C":"alto; baixo","D":"alto; alto","E":"todas erradas"},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-9382","number":"9382","sourceNumber":"9382","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A Síndrome poliglandular auto-imune tipo 2 caracteriza-se por:","options":{"A":"Diabetes mellitus insulino dependente, disfunção da tireoide e doença de Addison.","B":"Candidíase mucocutânea, hipoparatiroidismo e doença de Addison.","C":"Carcinoma medular da tireoide, feocromocitoma e hiperparatiroidismo.","D":"Hiperparatiroidismo, tumor de pâncreas e da hipófise.","E":"Hiperparatiroidismo, tumor de pâncreas e feocromocitoma."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-353846","number":"353846","sourceNumber":"353846","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Entre as diversas complicações que podem surgir como consequência do mau controle\nda glicemia em pacientes diabéticos, é CORRETO\nafirmar:","options":{"A":"A neuropatia diabética pode resultar em sintomas como formigamento e dormência das pernas,\npés e mãos, além de desequilíbrio e\nenfraquecimento muscular.","B":"A nefropatia diabética é caracterizada pela perda de proteína na urina e pode levar à falência\nhepática.","C":"A retinopatia diabética é uma complicação que afeta a retina do olho e pode levar à perda da\nacuidade visual.","D":"O pé diabético é uma condição que ocorre exclusivamente devido ao alto consumo de alimentos\naçucarados, levando a ulcerações nos pés que podem necessitar de amputação."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-355625","number":"355625","sourceNumber":"355625","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Exenetide e liraglutide foram incorporados recentemente ao arsenal terapêutico para o\ndiabetes mellitus. Não causam hipoglicemia, promovem perda de peso, retardam o esvaziamento\ngástrico e estimulam a secreção de insulina. Assinale a opção que indica o grupo de medicamentos\na que essas substâncias pertencem:","options":{"A":"inibidor da DPP-IV","B":"inibidores da SLGT2","C":"análogos da amilina","D":"inibidor da alfa-glicosidadse","E":"agonistas do receptor de GLP-1"},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362660","number":"362660","sourceNumber":"362660","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Em que condição o uso combinado de insulina e agonista do receptor GLP-1 é mais\nbenéfico?","options":{"A":"Quando o paciente tem peso normal.","B":"Quando o paciente necessita de perda de peso.","C":"Na presença de insuficiência renal.","D":"Na ausência de diabetes tipo 2."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-363961","number":"363961","sourceNumber":"363961","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Leia o caso clínico a seguir: Paciente com obesidade de 2° grau (IMC: 37,6 k/m2)\nassociado a diabetes mellitus tipo 2,\ndiagnosticado há 17 anos, metabolicamente descompensado\n(HbA1c: 9,2%). Procurou serviço de endocrinologia para melhor controle do diabetes e perda de\npeso. Tirzepatida, medicação recentemente aprovada pela ANVISA para tratamento do diabetes\nmellitus tipo 2, seria uma boa indicação para esse paciente, pela sua potência hipoglicemiante e\ngrande potencial de perda de peso. O fármaco citado apresenta como mecanismo de ação ser\nagonista do receptor de","options":{"A":"GLP-1.","B":"GLP-1 e GIP.","C":"glucagon, GLP-1 e GIP.","D":"GLP-1 e glucagon."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-363980","number":"363980","sourceNumber":"363980","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente de 62 anos, do sexo masculino, procura o ambulatório médico queixando-se\nde formigamento nos pés, cansaço e astenia\nprogressivos há quatro meses. Conta que está\ncomendo mais que o habitual, mas está emagrecendo; que aumentou o número de vezes que\nurina, inclusive à noite, tendo que se levantar várias vezes para ir ao banheiro, mas acha que é por\nestar com muito mais sede, bebendo quase o dobro de água que ingeria antes. Desconhece\ndoenças prévias. No exame físico, apresenta-se levemente desidratado e emagrecido, com hálito\ncetônico. Tem hipotonia muscular difusa leve, com reflexos tendinosos aquileus abolidos. As\nsensibilidades tátil e dolorosa estão reduzidas nos pés, até a altura dos tornozelos,\nsimetricamente.\nEle não apresenta outras alterações gerais ou neurológicas ao exame. Os exames fundamentais\npara o diagnóstico desse paciente são:","options":{"A":"hemograma, creatinofosfoquinase e tomografia computadorizada de crânio.","B":"urina tipo 1 (EAS), urocultura e ressonância magnética cerebral.","C":"ureia, creatinina e ressonância magnética de coluna lombossacra.","D":"glicemia de jejum, hemoglobina glicada e eletroneuromiografia dos 4 membros."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-354837","number":"354837","sourceNumber":"354837","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente, 54 anos de idade, sexo masculino, ex-tabagista (acessou há 15 anos),\ndiabético há 10 anos, com sobrepeso,\ntrabalha como operador de máquina em indústria de\nalimentos. Ao receber o diagnóstico de diabetes, iniciou uso de metformina 850 mg no café da\nmanhã e no almoço e assim se manteve. À época, foi feita uma rápida recomendação de mudança\nalimentar, a qual o paciente não aderiu (consulta 1). Aproximadamente há 5 anos, buscou novo\natendimento (consulta 2), por ter iniciado sintomatologia de polidipsia, polifagia e emagrecimento.\nOs exames revelaram HbA1C 10,1% e Glicemia de Jejum 216 mg/dL. O médico recomendou\naumento da metformina para 3 vezes ao dia e acrescentou gliclazida 30 mg no café da manhã e no\nalmoço. Novamente, foi feita uma breve recomendação de mudança de estilo de vida, também não\nfactível ao paciente. Hoje (consulta 3), ao atender este paciente, na Atenção Primária à Saúde, ele\ntraz bioquímica sérica com HbA1c 9,8% e Glicemia de Jejum 185 mg/dL. Acerca da conduta\nadotada na consulta","options":{"A":"2, foi incompleta, visto que é recomendado iniciar insulinoterapia bedtime em pacientes\nsintomáticos com HbA1C maior ou igual à 10%, contexto em que sulfonilureias são\n\ncontra-indicadas.","B":"1, foi completa, considerando que foi recomendado mudança de estilo de vida após primeira\nfalha no tratamento medicamentoso.","C":"3, deverá contemplar a prescrição de insulina NPH bedtime, na dose de 0,1 a 0,2 mg/kg, e\nsulfonilureia deverá ser suspensa.","D":"3, deverá contemplar a prescrição de insulina NPH bedtime, aproximadamente 10 a 14 UI antes\nde deitar, além de encaminhamento ao\nnutricionista."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-353813","number":"353813","sourceNumber":"353813","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O Pé Diabético está entre as complicações mais frequentes do Diabetes Mellitus (DM) e\nsuas consequências podem ser dramáticas para a vida do indivíduo, desde feridas crônicas e\ninfecções até amputações de membros inferiores. O exame periódico dos pés propicia a\nidentificação precoce e o tratamento oportuno das alterações encontradas, possibilitando, assim, a\nprevenção de um número expressivo de complicações do Pé Diabético. Sobre a classificação de\nrisco do Pé Diabético, está CORRETA a alternativa:","options":{"A":"Grau 0: neuropatia presente com ou sem deformidades (dedos em garra, dedos em martelo,\nproeminências em ante pé, Charcot).","B":"Grau 1: história de úlcera e/ou amputação.","C":"Grau 2: doença arterial periférica com ou sem neuropatia presente.","D":"Grau 3: neuropatia ausente."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362632","number":"362632","sourceNumber":"362632","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Estratégias escores de risco, para estimar a progressão da doença vascular ainda são\nlimitadas:","options":{"A":"Subestimando o risco em pacientes jovens com DM ou pacientes de diagnóstico recente, mas\ntambém superestimando o risco em indivíduos com diagnóstico há > 10 anos ou HbA1c > 9.0%.","B":"Subestimando o risco em pacientes jovens com DM, mas não em pacientes de diagnóstico\nrecente, mas também superestimando o risco em\nindivíduos com diagnóstico há > 10 anos ou\nHbA1c > 9.0%.","C":"Subestimando o risco em pacientes jovens com DM ou pacientes de diagnóstico recente, mas\ntambém subestimando o risco em indivíduos com diagnóstico há > 10 anos ou HbA1c > 9.0%.","D":"Subestimando o risco em pacientes jovens com DM ou pacientes de diagnóstico recente, mas\ntambém superestimando o risco em indivíduos com diagnóstico há > 30 anos ou HbA1c > 19.0%."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362631","number":"362631","sourceNumber":"362631","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dada a importância de se tratar a hiperglicemia, podemos indicar como correto:","options":{"A":"Na vigência de condições clínicas sejam consideradas causas secundárias de DM, e se faça o\nrastreamento de DM, tanto pelo potencial impacto no tratamento da doença de base como nos\nriscos de hiperglicemia detectada.","B":"Na vigência de condições clínicas sejam consideradas causas secundárias de DM, e se faça o\nrastreamento de DM, tanto pelo potencial impacto no tratamento da doença de base como nos\nriscos de hiperglicemia não detectada.","C":"Na vigência de condições clínicas que não sejam consideradas causas secundárias de DM, e se\nfaça o rastreamento de DM, tanto pelo potencial impacto no tratamento da doença de base como\nnos riscos de hiperglicemia não detectada.","D":"Na vigência de condições clínicas sejam consideradas causas secundárias de DM, e se faça o\nrastreamento de DM, nunca pelo potencial impacto no tratamento da doença de base como nos\nriscos de hiperglicemia não detectada."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362630","number":"362630","sourceNumber":"362630","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A falta de estudos clínicos robustos e a sub-representação do sexo feminino nos\nensaios clínicos contribuem para o escasso conhecimento sobre as Doenças Cardiovasculares\n(DCV) nas mulheres. Está correto o item:","options":{"A":"É mandatório investir em mais pesquisas sobre o papel dos hormônios sexuais no Risco\nCardiovascular (RCV) global feminino.","B":"É mandatório investir em menos pesquisas sobre o papel dos hormônios sexuais no Risco\nCardiovascular (RCV) global feminino.","C":"Não é mandatório investir em mais pesquisas sobre o papel dos hormônios sexuais no Risco\nCardiovascular (RCV) global feminino.","D":"É mandatório ignorar pesquisas sobre o papel dos hormônios sexuais no Risco Cardiovascular\n(RCV) global feminino."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362628","number":"362628","sourceNumber":"362628","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A grande vantagem de tais métodos de escores de risco:","options":{"A":"Reside na sua difícil aplicação em prática clínica, pois levam em conta dados clínicos usuais\ncomo idade, valores de exames laboratoriais e dados antropométricos.","B":"Não reside na sua fácil aplicação em prática clínica, pois levam em conta dados clínicos usuais\ncomo idade, valores de exames laboratoriais e dados antropométricos.","C":"Reside na sua fácil aplicação em prática clínica, pois levam em conta dados clínicos usuais\ncomo idade, valores de exames laboratoriais e nunca dados antropométricos.","D":"Reside na sua fácil aplicação em prática clínica, pois levam em conta dados clínicos usuais\ncomo idade, valores de exames laboratoriais e dados antropométricos."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362627","number":"362627","sourceNumber":"362627","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O uso de antipsicóticos tem sido associado ao risco de DM:","options":{"A":"Possivelmente por mecanismos ? diretos (sensibilidade e não a secreção de insulina) ou\nindiretos (ganho de peso).","B":"Possivelmente por mecanismos ? diretos (sensibilidade e secreção de insulina) ou indiretos\n(ganho de peso).","C":"Possivelmente por mecanismos ? diretos (sensibilidade e secreção de insulina) ou indiretos\n(perda de peso).","D":"Possivelmente por mecanismos ? diretos (sensibilidade e secreção de insulina), mas nunca\nindiretos (ganho de peso)."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-362626","number":"362626","sourceNumber":"362626","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Estratégias de revascularização guiadas por cintilografia de perfusão miocárdica ou\nangiotomografia de coronárias em diabéticos assintomáticos:","options":{"A":"Não demonstraram superioridade em comparação com o manejo clínico, guiado apenas por\nfatores de risco tradicionais.","B":"Demonstraram superioridade em comparação com o manejo clínico, guiado apenas por fatores\nde risco tradicionais.","C":"Não demonstraram superioridade em comparação com o manejo clínico, guiado apenas por\nfatores de risco não tradicionais.","D":"Não demonstraram superioridade em comparação com o manejo clínico, não guiado apenas por\nfatores de risco tradicionais."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-331962","number":"331962","sourceNumber":"331962","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Mulher, 58 anos, comparece em consulta com queixa de dor em uma área localizada à\ndireita do umbigo, sensível ao toque. Nega febre ou fraqueza. Antecedentes pessoais: hipertensão\narterial, diabetes tipo 2 e dislipidemia. Medicações em uso: losartana, atorvastatina, metformina,\ninsulina e aspirina. Exame físico: peso 80 kg; altura 1,6 m; PA 132x84 mmHg; FC 72 bpm; FR 12\nirpm. Exame neurológico: área de parestesia e alodínia do lado direito do abdome, que se estende\nposteriormente, mas não ultrapassa a linha média. O restante do exame neurológico é normal.\n\nExames laboratoriais: creatinina 2,1 mg/dL; hemoglobina glicosilada 7,8%. Exame de urina e\neletroforese de proteínas sérica normais. Ressonância de coluna torácica normal. A hipótese\ndiagnóstica é:","options":{"A":"Mononeuropatia diabética.","B":"Neuropatia urêmica.","C":"Neuropatia por paraproteinemia.","D":"Deficiência de vitamina b12."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-339761","number":"339761","sourceNumber":"339761","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Um paciente com obesidade grau 1 (IMC 33 kg/m2) apresenta os seguintes exames\nlaboratoriais: glicemia de jejum = 110 mg/dl, HbA1c= 6,1% e glicemia 2 horas após teste de\nsobrecarga com 75g de glicose = 160 mg/dl. Sobre o caso, assinale a alternativa CORRETA.","options":{"A":"Esse paciente tem cerca de 10% de risco de progressão para diabetes.","B":"Caso não ocorra progressão para diabetes, o paciente terá risco cardiovascular semelhante ao\ndos obesos com metabolismo glicêmico normal.","C":"O uso de metformina tem efeito profilático contra a progressão para diabetes superior ao da\nmudança de estilo de vida.","D":"O uso de liraglutida como tratamento para obesidade pode reduzir, de forma marcante, o risco\nde progressão para diabetes.","E":"A suplementação oral de selênio tem efeito benéfico na prevenção da progressão para diabetes."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334771","number":"334771","sourceNumber":"334771","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Paciente com diabetes mellitus tipo 2, apresenta elevação lenta e progressiva da\ncreatinina, mas sem apresentar aumento significativo da excreção de albumina na urina,\npermanecendo com albuminúria abaixo de 300 mg/g de creatinina. O quadro clínico apresentado:","options":{"A":"afasta o comprometimento renal pelo diabetes mellitus.","B":"ocorre em mais de 20% dos pacientes com doença renal diabética.","C":"tem como o achado mais comum na biópsia renal a necrose tubular aguda.","D":"tem no uso de bloqueadores do canal de cálcio, um contribuidor para o aparecimento desta\nnefropatia."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-331967","number":"331967","sourceNumber":"331967","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Dentre as complicações abaixo, qual a mais frequentemente encontrada no diabetes\nmellitus do tipo 2 (DM2)?","options":{"A":"Retinopatia.","B":"Nefropatia.","C":"Neuropatia periférica.","D":"Doença vascular periférica.","E":"Síndrome do túnel do carpo."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-321552","number":"321552","sourceNumber":"321552","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Leia o caso clínico. Paciente de 79 anos, com diagnóstico prévio de diabetes mellitus\ntipo 2 há 10 anos, associado a cirrose\nhepática (classe C - Child-Pugh) e doença de Alzheimer,\nPPS (Paliative Performance Scale) de 60%, em uso de insulina degludeca, 32u/dia e insulina aspart\nfiasp, aplicada após refeição de acordo com aceitação da paciente. De acordo com American\nDiabetes Association, qual o alvo de glicemia para essa paciente?","options":{"A":"HbA1c < 8%, glicemia de jejum 90-150mg/dL.","B":"HbA1c < 7%, glicemia de jejum 80-130 mg/dL.","C":"HbA1c < 6,5%, glicemia de jejum 70-140 mg/dL.","D":"HbA1c < 6,0%, glicemia de jejum 70-120 mg/dL."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337404","number":"337404","sourceNumber":"337404","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa incorreta sobre o SICI (sistema de infusão contínua de insulina).","options":{"A":"É uma alternativa para pacientes em terapia intensiva basal-bolus cm famílias motivadas.","B":"Crianças com muito medo de agulha devem evitar a SICI, pois ele necessita de muitas\naplicações diárias com agulhas.","C":"A segurança da família em manipular as bombas de insulina é fator importante a ser\nconsiderado na escolha por mudanças de terapia.","D":"A escolha do SICI deve ser sempre da equipe que acompanha o paciente em conjunto coma a\nfamília."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334118","number":"334118","sourceNumber":"334118","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a alternativa correta sobre a que se relaciona os melhores controles glicêmicos\ne adesão ao tratamento nos pacientes com\ndiabetes melito (DM) tipo 1.","options":{"A":"Pais autoritários e conflitos familiares.","B":"Coesão familiar e responsabilidades difusas quanto ao tratamento.","C":"Monitoração parental do manejo do DM tipo 1 e acordos sobre as responsabilidades no\ntratamento.","D":"Soluções de problemas de forma colaborativa e envolvimento exagerado."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-346430","number":"346430","sourceNumber":"346430","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Assinale a afirmativa correta que relaciona o caso clínico de pacientes portadores de\ndiabetes com o diagnóstico da sua complicação aguda:","options":{"A":"Mulher de 75 anos, hemiparesia à direita, com glicemia de 980 mg/dL, pH 7,45, cetonúria pouco\npositiva - Diagnóstico = Cetoacidose Diabética;","B":"Homem de 29 anos, dor abdominal e vômitos, com glicemia de 350 mg/dL, pH 7,25, bicarbonato\n15 mEq/L - Diagnóstico = Estado hiperosmolar\nhiperglicêmico;","C":"Mulher de 15 anos, torporosa, com glicemia de 520 mg/dL, pH 7,09, bicarbonato 8 mEq/L -\nDiagnóstico = Estado hiperosmolar hiperglicêmico;","D":"Homem de 45 anos, hálito cetônico, com glicemia de 410 mg/dL, pH 7,3, cetonúria muito positiva\n\n- Diagnóstico = Cetoacidose Diabética."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-342626","number":"342626","sourceNumber":"342626","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A oferta de esquemas terapêuticos com hipoglicemiantes orais ou insulinoterapia para\nindivíduos diabéticos tem aumentado a sobrevida desses pacientes. Com isso, ocorre a seguinte\nmudança no perfil epidemiológico do diabetes mellitus:","options":{"A":"diminuição da incidência e da prevalência","B":"aumento da prevalência e manutenção da incidência","C":"aumento da prevalência e diminuição da incidência","D":"manutenção da incidência e da prevalência"},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-331993","number":"331993","sourceNumber":"331993","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Diabetes mellitus (DM) é um importante e crescente problema de saúde para todos os\npaíses, independentemente do seu grau de desenvolvimento. Portanto, o conhecimento dessa\ndoença por parte da comunidade médica é muito importante. A respeito de DM, assinale a\nalternativa correta:","options":{"A":"O sobrepeso tem associação com DM tipo 1.","B":"A acantose nigricans é fator de risco para mDM tipo 1.","C":"Os autoanticorpos associados a DM tipo 1 só aparecem após os sintomas.","D":"Se a glicemia ao acaso for 200 mg/dL, o diagnóstico de DM estará estabelecido, com ou sem\nsintomas.","E":"Nos casos de glicemia de jejum 100 mg/dL e < 126 mg/dL, está estabelecido o diagnóstico de\npré-diabetes."},"answer":"E","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-321585","number":"321585","sourceNumber":"321585","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Uma jovem com diabetes mellitus não controlado é encontrada, caída, na porta de um\nrestaurante. Ao ser socorrida, recobrou a consciência e afirmou ter sentido tonturas e rubor facial\nao ingerir uma refeição. Curiosos negam movimentos involuntários. A jovem refere já ter\nexperimentado eventos semelhantes. Sua glicemia capilar é de 77 mg/dL, a pressão arterial de\n85/46mm e cetonas negativas na urina. O quadro apresentado por essa jovem foi de","options":{"A":"síndrome hiperosmolar hiperglicêmica não cetótica.","B":"cetoacidose diabética","C":"hipoglicemia e hipotensão pós-prandial.","D":"hipoglicemia convulsogênica."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-330117","number":"330117","sourceNumber":"330117","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"O procedimento mais indicado para paciente com clearance de creatinina de 10 ml/min,\n35 anos, sem comorbidade cardíaca, nem\nvascular periférica e presença de sintomas de uremia é:","options":{"A":"A realização do transplante de pâncreas isolado buscando salvar a função renal residual, uma\nvez que há presença de função renal.","B":"Apresentando-se o paciente em melhores condições, a realização de transplante duplo de rim\ncom o pâncreas antes da falência renal completa.","C":"A realização de transplante de rim cadavérico associado ao transplante de ilhotas pancreáticas.","D":"Transplante inter-vivos de pâncreas, não sendo indicado o cadavérico por ser um receptor muito\njovem."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337458","number":"337458","sourceNumber":"337458","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para indivíduos elegíveis para rastreamento pré-participação em exercícios\nprogramados, os exames a serem solicitados\ndevem ser prescritos de forma individualizada.\nPode-se afirmar que:","options":{"A":"Considera-se o eletrocardiograma de repouso como o exame básico, mas não essencial,\ndevendo ser solicitado em todos os casos pertinentes. Outros exames mais complexos, mais\ncustosos ou mais invasivos devem ser avaliados de acordo com o cenário clínico.","B":"Considera-se o eletrocardiograma de repouso como o exame básico e essencial, devendo ser\nsolicitado em todos os casos pertinentes. Outros exames mais complexos, mais custosos ou mais\ninvasivos não devem ser avaliados de acordo com o cenário clínico.","C":"Considera-se o eletrocardiograma de repouso como o exame básico e essencial, devendo ser\nsolicitado em todos os casos pertinentes. Outros exames mais complexos, mais custosos ou mais\ninvasivos devem ser avaliados de acordo com o cenário clínico.","D":"Considera-se o eletrocardiograma de esforço como o exame básico e essencial, devendo ser\nsolicitado em todos os casos pertinentes. Outros exames mais complexos, mais custosos ou mais\ninvasivos devem ser avaliados de acordo com o cenário clínico."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337461","number":"337461","sourceNumber":"337461","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para indivíduos com pré-diabetes, em risco aumentado de desenvolver DM2:","options":{"A":"50 minutos de atividade física aeróbica de moderada intensidade reduz o risco de diabetes tipo\n2.","B":"150 minutos de atividade física aeróbica de moderada intensidade não reduz o risco de diabetes\ntipo 2.","C":"150 minutos de atividade física aeróbica de moderada intensidade reduz o risco de diabetes tipo\n2.","D":"150 minutos de atividade física aeróbica de moderada intensidade reduz o risco de diabetes tipo\n1."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337463","number":"337463","sourceNumber":"337463","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Vários estudos comprovam os benefícios das terapias para a redução do colesterol em\npacientes em prevenção secundária. Sendo correto que:","options":{"A":"Nos pacientes de alto risco, o benefício não é independente dos níveis basais do LDL-C.","B":"Nos pacientes de alto risco, o benefício é dependente dos níveis basais do LDL-C.","C":"Nos pacientes de alto risco, o benefício é independente dos níveis basais do LDL-C.","D":"Nos pacientes de baixo risco, o benefício é independente dos níveis basais do LDL-C."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-337464","number":"337464","sourceNumber":"337464","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Para pessoas com DM2, está indicada:","options":{"A":"A prática de exercícios combinados resistidos (pelo menos 1 ciclo de 10 a 15 repetições de 5 ou\nmais exercícios, duas a três sessões por semana, em dias não consecutivos) e aeróbicos (no\nmínimo 150 minutos semanais de moderada ou equivalente de alta intensidade, sem permanecer\nmais do que dois dias consecutivos sem atividade) promovem reduções significativas da HbA1c.","B":"A prática de exercícios combinados resistidos (pelo menos 1 ciclo de 10 a 15 repetições de 5 ou\nmais exercícios, duas a três sessões por semana, em dias não consecutivos) e aeróbicos (no\nmínimo 150 minutos semanais de moderada ou equivalente de alta intensidade, sem permanecer\nmais do que dois dias consecutivos sem atividade) promovem reduções não significativas da\nHbA1c.","C":"A prática de exercícios combinados resistidos (pelo menos 1 ciclo de 10 a 15 repetições de 5 ou\nmais exercícios, duas a três sessões por semana, em dias não consecutivos) e aeróbicos (no\nmínimo 150 minutos semanais de moderada ou equivalente de alta intensidade, sem permanecer\nmais do que dois dias consecutivos sem atividade) promovem elevações significativas da HbA1c.","D":"A prática de exercícios combinados resistidos (pelo menos 1 ciclo de 10 a 15 repetições de 5 ou\nmais exercícios, duas a três sessões por semana, em dias não consecutivos) e não aeróbicos,\npromovem reduções significativas da HbA1c."},"answer":"A","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334174","number":"334174","sourceNumber":"334174","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Os ácidos graxos exercem ações distintas sobre a trigliceridemia:","options":{"A":"Por não modularem os fatores de transcrição envolvidos na síntese de enzimas lipogênicas\nenvolvidas na produção de ácidos graxos.","B":"Por modularem os fatores de transcrição nunca envolvidos na síntese de enzimas lipogênicas\nenvolvidas na produção de ácidos graxos.","C":"Por modularem os fatores de transcrição envolvidos na síntese de enzimas lipogênicas\nenvolvidas na produção de ácidos graxos.","D":"Por modularem os fatores de transcrição envolvidos na síntese de enzimas lipogênicas não\nenvolvidas na produção de ácidos graxos."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334176","number":"334176","sourceNumber":"334176","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"É importante ressaltar que a matriz alimentar é fator determinante no risco\nCardiovascular (CV), uma vez que, além de macronutrientes:","options":{"A":"Os alimentos nunca fornecem micronutrientes e fibras que, quando inseridos no contexto do\npadrão alimentar saudável, contribuem para desfecho CV favorável.","B":"Os alimentos fornecem micronutrientes e fibras que, quando inseridos no contexto do padrão\nalimentar saudável, contribuem para desfecho CV favorável.","C":"Os alimentos fornecem micronutrientes e fibras que, quando inseridos no contexto do padrão\nalimentar saudável, não contribuem para desfecho CV favorável.","D":"Os alimentos fornecem micronutrientes e fibras que, quando inseridos no contexto do padrão\nalimentar saudável, contribuem para desfecho CV desfavorável."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334177","number":"334177","sourceNumber":"334177","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"As modalidades de monitorização contínua da glicose (CGM) envolvem tecnologia de\nleitura da concentração de glicose no líquido intersticial. Os níveis de glicose intersticial têm\nboa\ncorrelação com os do sangue capilar. Sendo correto que:","options":{"A":"O valor da glicose intersticial pode ser obtido pela inserção subcutânea de um sensor com\nespessura de um fio de cabelo que,\ndesacoplado a um transmissor, envia um sinal elétrico para um\nleitor, para uma bomba de insulina ou para um aplicativo de celular, os quais transformam essa\ninformação numa leitura do nível de glicose.","B":"O valor da glicose intersticial não pode ser obtido pela inserção subcutânea de um sensor com\nespessura de um fio de cabelo que, acoplado a um transmissor, envia um sinal elétrico para um\nleitor, para uma bomba de insulina ou para um aplicativo de celular, os quais transformam essa\ninformação numa leitura do nível de glicose.","C":"O valor da glicose intersticial pode ser obtido pela inserção subcutânea de um sensor com\nespessura de um fio de cabelo que, acoplado\na um transmissor, envia um sinal elétrico para um\nleitor, para uma bomba de insulina, mas não para um aplicativo de celular, os quais transformam\nessa informação numa leitura do nível de glicose.","D":"O valor da glicose intersticial pode ser obtido pela inserção subcutânea de um sensor com\nespessura de um fio de cabelo que, acoplado\na um transmissor, envia um sinal elétrico para um\nleitor, para uma bomba de insulina ou para um aplicativo de celular, os quais transformam essa\ninformação numa leitura do nível de glicose."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334178","number":"334178","sourceNumber":"334178","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"A neuropatia periférica diabética NPD apresenta implicações importantes nos custos de\nsaúde pública. Assinale a alternativa correta.","options":{"A":"Evidências recentes apontam uma relação direta entre os determinantes sociais da saúde nas\nsuas três vertentes (social, econômica e\nambiental) e o risco de NPD.","B":"Evidências recentes não apontam relação direta entre os determinantes sociais da saúde e o\nrisco de NPD.","C":"Evidências recentes se opõem a uma relação direta entre os determinantes sociais da saúde\nnas suas três vertentes (social, econômica e\nambiental) e o risco de NPD.","D":"Não existem evidências recentes de uma relação direta entre os determinantes sociais da saúde\nnas suas três vertentes (social, econômica e\nambiental) e o risco de NPD."},"answer":"D","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334180","number":"334180","sourceNumber":"334180","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Na prática clínica, os melhores testes para rastreamento neuropatia periférica\ndiabética.","options":{"A":"São o biotesiômetro e nunca a sensibilidade térmica. Já, para o diagnóstico definitivo da\nneuropatia periférica diabética NPD, a SBD\nrecomenda o Escore de comprometimento Neuropático\n(ECN).","B":"São o biotesiômetro e a sensibilidade térmica. Já, para o diagnóstico definitivo da neuropatia\nperiférica diabética NPD, a SBD recomenda o Escore de comprometimento Neuropático (ECN).","C":"São o biotesiômetro e a sensibilidade térmica. Já, para o diagnóstico definitivo da neuropatia\nperiférica diabética NPD, a SBD não recomenda o\nEscore de comprometimento Neuropático (ECN).","D":"São o biotesiômetro e a sensibilidade térmica. Já, para o diagnóstico definitivo da neuropatia\nperiférica diabética NPD, a SBD veta o uso do Escore de comprometimento Neuropático (ECN)."},"answer":"B","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-2-334182","number":"334182","sourceNumber":"334182","collectionBlock":"medcurso:medcurso-endocrinologia-end-2","collectionLabel":"Medcurso · END 2","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 2","subtopic":"","stem":"Tratamento de base da neuropatia periférica diabética que interfere na história natural\nda doença, está de acordo com o seguinte item\ncorreto:","options":{"A":"Este deve abordar, além do controle glicêmico, os fatores de risco cardiovasculares, como\ncontrole da hipertensão arterial, da albuminúria, dos lípides, do peso, mas não o etilismo e\ntabagismo.","B":"Este nunca deve abordar o controle glicêmico, e sim os fatores de risco cardiovasculares, como\ncontrole da hipertensão arterial, da albuminúria, dos lípides, do peso, etilismo e tabagismo.","C":"Este deve abordar, além do controle glicêmico, os fatores de risco cardiovasculares, como\ncontrole da hipertensão arterial, da albuminúria, dos lípides, do peso, etilismo e tabagismo.","D":"Este deve abordar, além do controle glicêmico, os fatores de risco cardiovasculares, exceto\ncontrole da hipertensão arterial, da albuminúria, dos lípides, do peso, etilismo e tabagismo."},"answer":"C","source":"Endocrinologia/END 2/END 2.txt","sourceLabel":"Medcurso · END 2","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
